/* Loan Niche Encyclopedia deep extensions, part 4: guideline matrices, walkthroughs, income examples, scenarios, Q&A, AE questions, red flags, pricing notes, marketing and checklists for the Specialty borrower & situations, Commercial & business and Reverse groups plus all part-4 (d_) programs. Values marked (verify)/(lender-specific) must be confirmed against current guides. Scenario numbers are illustrative only; no rate quotes; no approval promises. Updated 2026-11. */
window.NICHE_DEEP=Object.assign(window.NICHE_DEEP||{},{
"c_dpa_ftb":{"matrix":[["First-time buyer definition","Usually no ownership interest in prior 3 years; exceptions for veterans/targeted areas (verify program)"],["Income limits","County-based; some programs count household income (verify)"],["Purchase price limits","Program/county-specific (verify)"],["Minimum FICO","Often 620-660 with program overlays (verify)"],["Max DTI","Often 45-50% with AUS (verify)"],["Homebuyer education","Usually required (online or HUD-approved counselor)"],["Assistance type","Grant, forgivable second, deferred-payment second or shared-appreciation (CA Dream For All)"],["First mortgage","FHA, VA, USDA or conventional (HFA-preferred) - program-specific"],["Funding","Reservations can close when funds run out; CA Dream For All uses lottery rounds"],["Repayment triggers","Sale, refinance, payoff or non-occupancy for deferred seconds (verify)"],["Stacking","Combining multiple assistance programs allowed only per each program's rules (verify)"],["Lender approval","Lender must be HFA-approved; brokers need an approved wholesale/correspondent channel"]],"walkthrough":["Screen income, household size, county and first-time status against current program limits","Check funding status for each candidate program that day (CalHFA, IHDA, Nevada Housing Division, Florida Housing, Arizona IDA Home Plus)","Choose first mortgage type that pairs best (FHA vs HFA conventional vs VA)","Enroll buyer in required homebuyer education early","Issue pre-approval showing DPA assumptions; brief the agent on timelines","Reserve funds as soon as there is an accepted contract","Collect all household income docs if program counts household income","Order appraisal and submit to HFA for compliance review","Clear HFA conditions (compliance approval) before closing","Explain subordinate-lien repayment terms in writing before signing","Close and fund; confirm assistance funds wired to escrow","Calendar repayment/forgiveness milestones for the client file"],"incomeExample":{"title":"Illustrative income-limit test with household income","steps":["Program counts all household income (verify program)","Borrower salary $78,000; co-borrower part-time $22,000","Adult child living at home earns $18,000 (counted for some programs, not others)","Household income = $78,000 + $22,000 + $18,000 = $118,000","County income limit (illustrative) $125,000 for household size 4","$118,000 is below $125,000, so eligible under the household test (verify current limit)"],"result":"Household income fits; the file still needs credit, DTI and price limit checks. Illustrative only."},"scenarios":[{"t":"FHA plus a CalHFA second","who":"Jasmine, 29, dental hygienist, Murrieta","situation":"Jasmine earns $84,000 and has $6,000 saved. Rent is $2,600 a month. She wants a $560,000 home near her family. Her income is under the Riverside County CalHFA limit (verify).","structure":"FHA first mortgage plus CalHFA MyHome deferred second (verify current terms)","numbers":"3.5% down $19,600; assistance up to 3.5% of price (verify)","why":"The assistance covers most of her down payment. FHA accepts her 665 score at reasonable cost. She keeps her savings for reserves and closing costs.","alternatives":"Conventional 97 with seller credits avoids lifetime FHA MIP if her score rises above 700. HomeReady with reduced MI if her income fits the area limit (verify).","watch":"The second is repaid on sale or refinance (verify). Seller credits can't duplicate assistance-funded costs."},{"t":"Dream For All shared appreciation","who":"Marco, 33, teacher, Chula Vista","situation":"Marco is a first-generation homebuyer earning $78,000. He registered for the 2026 Dream For All round and was selected in the lottery (verify round status). The assistance can cover up to 20% of the price, capped (verify). He wants a $600,000 condo.","structure":"CalHFA first mortgage plus Dream For All shared-appreciation second","numbers":"Assistance ~ $120,000 (20%); repaid with a share of appreciation (verify)","why":"20% assistance removes mortgage insurance and lowers his payment. Shared appreciation means repayment scales with value. He couldn't otherwise afford the price.","alternatives":"FHA with a smaller DPA if not selected in the lottery. A less expensive condo with conventional 3% down.","watch":"Shared appreciation can be large if values rise. The voucher has a deadline to close."},{"t":"Illinois IHDA Access","who":"Keisha, 31, nurse, Joliet","situation":"Keisha earns $72,000 and has $5,000 saved. She wants a $260,000 home near her hospital. IHDA programs pair with FHA or conventional first mortgages (verify current options).","structure":"IHDA assistance with FHA first mortgage","numbers":"Assistance per current IHDA terms","why":"Covers down payment. IHDA is statewide. Her income fits.","alternatives":"FHA alone with seller credits. Conventional 97.","watch":"IHDA income and purchase-price limits vary by county (verify). Repayment terms differ between forgivable and repayable options."},{"t":"Florida Hometown Heroes","who":"Andre, 35, firefighter, Tampa","situation":"Andre has been a Tampa firefighter for 8 years and rents an apartment. He has $9,000 saved and 700 credit. He is a first-time buyer in an eligible occupation. Hometown Heroes reopened in July 2026 with new funding (verify availability).","structure":"FHA + Hometown Heroes","numbers":"Up to $35,000 (verify)","why":"Large assistance. Eligible occupation. Funding available.","alternatives":"Florida Assist or other Florida Housing DPA if Hometown Heroes funds run out. A VA loan if he has qualifying military service, with no down payment.","watch":"Funding can be reserved within weeks of opening. The second is repaid on sale, refinance or payoff of the first mortgage (verify)."},{"t":"Arizona Home Plus","who":"Sofia, 27, Mesa","situation":"Sofia is a retail manager in Mesa earning $56,000. She has $5,000 saved and 650 credit. She wants a $380,000 home. Arizona Home Plus is open statewide (verify 2026 terms).","structure":"Home Plus with FHA","numbers":"Assistance %","why":"Statewide. Fits income. Covers down.","alternatives":"Conventional 97 with seller credits if her score rises above 680. HomeReady if her income is under the area limit (verify).","watch":"Home Plus income cap was updated in 2026 (verify). Arizona Is Home is exhausted for 2026, so don't quote it."}],"qa":[{"q":"Do I have to repay the down payment assistance?","a":"It depends on the program. Some are grants, some forgive over time, and many are deferred loans repaid when you sell, refinance or pay off the first mortgage. We give you the terms in writing before you commit."},{"q":"Who counts as a first-time buyer?","a":"Usually anyone who hasn't owned a home in the last 3 years. Veterans and buyers in targeted areas are sometimes exempt (verify)."},{"q":"Can I use assistance with a VA loan?","a":"Some programs pair with VA first mortgages and others don't (verify). VA already allows zero down, so assistance often covers closing costs."},{"q":"Is there a waiting list?","a":"Some programs, like CalHFA Dream For All, use lottery rounds. Others reserve funds first-come, first-served until money runs out."},{"q":"Does assistance change my interest rate?","a":"HFA first mortgages can price differently from standard loans. We compare total cost, not just cash to close."},{"q":"Do I need homebuyer education?","a":"Usually yes, through an online course or HUD-approved counselor. Complete it early so it doesn't delay closing."},{"q":"Can I refinance later?","a":"Yes, but a refinance may trigger repayment of a deferred second or require the agency's subordination approval. Plan for that before you choose a program."},{"q":"What if the funds run out after I'm in contract?","a":"Funds are typically reserved once you have a contract and the lender locks the program. Before that, we keep a backup program ready."},{"q":"Can I buy a condo with assistance?","a":"Usually, if the condo is eligible for the first mortgage program. FHA and conventional condo approval rules still apply."}],"aeQuestions":["Which HFA programs are you approved for in each state?","Current funding status and reservation process?","HFA compliance turn times?","Overlays on FICO/DTI?","Household income treatment?","Can brokers originate the program through you?","Comp treatment for DPA files (no term-based comp)?","Do you allow stacking with local programs?"],"redFlags":["Income near the limit with expected raises","Undisclosed household members","Funds reservation expiring","Unclear repayment understanding","Recent ownership disqualifying first-time status","Buyer relying on assistance that isn't reserved"],"pricing":"DPA first mortgages may price differently than standard loans, and the second lien has its own terms. Compare total cost of FHA-with-DPA vs conventional options. Disclose all repayment conditions. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Show options in writing.","marketing":["First-time buyer workshops with agents","Teacher/nurse/first-responder association presentations","Spanish/Tagalog/Vietnamese language events with qualified interpreters","Social posts on program openings","Partner with HUD-approved counseling agencies"],"checklist":["Program eligibility worksheet","Homebuyer education certificate","Household income docs","Tax returns (3 years for first-time status in some programs)","Reservation confirmation","HFA compliance package","Subordinate lien disclosures","Appraisal","Purchase contract","Assistance funds wire confirmation"],"updated":"2026-11"},
"c_gift_equity":{"matrix":[["Fannie Mae","Gift of equity from an acceptable donor (relative/domestic partner) can fund all or part of down payment and closing costs; primary or second home (verify B3-4.3-05)"],["Freddie Mac","Similar; gift of equity from related person allowed (verify)"],["FHA","Gift of equity from family member allowed and can satisfy 3.5% minimum required investment (verify 4000.1)"],["VA","No down payment required; gift of equity can offset costs where allowed (verify)"],["Minimum borrower contribution","None on conventional 1-unit primary when gift results in required equity (verify)"],["Gift letter","Signed by donor: amount, relationship, no repayment expected"],["Interested-party contributions","Seller credits are separate and still capped by program IPC limits"],["Appraisal","Independent appraisal must support the contract price"],["Identity of interest (FHA)","Family-member principal-residence purchases keep standard LTV; other identity-of-interest deals may be limited to 85% (verify)"],["Tax","Donor may need IRS Form 709 if the gift exceeds the annual exclusion; refer to CPA"]],"walkthrough":["Confirm relationship qualifies under the chosen program","Discuss price: market value vs. family-friendly price with gift of equity","Have parties' agent/attorney write the contract showing gift of equity explicitly","Prepare gift-of-equity letter (amount, relationship, no repayment)","Order appraisal; manage expectations if appraisal is lower","Check seller's payoff and liens so the gift amount still clears title","Make sure escrow/title reflects gift of equity on the CD as a credit to buyer","Verify buyer's remaining cash for closing costs/reserves","Underwrite; resolve any FHA identity-of-interest questions","Close; remind donor to consult CPA on gift tax filing and capital gains"],"incomeExample":{"title":"Illustrative LTV with gift of equity","steps":["Appraised value and contract price: $650,000","Gift of equity from parents: $130,000 (20%)","Loan amount: $650,000 - $130,000 = $520,000","LTV = $520,000 / $650,000 = 80%","Buyer pays closing costs (or seller credits within IPC limit)"],"result":"Buyer reaches 80% LTV with no cash down payment and avoids monthly mortgage insurance on conventional. Illustrative only."},"scenarios":[{"t":"Parents downsizing sell to daughter","who":"Emily, 30, elementary teacher, Temecula","situation":"Emily's parents are moving to a 55+ community and own their Temecula home free and clear. They want Emily to have it at a family-friendly price. The home appraises at $650,000. Emily earns $82,000 and has $20,000 saved for closing costs.","structure":"Conventional purchase with 20% gift of equity","numbers":"Value $650,000; gift $130,000; loan $520,000","why":"A $130,000 gift of equity gets her to 80% LTV with no cash down payment. Conventional at 80% has no monthly mortgage insurance. Her parents keep the rest of their equity as sale proceeds.","alternatives":"FHA with a smaller gift could work if her credit is weaker, though with FHA MIP. A seller carry-back from her parents could reduce the loan further but adds complexity.","watch":"Her parents should consult a CPA about Form 709 and capital gains. The gift must be shown as a credit on the Closing Disclosure."},{"t":"Grandmother's house via FHA","who":"Daniel, 34, warehouse supervisor, Las Vegas","situation":"Daniel is buying his grandmother's home in Las Vegas so she can move in with his aunt. His credit score is 618 and he has little savings. The home is worth $400,000. His grandmother wants to help with a gift of equity.","structure":"FHA with gift of equity covering the 3.5% investment","numbers":"Value $400,000; gift $14,000+","why":"FHA accepts his credit score. A gift of equity from a family member satisfies FHA's 3.5% minimum investment. The family-member exception keeps standard FHA financing.","alternatives":"Conventional 97 with the gift if his score rises above 640. A larger gift to reduce his loan and payment.","watch":"FHA identity-of-interest documentation must show the family relationship. His grandmother's existing liens must be paid at closing."},{"t":"Sibling transfer","who":"Ana, 40, paralegal, Chicago","situation":"Ana is buying her brother's condo in Chicago. Her brother wants to give her a 10% gift of equity. The condo is worth $350,000. She needs the condo to be warrantable for conventional financing.","structure":"Conventional purchase with gift of equity from sibling (acceptable relative - verify)","numbers":"Value $350,000; gift $35,000","why":"Siblings are eligible donors under most programs (verify). The gift lowers her down payment. A below-market family price is allowed with disclosure.","alternatives":"FHA if the condo is FHA-approved. An arm's-length purchase of a different condo.","watch":"The condo project must be warrantable or FHA-approved. Confirm siblings are acceptable donors under the chosen program (verify)."},{"t":"Parents in Florida helping son","who":"Lisa, 38, nurse, Tampa","situation":"Lisa's parents own a Tampa rental they want to transfer to her as her home. The tenant's lease ends in three months. The property is worth $380,000. Lisa earns $76,000.","structure":"Conventional with gift of equity; tenant must vacate if Lisa occupies","numbers":"Value $380,000; gift $76,000","why":"A 20% gift of equity removes PMI. Lisa will occupy it as her primary residence. Florida insurance costs are budgeted.","alternatives":"FHA with a smaller gift. Waiting until the lease ends to avoid tenant issues.","watch":"The tenant must vacate before Lisa occupies. Florida homeowners and flood insurance must fit her budget."},{"t":"Investment-property transfer","who":"Mark, 45, contractor, Phoenix","situation":"Mark's parents want to sell him a rental property he would keep as an investment. They assumed a gift of equity would work. Agency rules generally don't allow it for investment purchases (verify).","structure":"Gift of equity usually not allowed for investment purchases - use normal down payment (verify)","numbers":"Value $450,000; 15-25% down needed","why":"Explaining the rule honestly prevents an occupancy misstatement. He can still buy with a standard down payment. DSCR or conventional investment loans fit.","alternatives":"A DSCR loan qualifying on rent. A seller carry-back from his parents for part of the price.","watch":"Never mislabel occupancy to use a gift of equity. Investment loans require normal down payment sourcing."}],"qa":[{"q":"Is a gift of equity taxable?","a":"The donor may need to file a gift tax return if the gift exceeds the annual exclusion, though actual tax is rare. Refer the donor to a CPA."},{"q":"Can a gift of equity cover closing costs too?","a":"Often yes on agency loans. It must stay within program and interested-party contribution rules (verify)."},{"q":"Who can give a gift of equity?","a":"Relatives as defined by the program. Check eligibility before writing the contract."},{"q":"Does the price have to equal appraised value?","a":"The price is usually set at value with the gift shown as a credit. The loan is based on the lower of price or appraised value."},{"q":"Can a gift of equity eliminate PMI?","a":"If the gift brings you to 20% equity on a conventional loan, monthly mortgage insurance isn't required."},{"q":"Can it be used on an investment property?","a":"Generally no on agency loans (verify). It's meant for primary and some second-home purchases."},{"q":"What if the appraisal comes in low?","a":"The gift amount or price may need to change. The loan is based on the lower value."},{"q":"Do the sellers still need to pay off their mortgage?","a":"Yes. Their liens must be paid at closing, so the gift can't exceed their equity."}],"aeQuestions":["Which relationships qualify for gift of equity under your overlays?","Can gift of equity cover closing costs and prepaids?","FHA identity-of-interest documentation you require?","Do you allow gift of equity from an estate or trust?","Do you need donor ability-to-give documentation?","Any LTV overlays for family sales?","How should escrow show it on the CD?","Comp plan (no term-based comp)?"],"redFlags":["Donor not an eligible relative","Cash back to buyer or side payments","Contract price inflated above value","Seller liens exceed what remains after gift","Occupancy story inconsistent","Pressure from family members on elderly seller"],"pricing":"Gift of equity can lower LTV, which may improve pricing and remove mortgage insurance. Compare conventional at 80% LTV against FHA options with smaller gifts. Show the effect on cash to close and monthly payment. Clarify that the seller nets less by the amount of the gift. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide a written comparison.","marketing":["Estate planning attorneys and CPAs (education, not paid referrals)","Senior downsizing specialists","Articles: 'How to buy a family home the right way'","Workshops for parents helping adult children","Past-client families"],"checklist":["Gift of equity letter","Purchase contract showing gift","Relationship verification","Appraisal","Seller's payoff statements","Title commitment","CD review with escrow","Borrower income and asset docs","Credit report","Homeowners insurance","CPA referral note for donor"],"updated":"2026-11"},
"c_divorce_buyout":{"matrix":[["Fannie Mae","Equity buyout under a divorce/separation agreement may be treated as limited cash-out when requirements are met (verify B2-1.3-02)"],["Freddie Mac","Special-purpose cash-out refinance for buyout of co-owner per divorce/legal separation (verify 4301.5)"],["FHA","Cash-out or rate/term options; buyouts documented by decree (verify 4000.1)"],["VA","IRRRL can't remove veteran; cash-out refinance can (verify)"],["Seasoning","Property awarded through divorce often exempt from cash-out seasoning (verify)"],["Support income","Typically 3 years continuance; receipt history often 6 months (verify by program)"],["Support paid","Alimony may be deducted from income or treated as liability per program (verify)"],["Decree","Final decree or court-approved agreement typically required"],["Credit","Joint debts assigned to ex-spouse can be excluded with decree"],["Title","Ex-spouse quitclaim recorded at or after closing"]],"walkthrough":["Learn settlement status and timeline from client and attorney","Read draft agreement: buyout amount, support terms, debt allocation","Determine program: Fannie LCOR-type buyout, Freddie special-purpose, FHA or VA","Calculate qualifying income including support if eligible","Confirm support receipt history and continuance","Exclude joint debts assigned to ex-spouse with decree","Pre-qualify before final decree so client negotiates realistically","Order appraisal; confirm buyout fits LTV","Coordinate quitclaim timing with title (not before approval)","Close and fund buyout to ex-spouse via escrow"],"incomeExample":{"title":"Illustrative support income qualification","steps":["Borrower salary $72,000/yr = $6,000/mo","Child support $1,500/mo, 6 months received, continues 4+ years","Alimony $1,000/mo, continues 5 years","Total qualifying income = $6,000 + $1,500 + $1,000 = $8,500/mo","New PITI $3,400; other debts $400","DTI = $3,800 / $8,500 = 44.7%"],"result":"Support income makes the buyout feasible within typical DTI limits (verify program). Illustrative."},"scenarios":[{"t":"Keep the kids in their school","who":"Rachel, 41, HR manager, Temecula","situation":"Rachel and her ex-husband agreed she keeps their $750,000 home and pays him $150,000 for his equity. The existing loan is $380,000. She earns $96,000 and will receive $1,500 a month in child support. Their decree is final.","structure":"Fannie Mae equity buyout under the decree, treated as limited cash-out if requirements are met (verify)","numbers":"New loan ~ $545,000 incl. costs; LTV ~ 73%","why":"Limited cash-out treatment may price better than a standard cash-out. Child support can count with receipt history and 3-year continuance. Her children stay in the same school.","alternatives":"Sell and split the equity if the payment is too high. An FHA cash-out if her credit took a hit during the divorce.","watch":"Support receipt history may need 6 months (verify program). Joint debts assigned to her ex must be excluded with decree language."},{"t":"Veteran keeps the VA home","who":"Mike, 45, Navy retiree, Oceanside","situation":"Mike and his ex-wife hold a VA loan together. The decree awards him the home and requires her removal from the loan within 6 months. The home is worth $700,000. He receives VA disability compensation.","structure":"VA cash-out refinance in Mike's name, paying her equity share","numbers":"Value $700,000; payoff $350,000; buyout $100,000","why":"VA allows high LTV cash-out for veterans. His disability exempts him from the funding fee. VA pricing is competitive.","alternatives":"A conventional cash-out if he wants to restore VA entitlement. Keep the existing loan if the decree allows, though she stays liable.","watch":"The decree deadline must fit lender timelines. The quitclaim should record at closing."},{"t":"Florida decree with a deadline","who":"Teresa, 50, school administrator, Orlando","situation":"Teresa's decree requires her to refinance within 6 months or sell. Her credit dropped during the divorce to 640. The home is worth $400,000 with a $200,000 loan. She will pay her ex $60,000.","structure":"FHA cash-out refinance","numbers":"New loan ~ $265,000; LTV ~ 66%","why":"FHA tolerates her current score better. The LTV is well within limits. Meeting the deadline avoids a forced sale.","alternatives":"Conventional if her score recovers above 680. Ask the court for an extension.","watch":"The 6-month decree deadline must allow time for appraisal and underwriting. Her credit score may require FHA pricing until it recovers."},{"t":"Paying alimony while keeping the home","who":"Dan, 48, engineer, Chandler AZ","situation":"Dan keeps the home and pays his ex-wife $2,000 a month in alimony for 5 years. His salary is $160,000. The buyout is $120,000. Alimony counts against his qualifying.","structure":"Conventional with alimony deducted from income or treated as a debt per program (verify)","numbers":"Alimony $2,000/mo","why":"He keeps the home. His income supports the payment. Program rules decide how alimony is treated.","alternatives":"Sell and rent. Negotiate a lower buyout.","watch":"Alimony paid reduces his qualifying income or counts as a debt depending on program (verify). DTI must still fit after the buyout."},{"t":"Decree not yet final in Illinois","who":"Priya, 39, Naperville","situation":"Priya's divorce is in negotiation. She wants to know what buyout she can afford. The decree isn't final.","structure":"Pre-approval; close after decree","numbers":"Value $500,000","why":"Planning helps negotiation. Lenders need the decree to close. Timing is key.","alternatives":"Wait. Sell.","watch":"Don't sign a quitclaim before the refinance is approved. The final decree must include buyout terms the lender can rely on."}],"qa":[{"q":"Can I count child support or alimony as income?","a":"Usually yes when the decree documents it, you've received it consistently (often 6 months, program-specific), and it will continue at least 3 years from closing. Bank statements show receipt."},{"q":"Do I need a final divorce decree to refinance?","a":"Most programs require a final decree or court-approved settlement to close. We can pre-qualify you before it's final so you negotiate with real numbers."},{"q":"Can my ex stay on the loan after the divorce?","a":"The refinance normally removes them. If you keep the old loan, both of you stay liable even though the decree assigns the home to you."},{"q":"Is paying my ex's equity a cash-out refinance?","a":"It depends on the program. Some agency rules treat a decree-based buyout as limited cash-out, while others treat it as cash-out with different pricing and LTV limits (verify)."},{"q":"What about credit cards and car loans in both names?","a":"Debts assigned to your ex in the decree can usually be excluded from your ratios. Late payments your ex makes on joint accounts can still hurt your credit, so close or refinance them when possible."},{"q":"When should my ex sign the quitclaim deed?","a":"At closing through escrow, not before approval. Signing early can complicate title and the transaction type."},{"q":"Can I keep my VA loan?","a":"A veteran can refinance with VA cash-out to remove a non-veteran ex-spouse. A non-veteran keeping a VA loan usually needs a different program (verify)."},{"q":"How long does the process take?","a":"Typically 30-45 days once the decree and documents are ready. Build in time if your decree sets a deadline."},{"q":"What if the support income just started?","a":"Some programs require a receipt history before it counts. We may wait a few months or qualify you without it."}],"aeQuestions":["Do you treat a decree-based equity buyout as limited cash-out, and what documentation triggers it?","What support-income receipt history do you require (by program)?","Do you accept a marital settlement agreement before the final decree?","Is a property awarded in divorce exempt from cash-out seasoning under your overlays?","How do you exclude joint debts assigned to the ex-spouse?","Do you allow alimony paid to be treated as a reduction of income rather than a liability?","VA cash-out removing a non-veteran ex-spouse: any overlays?","Turn times and appraisal waiver availability for buyouts?","Broker comp plan details (no term-based comp)?"],"redFlags":["Decree not final","Support not received","Early quitclaim","Undisclosed debts","Hostile ex-spouse","Unrealistic buyout amount"],"pricing":"A buyout treated as limited cash-out can price better and allow higher LTV than a standard cash-out refinance, so the structure matters. Compare agency, FHA and VA options on cash to close, payment and total cost over the expected holding period. Explain that the buyout amount is set by the settlement, not the lender. Coordinate closing deadlines in the decree with realistic lock periods. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide every option in a written comparison.","marketing":["CE-style workshops for family law attorneys and mediators on refinance timing","Partner with Certified Divorce Financial Analysts (education, no referral fees)","Guide: 'Keeping the house after divorce' in English and Spanish","Check-ins with past clients after life changes","Local co-parenting and single-parent support groups (sensitive, education-only)"],"checklist":["Final decree or court-approved settlement","Marital settlement agreement with buyout language","Proof of support receipt (bank statements)","Income documentation","Credit report with joint-debt review","Appraisal","Title report and vesting","Quitclaim deed timing with escrow","Existing mortgage statement","Homeowners insurance","Payoff/buyout instructions to escrow"],"updated":"2026-11"},
"c_nonocc_coborrower":{"matrix":[["Fannie Mae","Non-occupant co-borrower allowed on 1-unit primary; DU uses blended ratios; manual underwrite limits may apply (verify)"],["Freddie Mac","Allowed; LPA evaluates; occupant-borrower contribution rules (verify)"],["FHA","Non-occupant co-borrower allowed; family member allows max financing on 1-unit; non-family limited to 75% LTV (verify 4000.1)"],["VA","Non-veteran non-occupant co-borrower generally requires joint loan guaranty rules; limited (verify)"],["Max LTV","Program-specific; FHA family 96.5% (verify)"],["Occupant credit","Occupant borrower must meet credit; all borrowers' scores used"],["Title","Non-occupant usually on title"],["Liability","Co-borrower fully liable; affects their DTI on future loans"]],"walkthrough":["Confirm in writing who will occupy the home and who is co-signing; occupancy drives which rules apply","Check the relationship against the FHA 'family member' definition (parent, child, sibling, grandparent, in-law, domestic partner and others - verify 4000.1) because it changes FHA max LTV","Pull credit on every borrower; note the lowest representative score, which usually drives pricing and MI","Run DTI two ways: blended (all borrowers) and occupant-only, so you know whether a manual underwrite or lender overlay will bite","Collect the co-borrower's full income, asset and housing-expense documentation, including their own mortgage statement and property taxes","Explain liability to the co-borrower separately and in writing: they are 100% liable, the debt hits their DTI, and late payments hit their credit","Choose program: Fannie DU (blended ratio), Freddie LPA, or FHA (family non-occupant at standard LTV; non-family limited - verify)","Confirm occupant-borrower contribution or reserve rules for the chosen program (lender-specific overlays)","Decide title vesting with the family's attorney: on title vs loan-only, joint tenancy vs tenancy in common","Submit to AUS; resolve conditions on both households' documentation","Close with all borrowers signing; the co-borrower can sign via mail-away or POA where permitted","Calendar a 12-24 month review to see if the occupant can refinance the co-borrower off"],"incomeExample":{"title":"Illustrative blended DTI","steps":["Occupant income $4,500/mo; debts $500","Co-borrower (parent) income $8,000/mo; debts $2,800 incl. own mortgage","New PITI $3,200","Blended DTI = ($3,200 + $500 + $2,800) / ($4,500 + $8,000) = $6,500 / $12,500 = 52%","Occupant-only DTI would be ($3,200 + $500) / $4,500 = 82%"],"result":"Blended ratios may qualify through AUS when occupant alone cannot (verify program limits/overlays). Illustrative."},"scenarios":[{"t":"Parent helps an early-career engineer","who":"Kevin, 27, junior civil engineer, Temecula","situation":"Kevin earns $78,000 and has 6% saved, but his DTI on a $550,000 townhome is about 58% on his own. His mother, a school administrator in Murrieta, earns $110,000 and has a modest mortgage of her own. She is willing to co-sign but will not live in the home. Kevin's credit score is 742 and hers is 768.","structure":"Conventional 95% LTV with mother as non-occupant co-borrower; DU blended ratios","numbers":"Price $550,000; loan $522,500; blended DTI ~41% (illustrative)","why":"Blending the mother's income brings ratios within DU limits. Both scores are strong, so pricing and MI stay reasonable. Kevin builds equity now rather than renting for another three years while his salary grows.","alternatives":"FHA with mother as family non-occupant co-borrower at 96.5% LTV, useful if a score drops, but MIP lasts longer. Waiting 18-24 months for a raise and qualifying alone avoids tying up the mother's credit capacity.","watch":"The new loan counts in the mother's DTI, which may block her own refinance or second-home plans. Confirm DU accepts the blended ratio without a lender overlay requiring Kevin alone to be under 43-45%."},{"t":"Brother co-signs an FHA purchase","who":"Maria, 31, medical assistant, North Las Vegas","situation":"Maria has 612 credit after past medical bills and earns $46,000. Her brother, an electrician, earns $92,000 and rents. She has $14,000 saved toward a $380,000 home. Conventional pricing at her score would be expensive.","structure":"FHA with brother as family non-occupant co-borrower","numbers":"3.5% down $13,300; loan ~$373,000 with UFMIP","why":"FHA's family non-occupant rule keeps maximum financing. FHA tolerates her score better than conventional pricing does. Her brother's rent payment counts in his DTI, but his income easily absorbs it.","alternatives":"Conventional with brother co-signing could work if her score rises to 640+, lowering long-term MI cost. A Nevada DPA program could reduce cash needed if household income fits limits (verify).","watch":"Document the sibling relationship for FHA. The brother's future home purchase will count this loan unless Maria pays it for 12 months from her own account and the lender accepts that evidence (verify)."},{"t":"Friend co-signer and FHA limits","who":"Jared, 29, barista and part-time student, Chicago","situation":"Jared's friend from college offered to co-sign on a $300,000 condo. Jared earns $38,000 and the friend earns $120,000. They are not related. FHA treats non-family non-occupant co-borrowers differently.","structure":"Conventional with non-occupant co-borrower, or FHA limited to 75% LTV for non-family (verify)","numbers":"Conventional 5% down $15,000 vs FHA 25% down $75,000","why":"Conventional does not impose FHA's non-family LTV restriction. The friend's income lets DU approve blended ratios. Showing both paths makes the real cost of the relationship structure clear.","alternatives":"Jared could buy a lower-priced condo alone with IHDA assistance (verify eligibility), avoiding shared liability. He could also add a family member instead of a friend to use FHA at standard LTV.","watch":"Shared liability between friends is risky. Recommend a written agreement on payments and exit. The condo must be warrantable for conventional financing."},{"t":"Retired parent co-signs with pension income","who":"Lily, 26, new-grad RN, Phoenix","situation":"Lily has only 7 months of nursing pay after graduating. Her father, 66, is retired with a $4,200/month pension and $2,100 Social Security. He lives in Tucson and owns his home free and clear. They want a $400,000 home near her hospital.","structure":"Conventional with father as non-occupant co-borrower; Lily's new-grad income allowed with diploma/transcripts (verify)","numbers":"Father's qualifying income with SS gross-up ~ $6,700/mo (verify)","why":"Pension and Social Security are stable, documented income. Lily's education counts toward her two-year history. The father has no housing payment, so blended DTI is low.","alternatives":"FHA family co-borrower at 3.5% down if her credit is thinner. Lily could also wait one year to qualify alone, but Phoenix rents would cost her about the same as the payment.","watch":"Age cannot be considered against the father; document continuance as for any applicant. If he later needs a reverse mortgage, this co-signed debt may matter to his financial assessment."},{"t":"Graduate student with parental support","who":"Omar, 25, PhD student with stipend, Tampa","situation":"Omar's university stipend is $32,000 for three more years. His parents in Orlando earn $180,000 combined and want him to stop renting. They plan for him to rent two bedrooms to classmates. The lender cannot count that future rent for a single-family home.","structure":"Conventional with parents as non-occupant co-borrowers; stipend counted with documented continuance (verify)","numbers":"Price $320,000; 5% down from parental gift","why":"The parents' income carries the qualification. Omar's stipend has documented continuance through his program. A gift letter covers the down payment cleanly.","alternatives":"A 2-unit property would let rental income count for Omar, but prices near campus may be higher. Parents could buy as a second home, but Omar's occupancy as a child of the owners may not meet second-home rules.","watch":"Stipend continuance must be at least 3 years from closing (verify). Roommate rent cannot be used to qualify unless under HomeReady boarder rules with history."}],"qa":[{"q":"Does my co-signer have to live in the home?","a":"No. A non-occupant co-borrower signs the note and usually the deed of trust but lives elsewhere. They are fully liable for the loan even though they don't live there."},{"q":"How will co-signing affect my parent's credit?","a":"The mortgage appears on their credit report and the full payment counts in their debt-to-income ratio for future loans. Late payments by you would lower their score. Some lenders will exclude the debt later if you can show 12 months of payments from your own account (verify)."},{"q":"Can my co-signer be removed later?","a":"Usually only by refinancing into your name alone once you qualify. Lenders rarely release a borrower from an existing loan. We can review your numbers each year to see when that's possible."},{"q":"Does my co-signer have to be family?","a":"Not for conventional loans. FHA gives better terms when the co-borrower is a family member; non-family non-occupant co-borrowers can be limited to 75% LTV (verify)."},{"q":"Does my co-signer have to be on title?","a":"Most lenders require borrowers on the note to have an ownership interest or sign the security instrument; rules vary. Vesting has legal and tax effects, so an attorney should advise."},{"q":"How is our income combined?","a":"Fannie Mae's DU and Freddie Mac's LPA typically evaluate a blended ratio using everyone's income and debts. Some lenders also cap the occupant's own ratio as an overlay, so we check both."},{"q":"What if my co-signer already has a mortgage?","a":"Their full housing payment counts in the blended calculation. That's often what decides whether a co-signer helps enough."},{"q":"Can a co-signer help on an investment property?","a":"Non-occupant co-borrower rules are designed for primary residences. Investment properties are underwritten differently, and everyone on the loan is simply a borrower."},{"q":"Whose credit score sets my pricing?","a":"Usually the lowest representative score among the borrowers, depending on the program. A co-signer with a higher score doesn't raise a low score."}],"aeQuestions":["Blended ratio limits/overlays?","Manual underwriting rules?","FHA family definition documentation?","Non-family co-borrower LTV?","Occupant borrower minimum contribution?","Credit score used?","Turn times?","Comp plan?"],"redFlags":["Co-signer seems pressured, confused or is elderly and dependent on the occupant","Co-signer is actually planning to live there part-time (occupancy story shifting)","Occupant-only DTI is extreme (70%+) with no path to qualify alone","Co-signer's own DTI is near limits and a rate or tax change would push it over","Undisclosed debts or a pending home purchase by the co-signer","Gift and co-signer are the same person but documentation is inconsistent","FHA family relationship cannot be documented","Co-borrower intends to quitclaim off title right after closing"],"pricing":"Pricing typically uses the lowest qualifying score among borrowers (program-specific). Compare FHA family and conventional options. Explain liability and MI implications. Disclose all costs. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written options.","marketing":["Parents' workshops: helping kids buy","Social content on co-signing basics","Partner with financial planners","College alumni groups","Past clients with adult children"],"checklist":["Occupancy certification","Co-borrower income docs","Co-borrower credit","Relationship documentation (FHA)","Purchase contract","Appraisal","Title vesting instructions","Liability disclosure","Insurance","Assets"],"updated":"2026-11"},
"c_retirees_assets":{"matrix":[["Social Security","Award letter and receipt; gross up non-taxable portion (Fannie up to 25% - verify; FHA up to 15% or actual tax rate - verify)"],["Pension/annuity","Award letter; 3-year continuance if term-limited (verify)"],["Retirement distributions (IRA/401k)","3-year continuance from assets; documented distribution (verify)"],["Employment-related assets as income (Fannie)","Net documented value / loan term months, subject to rules (verify B3-3.1-09)"],["Freddie asset-based income","Similar calculation rules (verify)"],["Non-QM asset depletion","Lender-specific formulas (e.g., assets / 60-120 months)"],["Age","Cannot be considered negatively (ECOA)"],["Reserves","Program-specific"],["RMDs","Required minimum distributions may count with documentation (verify)"],["Reverse mortgage alternative","HECM for purchase or refinance"]],"walkthrough":["Inventory every income source: Social Security, pensions, annuities, military retirement, VA disability, IRA/401(k) distributions, rental income","Collect award letters and two months of deposits for each","Determine taxable vs non-taxable portions and apply the program's gross-up","For retirement-account distributions, confirm 3-year continuance from current balances (verify program)","If income is short, run Fannie/Freddie asset-based income calculations","If still short, price non-QM asset depletion as a comparison","Compare against HECM for Purchase or a HECM refinance where goals fit","Issue pre-approval; explain reserve requirements","Underwrite; update statements if markets move","Close; suggest coordinating draws with financial planner (no investment advice)"],"incomeExample":{"title":"Illustrative retiree income","steps":["Social Security $3,000/mo (85% taxable; 15% grossed up 25% = +$112)","Pension $2,500/mo","IRA distributions $2,000/mo with 3+ years remaining","Total qualifying ~ $7,612/mo","PITI $2,800 + debts $300 = $3,100; DTI ~ 41%"],"result":"Retiree qualifies on combined income. Illustrative."},"scenarios":[{"t":"Downsizing on Social Security and pension","who":"Bob, 68, retired postal supervisor, and Jan, 67, Escondido","situation":"Bob and Jan are selling their $1.1M two-story home in Escondido. They want a $650,000 single-level home nearby. Their combined Social Security is $4,100 a month and Bob's pension is $2,800. They want to keep cash in reserve.","structure":"Conventional purchase with 40% down from sale proceeds","numbers":"Income: SS $4,100/mo combined, pension $2,800/mo; PITI ~ $2,700","why":"Their documented retirement income supports a modest mortgage. A 40% down payment keeps the payment around $2,700. They retain significant cash from the sale.","alternatives":"HECM for Purchase would remove the monthly payment but require a larger down payment. Cash purchase would use most of their sale proceeds.","watch":"Gross-up applies only to the non-taxable portion of Social Security. Their sale must close before or simultaneously with the purchase."},{"t":"IRA distributions as income","who":"Helen, 72, retired accountant, Henderson NV","situation":"Helen has a $900,000 IRA and takes $4,000 a month. She is buying a $500,000 condo in Henderson with 30% down. Her Social Security is $2,400. Her IRA withdrawals are already established.","structure":"Distribution income documented; 3-year continuance from balance","numbers":"$4,000 x 36 = $144,000, well below balance","why":"Her distribution can last well beyond three years. Agency pricing applies. She avoids selling investments for a larger down payment.","alternatives":"Asset depletion if distributions aren't set up. A HECM for Purchase.","watch":"Distributions must be established and documented before closing (verify). The IRA balance must support at least 3 years of withdrawals."},{"t":"Asset-rich, income-light","who":"Stan, 66, sold his business, Scottsdale","situation":"Stan sold his business and has a $2M brokerage account. He has little monthly income. He wants a $900,000 home in Scottsdale. He'd rather not sell investments for a cash purchase.","structure":"Fannie employment-related assets income or non-QM asset depletion","numbers":"Illustrative: $2M x 70% eligible / 360 = ~$3,900/mo (verify formula)","why":"Asset-based income converts his wealth into qualifying income. He keeps investments working. Agency or non-QM options both may work.","alternatives":"A larger down payment from investments. A cash purchase.","watch":"Lenders discount stocks for volatility, reducing eligible assets. Asset depletion formulas differ between agency and non-QM."},{"t":"Navy retiree with disability","who":"Ray, 62, retired Navy Chief, Oceanside","situation":"Ray retired from the Navy after 30 years. His military retirement is $3,600 and VA disability is $2,200 a month. He's buying a $650,000 home in Oceanside.","structure":"VA purchase; disability exempts funding fee","numbers":"Non-taxable VA disability grossed up per VA rules (verify)","why":"VA allows zero down and no funding fee with disability. Both incomes count. Residual income should be strong.","alternatives":"Conventional with a down payment. FHA.","watch":"VA residual income must meet the West-region table. VA disability gross-up follows lender policy (verify)."},{"t":"Widow on survivor benefits","who":"Diane, 75, Tampa","situation":"Diane is a widow with survivor pension and Social Security. She wants a $350,000 condo in Tampa. She has 30% down from her prior home.","structure":"Conventional with reserves","numbers":"Income $4,800/mo; price $350,000; 30% down","why":"Survivor benefits are lifetime income. A modest loan fits. She keeps reserves.","alternatives":"HECM for Purchase. Cash.","watch":"Florida SIRS-related condo assessments may be coming (verify). Insurance premiums must fit her fixed income."}],"qa":[{"q":"Can I qualify for a mortgage without a job?","a":"Yes. Social Security, pensions, annuities, retirement distributions and even assets can be qualifying income when documented."},{"q":"Is my Social Security grossed up?","a":"The non-taxable portion can be grossed up by the program's allowed percentage, which raises qualifying income. Fannie Mae allows up to 25% and FHA up to 15% or the actual tax rate (verify)."},{"q":"How long must my IRA distributions continue?","a":"Generally at least three years from closing, based on the account balance (verify program). Distributions often need to be set up before closing."},{"q":"Can my investments count even if I don't withdraw from them?","a":"Agency asset-based income rules and non-QM asset depletion can convert assets into qualifying income without actual withdrawals. Each program has its own formula."},{"q":"Will my age affect approval?","a":"No. Lenders can't hold age against you. We document income continuance the same way as for any applicant."},{"q":"Should I consider a reverse mortgage instead?","a":"Sometimes. We compare a traditional loan with a HECM for Purchase or HECM refinance so you can choose."},{"q":"How many months of reserves do I need?","a":"It depends on the program and loan size. Retirement accounts usually count at a discounted value."},{"q":"Can I use required minimum distributions?","a":"Often yes, documented with statements and evidence of continuance (verify)."},{"q":"Will a market drop hurt my approval?","a":"Possibly, if statements are updated before closing and balances fall. Leave a cushion above the minimum."}],"aeQuestions":["What gross-up percentage do you apply to non-taxable Social Security and VA disability?","Do you require distributions to be established before application or just before closing?","Which asset-based income method do you use (Fannie employment-related assets vs. your own)?","Haircuts on stocks and retirement accounts for reserves?","Non-QM asset depletion: divisor, eligible assets, minimum FICO?","Do you accept RMDs as continuing income?","Any overlays for borrowers on fixed incomes?","Turn times and statement-refresh rules?","Broker comp plan details (no term-based comp)?"],"redFlags":["Distribution plan would deplete assets quickly","Income relies on an annuity with a near-term end date","Adult children directing the transaction","Signs of cognitive decline or confusion","Undisclosed debts or co-signed loans for family","Budget ignores insurance and HOA increases"],"pricing":"Agency loans using documented retirement income usually price better than non-QM asset depletion, so exhaust agency options first. Show the trade-off between larger down payment and keeping liquidity. Compare to a HECM for Purchase where appropriate. Clarify that we provide no investment advice and coordinate with the client's planner. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Give written side-by-side comparisons.","marketing":["Workshops with retirement planners on 'mortgages in retirement'","Military retiree associations and Fleet Reserve events","55+ community sales offices","Articles on downsizing math","Past-client annual reviews"],"checklist":["Social Security award letter","Pension/annuity award letters","Two months of deposit statements","Retirement account statements (2 months)","Distribution set-up confirmation","Asset-income worksheet","Tax returns (if required)","Credit report","Appraisal","Homeowners insurance","Property tax estimates"],"updated":"2026-11"},
"c_selfemp_new":{"matrix":[["Fannie Mae","Self-employment 12-24 months may be acceptable with prior 2 years in same field/related occupation and DU approval (verify B3-3.2)"],["Freddie Mac","Less than 2 years but at least 12 months with prior related history (verify)"],["FHA","1-2 years self-employment acceptable with 2 prior years of related employment/education (verify 4000.1)"],["VA","Generally 2 years; less with strong related history (verify)"],["Under 12 months","Usually non-agency; non-QM bank-statement programs may allow 12 months of statements with 2-year business existence (lender-specific)"],["Tax returns","1-2 years personal and business returns per AUS"],["P&L","YTD P&L may be required (lender-specific)"],["Business verification","CPA letter, license or internet listing within days of closing"],["Income trend","Stable or increasing required"],["DTI","Program limits"]],"walkthrough":["Build a work-history timeline: prior W-2 employer, title, dates, then business start date (entity filing or first invoice)","Decide whether the business is in the same or a related field as the prior job; this is what makes 12-24 months acceptable for agency (verify)","Collect every filed personal return since the business started, plus business returns if it is an S-corp or partnership","Calculate income on the lender's worksheet (Fannie 1084 / Freddie 91 / FHA method), adding back depreciation, depletion and business-use-of-home","Run DU/LPA and read the findings: one-year return eligibility, YTD P&L requests, reserve requirements","If income is declining year-over-year, use the lower figure and prepare a written explanation","If agency fails, price a 12- or 24-month bank-statement non-QM as a comparison (many need 2 years of business existence)","Obtain a CPA letter or business license and an online presence to verify the business","Issue pre-approval with conditions listed (YTD P&L, verification of business within 10-30 days of closing - lender-specific)","Coach the borrower not to change entity type, open new business debt or switch to W-2 before closing","Re-verify the business just before closing and close"],"incomeExample":{"title":"Illustrative 1-year self-employed calculation","steps":["Prior 4 years W-2 as an electrician at $85,000","2025 Schedule C net profit $96,000","Add back depreciation $8,000 and home-office use $2,000","Qualifying income = $106,000 / 12 = $8,833/mo","PITI $3,300 + debts $600 = $3,900; DTI 44%"],"result":"Could qualify with one year of returns if AUS allows and history is in the same trade (verify). Illustrative."},"scenarios":[{"t":"Electrician goes out on his own","who":"Tony, 36, licensed electrical contractor, Temecula","situation":"Tony worked six years as a W-2 electrician before opening his own shop 14 months ago. His 2025 Schedule C shows $96,000 net plus $8,000 of depreciation. He wants a $640,000 home in Murrieta with 10% down. His bank deposits suggest 2026 is running higher.","structure":"Conventional with one year of returns, relying on DU approval and prior same-trade history","numbers":"Qualifying ~ $8,833/mo; PITI ~ $4,300; DTI ~ 49% with car payment (illustrative)","why":"Agency guidelines can accept 12-24 months of self-employment when prior experience is in the same line of work. Depreciation add-back increases usable income. Agency pricing is much lower than a bank-statement loan.","alternatives":"A 12-month bank-statement non-QM would use his higher 2026 deposits but costs more and may need 2 years of business existence. Waiting until his 2026 return is filed gives a two-year average and more lenders.","watch":"DU must actually return the one-year allowance; if it asks for two years, the file stalls. A big YTD drop on the P&L would reduce income."},{"t":"Staff nurse becomes a 1099 travel nurse","who":"Gina, 31, RN, San Diego","situation":"Gina was a staff RN for five years, then switched to 1099 travel contracts 18 months ago. Her 1099 income is $120,000 but she deducts travel, housing and licensing costs. Her net Schedule C is $84,000. She wants an FHA loan on a $520,000 condo.","structure":"FHA treating 1099 nursing as self-employment with prior W-2 nursing history","numbers":"Net $84,000 = $7,000/mo","why":"FHA accepts 1-2 years of self-employment when the borrower worked in the same field for the prior two years. Her nursing license and contracts show continuity. FHA's credit flexibility helps her 655 score.","alternatives":"Conventional with one year may work through DU and avoid lifetime MIP if she has 10% down. A W-2 staffing agency job would simplify documentation but would reset her contract income history.","watch":"Unreimbursed travel deductions reduce net income. If her next contract has a gap longer than 30 days, explain it in writing."},{"t":"First-year real estate agent","who":"Luis, 29, real estate agent, Las Vegas","situation":"Luis got licensed 11 months ago after two years as a leasing agent. He has closed 14 deals and deposits average $8,000 per month. He has not yet filed a tax return showing self-employment.","structure":"Likely wait for the first return; some non-QM lenders allow 12 months of bank statements with 2-year industry history (lender-specific)","numbers":"Bank-statement income at 50% expense factor ~ $4,000/mo","why":"Agency loans generally need at least one filed return showing the business. Non-QM may be possible but expense factors cut usable income sharply. Waiting a few months may give him far better options.","alternatives":"File 2026 taxes early and use conventional with one year if DU allows. Use a W-2 co-borrower (spouse) to qualify now.","watch":"Commission income without a filed return is hard to document. Large earnest money deposits from commissions need sourcing."},{"t":"Corporate IT manager turned consultant","who":"Neha, 40, IT consultant, Naperville IL","situation":"Neha left a W-2 role paying $165,000 to consult 15 months ago. Her 2025 net income is $180,000 through an S-corp she owns 100%. She wants a $750,000 home. Her CPA filed her returns on time.","structure":"Conventional or high-balance with 1 year of personal and S-corp returns (verify AUS)","numbers":"W-2 from S-corp $120,000 + K-1 $60,000 = $180,000","why":"Same field as her prior employment supports a shorter history. S-corp wages and K-1 income are both usable with liquidity analysis. Her income exceeds her prior salary, which helps the story.","alternatives":"Jumbo or portfolio lenders may require 2 years and more reserves. A bank-statement non-QM is unnecessary if agency approves.","watch":"25%+ ownership means business returns and a liquidity test. A declining YTD P&L would raise questions."},{"t":"Restaurant manager opens a food truck","who":"Carlos, 34, food-truck owner, Phoenix","situation":"Carlos managed restaurants for eight years before buying a food truck 16 months ago. His 2025 net profit was $70,000. He wants an FHA loan on a $360,000 home using Arizona Home Plus assistance. His business is seasonal, with slower summers.","structure":"FHA with Home Plus DPA (verify), using one year of self-employment plus related management history","numbers":"Net $70,000 = $5,833/mo","why":"FHA permits self-employment of 1-2 years with related prior experience. Food service management is directly related. DPA reduces his cash needed, preserving business reserves.","alternatives":"A bank-statement non-QM would avoid tax-return scrutiny but cost more and not pair with DPA. Waiting a year gives a two-year average and more lenders.","watch":"Seasonal deposits may make YTD look weak in summer. Health permits and the commissary lease should be current."}],"qa":[{"q":"Do I need two full years of self-employment?","a":"Not always. Fannie Mae, Freddie Mac and FHA can accept 12-24 months when you worked in the same or a related field before starting the business, and the AUS approves (verify). Under 12 months is usually non-agency."},{"q":"What if I haven't filed a tax return for my business yet?","a":"Agency loans generally need at least one filed return that shows the business income. Some non-QM bank-statement programs can work, but many require two years of business existence. Sometimes filing early is the fastest path."},{"q":"Can I use a profit-and-loss statement instead of tax returns?","a":"For agency loans, a P&L supplements tax returns; it doesn't replace them. P&L-only loans exist in non-QM and usually require a CPA-prepared statement."},{"q":"Do my business write-offs hurt me?","a":"Yes, lenders use net income after expenses. Non-cash items like depreciation and business use of home are usually added back, which helps."},{"q":"Should I amend my return to show more income?","a":"Talk to your CPA first. Amended returns get extra scrutiny and lenders may require proof the tax was paid."},{"q":"How does the lender verify my business?","a":"Usually with a CPA letter, business license, state registration or an internet listing, checked again shortly before closing."},{"q":"My income dropped this year. What happens?","a":"The underwriter will use the lower figure or ask for an explanation and proof that income has stabilized. A large drop can reduce the loan amount."},{"q":"Can I switch from 1099 to W-2 during the loan process?","a":"Avoid it. Changing employment type mid-process can reset your history and delay or derail the loan."}],"aeQuestions":["Do you allow 1 year of returns per DU/LPA?","Overlays for self-employment under 2 years?","P&L requirements?","Bank-statement minimum business existence?","CPA letter requirements?","Add-back policies?","Turn times?","Comp plan (no term-based comp)?"],"redFlags":["Business started recently with no prior same-field experience","Year-over-year or YTD income declining more than 10-20% without explanation","Unfiled or extended returns when the lender needs them","Personal and business funds commingled in a way that confuses sourcing","Large unexplained deposits in business accounts","CPA unwilling to provide a verification letter","Business license or registration lapsed","Borrower plans to change entity type or take on business debt before closing"],"pricing":"Agency loans generally price better than non-QM bank-statement loans; check agency eligibility first. Explain cost differences and the benefit of waiting for a second return if close. Disclose all fees. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide comparisons in writing.","marketing":["CPA partnerships","Trade associations","Small business events","Content for new entrepreneurs","Past W-2 clients who launched businesses"],"checklist":["Personal tax returns","Business tax returns","YTD P&L","Business license","CPA letter","Prior W-2s","Bank statements","Credit report","Appraisal","Insurance"],"updated":"2026-11"},
"c_credit_rebuild":{"matrix":[["FHA minimum FICO","580 for 3.5% down; 500-579 with 10% down (lender overlays common, often 600-640) (verify)"],["Conventional","620 minimum for DU/LPA; pricing improves with higher scores"],["VA","No VA minimum; lenders often 580-620 (verify)"],["USDA","GUS typically 640 for automated (verify)"],["Credit scoring models","FHFA approved VantageScore 4.0 option for GSE loans in 2025; implementation details and tri-merge/bi-merge changes - verify current"],["Rapid rescore","Only through lender's credit vendor; no fee charged to consumer by some lenders (verify)"],["Collections","FHA: medical collections excluded; non-medical $2,000+ may need 5% calc or payoff (verify)"],["Disputes","Disputed accounts may require removal of dispute for AUS (verify)"],["Seasoning after BK/FC","Program-specific waiting periods"],["Credit repair","CROA prohibits upfront fees by credit repair organizations; LOs should not act as credit repair (verify state law)"]],"walkthrough":["Get written authorization and pull a tri-merge report (or the format the lender's AUS currently requires - verify)","Identify each bureau's score factors: utilization, recent lates, collections, thin file, inquiries","Use the lender's credit simulator to model specific actions, such as paying a card from 92% to 25% utilization","Write a dated action plan with dollar amounts, which accounts to pay first, and a re-pull date","Advise keeping old accounts open and avoiding new credit applications","Address collections according to the target program: FHA excludes medical collections; non-medical totals may require payoff or a 5% payment calculation (verify)","For thin files, list non-traditional credit (rent, utilities, phone, insurance) and consider a secured card","Note waiting periods after bankruptcy, foreclosure or short sale for each program","Re-pull in 30-60 days or order a rapid rescore once balances post","Pre-approve when the score meets the program threshold with margin","Refer to a HUD-approved housing counselor for broader budgeting help","Never charge for credit repair or advise disputing accurate information"],"incomeExample":{"title":"Illustrative utilization pay-down plan","steps":["Three cards with $6,000 total limits carry $5,400 balances (90% utilization); middle score 598","Target total utilization under 30%: $6,000 x 30% = $1,800","Pay down $3,600 across the cards, starting with the card closest to its limit","Simulator estimate (lender tool) shows middle score may rise into the 630s (illustrative; not guaranteed)","At 620+, conventional DU becomes possible; at 640+ more FHA lenders without overlays accept the file"],"result":"A targeted $3,600 pay-down may move the borrower across a program threshold within 30-60 days. Results vary and can't be promised."},"scenarios":[{"t":"Utilization fix for a retail manager","who":"Jasmine, 28, retail store manager, Murrieta","situation":"Jasmine's middle score is 598 because her three cards are at 90% utilization. She has no late payments and earns $62,000. She has $12,000 saved for a home. Paying down cards would leave $8,400 for closing.","structure":"Pay down $3,600 to reach under 30% utilization; rapid rescore; then FHA or conventional","numbers":"See income example","why":"Utilization is the main factor lowering her score. A modest pay-down may move her past 620 or 640 thresholds. Better scores lower pricing and MI.","alternatives":"FHA at 598 with a lender that allows 580, accepting higher cost. Wait 3 months and save more while keeping balances low.","watch":"Don't close the paid cards. Any new purchase on the cards before rescore undoes the gain."},{"t":"Medical collections and FHA","who":"Derek, 35, warehouse lead, Las Vegas","situation":"Derek has $4,000 in medical collections from an emergency surgery. His score is 625. He worries he must pay them before buying. His other accounts are current.","structure":"FHA purchase; medical collections excluded from FHA calculations (verify)","numbers":"Price $350,000; 3.5% down","why":"FHA excludes medical collections. Paying them wouldn't necessarily raise his score. He keeps his savings for the down payment.","alternatives":"Negotiate settlements later once in the home. Conventional if AUS approves with collections.","watch":"Non-medical collections over the FHA threshold would need treatment. Check for judgments."},{"t":"Rebuilding after Chapter 7","who":"Angela, 42, nurse, Phoenix","situation":"Angela's Chapter 7 was discharged 18 months ago after a divorce. She opened two secured cards and has paid perfectly. Her score is 610. She wants to buy when eligible.","structure":"Continue rebuilding; FHA at the 2-year mark (verify)","numbers":"Target score 640+","why":"FHA's waiting period is 2 years after discharge. Re-established credit is required. Waiting six months may also improve her score.","alternatives":"Non-QM recent-credit-event programs now, at higher cost. Conventional after 4 years.","watch":"Any new late payment resets her progress. FHA requires re-established credit and 2 years after Chapter 7 discharge (verify)."},{"t":"Credit-invisible technician","who":"Victor, 24, HVAC technician, Chicago","situation":"Victor has no credit cards or loans. He pays rent, phone and car insurance on time. He earns $55,000. He wants a $220,000 condo.","structure":"FHA with non-traditional credit (lender-specific), or build credit for 12 months","numbers":"3.5% down $7,700","why":"FHA allows non-traditional credit. His payment history shows responsibility. Building traditional credit opens more lenders.","alternatives":"Secured card and credit-builder loan for 12 months. A co-borrower with established credit.","watch":"Few lenders accept no-score files, so overlays narrow options. Rent history must be verifiable by landlord or cancelled checks."},{"t":"Recent late payments","who":"Monica, 39, office manager, Orlando","situation":"Monica had two 30-day late payments six months ago during a job transition. Her score dropped to 630. She has a new stable job.","structure":"Wait for more on-time history; then FHA or conventional","numbers":"Score target 660+","why":"Recent lates weigh heavily. Time and on-time payments help. Better scores lower costs.","alternatives":"FHA now with a manual underwrite if AUS refers. Wait 6-12 months.","watch":"Any new late payment before applying would push her timeline out. AUS may refer her file to manual underwriting."}],"qa":[{"q":"How fast can my credit score improve?","a":"Paying revolving balances down below about 30% of limits often shows within one or two billing cycles. A lender's rapid rescore can update scores within days once the bureaus have the new balances."},{"q":"Should I close old credit cards?","a":"Usually not. Closing old accounts can raise utilization and shorten your credit history, which can lower your score."},{"q":"Do I have to pay off collections?","a":"It depends on the program. FHA ignores medical collections and has specific rules for non-medical collections over certain totals (verify). Paying an old collection doesn't always raise your score."},{"q":"Can you fix my credit for a fee?","a":"No. We give free guidance on what affects your mortgage score. Federal law (CROA) bars credit repair companies from charging upfront fees."},{"q":"Will shopping for a mortgage hurt my score?","a":"Multiple mortgage inquiries in a short window are typically treated as one. Avoid opening new credit cards or car loans while you shop."},{"q":"What is a rapid rescore?","a":"A service ordered through the lender that updates your scores after you pay down or correct accounts. It's only available through lenders, not consumers directly."},{"q":"Can I buy a home with a 580 score?","a":"FHA allows 3.5% down at 580, but many lenders set higher minimums. We look for lenders whose overlays fit your file."},{"q":"How long after bankruptcy or foreclosure can I buy?","a":"FHA generally requires 2 years after Chapter 7 discharge and 3 years after foreclosure. Conventional generally requires 4 and 7 years, with shorter periods for extenuating circumstances (verify)."},{"q":"Should I dispute accounts on my report?","a":"Only inaccurate ones. Open disputes can block automated approval until resolved."}],"aeQuestions":["FICO overlays by program?","Rapid rescore process and cost?","Non-traditional credit acceptance?","Collection rules?","Disputed account policy?","VantageScore implementation?","Manual underwriting?","Comp?"],"redFlags":["Requests to dispute accurate items","Credit repair company charging upfront","New inquiries","Undisclosed debts","Authorized-user piggybacking schemes","Unrealistic timelines"],"pricing":"Credit score affects loan-level price adjustments and mortgage insurance, so a 20-40 point improvement can materially change cost. Show the borrower a written 'today vs after plan' comparison without quoting rates in marketing. Never charge for credit repair or promise a score outcome. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons when the borrower is ready.","marketing":["Free credit workshops","HUD counselors","Employers' financial wellness","Social content","Past clients' referrals"],"checklist":["Credit authorization","Tri-merge","Action plan","Pay-down proof","Rescore results","Collection letters","Dispute status","Income docs","Assets","Re-pull schedule"],"updated":"2026-11"},
"c_military_pcs":{"matrix":[["VA occupancy","Intent to occupy within a reasonable time (generally 60 days; longer with justification such as deployment) - verify"],["Spouse occupancy","Spouse occupancy satisfies VA occupancy while member is deployed (verify)"],["Dependent child occupancy","Allowed in limited cases for VA (verify)"],["Power of attorney","VA-specific POA requirements; lender approval needed (verify)"],["BAH/BAS","Counts as income; documented on LES"],["PCS orders","Used to document relocation and income continuance"],["ETS within 12 months","Lender requires evidence of re-enlistment or civilian job (verify)"],["Departing residence rental income","Fannie/Freddie: lease plus deposit documentation; FHA relocation 100+ miles with 25% equity for rental income (verify)"],["Remote closing","E-closing/RON availability lender-specific; state rules vary"],["SCRA","Interest-rate cap on pre-service debts; protections for servicemembers"],["Entitlement","Restoration or second-tier entitlement when keeping prior VA home"],["Funding fee","Exempt with service-connected disability compensation or Purple Heart (verify)"]],"walkthrough":["Get the PCS orders, report-no-later-than date and the family's move timeline","Pull the LES and calculate base pay, BAH, BAS and any special or incentive pays","Order the Certificate of Eligibility and determine full, partial or second-tier entitlement","Decide what happens to the departing residence: sell, rent with a lease, or keep using remaining entitlement","Collect the lease and deposit evidence if rental income from the departing home will be used","Pre-approve with VA and conventional comparisons, including residual income for the destination region","Coordinate remote house-hunting with an agent who knows the base (video tours, virtual inspections)","Arrange a VA-compliant specific power of attorney or spouse signing if the member may be unavailable","Order the VA appraisal and use Tidewater if a value issue arises","Close by remote online notarization or POA where lender and state allow","Document occupancy timing, including spouse occupancy during deployment","Give the borrower servicer contacts and an SCRA overview"],"incomeExample":{"title":"Illustrative active-duty income (E-7 PCS to San Diego)","steps":["Base pay (illustrative) $5,200/mo","BAH San Diego with dependents (illustrative) $4,200/mo","BAS $460/mo","Total income $9,860/mo (BAH/BAS non-taxable; gross-up per VA/lender policy - verify)","Residual income test for family of 4 in West region (verify table)","PITI $5,600; debts $700; DTI ~ 64% but VA allows with residual income (verify)"],"result":"VA's residual income method may allow a higher DTI when residual income is strong. Illustrative only."},"scenarios":[{"t":"PCS with deployment right after arrival","who":"Chief Ramirez, 38, Navy E-7, PCS to Naval Base San Diego","situation":"Chief Ramirez reports to San Diego in June and deploys in September for seven months. His wife and two children arrive with him. They want to buy rather than rent off base. He has full VA entitlement and $30,000 saved.","structure":"VA purchase with spouse occupancy satisfying VA's occupancy requirement during deployment (verify)","numbers":"Price $850,000; $0 down within full entitlement; funding fee unless exempt","why":"Spouse occupancy satisfies VA while he's deployed. Full entitlement allows zero down even at this price. BAH for San Diego with dependents supports the payment.","alternatives":"Rent for the deployment and buy after return, avoiding a rushed purchase. Conventional with 5-10% down if he wants to preserve entitlement for a future home.","watch":"If closing slips past his deployment date, a VA-compliant specific power of attorney must be in place. Residual income must meet VA's West-region table."},{"t":"Keep the Oceanside home as a rental","who":"Capt. Lee, 34, USMC, PCS from Camp Pendleton to Quantico","situation":"Capt. Lee bought in Oceanside with VA three years ago and wants to keep it as a rental. He has orders to Virginia and wants to buy there too. Part of his entitlement is tied up in the Oceanside loan. He has a signed lease for the Oceanside home.","structure":"New VA loan using remaining (second-tier) entitlement in Virginia","numbers":"Remaining entitlement determines zero-down maximum; Oceanside rent $3,600 (75% may count - verify)","why":"Second-tier entitlement lets him buy again without selling. Rental income from the lease offsets the Oceanside payment. He builds a long-term rental portfolio.","alternatives":"Sell the Oceanside home and restore full entitlement. Use a conventional loan in Virginia to keep VA entitlement available.","watch":"Rental income needs a lease and possibly a security deposit or rent receipt (verify). Property management costs must fit his budget."},{"t":"ETS within a year","who":"Sgt. Johnson, 27, Army, separating from Fort Irwin to Henderson NV","situation":"Sgt. Johnson leaves the Army in 10 months. He has a civilian job offer in Henderson starting after separation. His family wants to buy before he starts. He has $10,000 saved.","structure":"VA purchase qualifying with the civilian job offer (lender-specific)","numbers":"Civilian salary $70,000; price $400,000","why":"Lenders need evidence of income after ETS. A firm offer documents continuance. VA's zero down fits his savings.","alternatives":"Wait until he starts the civilian job and has a paystub. Rent in Henderson for a few months.","watch":"The offer letter must show start date, salary and position. A delayed start can derail closing."},{"t":"Air Force PCS to Luke AFB","who":"MSgt. Brown, 40, Air Force, Glendale AZ","situation":"MSgt. Brown has PCS orders to Luke AFB with his family. He has used VA before and restored his entitlement. He's buying a $480,000 home in an HOA community. His spouse works remotely.","structure":"VA purchase","numbers":"$0 down","why":"Full entitlement allows zero down. BAH and spouse income support the payment. VA has no monthly MI.","alternatives":"Conventional if he wants to preserve entitlement. Rent on base.","watch":"HOA dues count in ratios and Glendale HOA rules may restrict rentals later. Closing must align with his report date."},{"t":"Coast Guard to Florida","who":"PO1 Davis, 32, Coast Guard, Clearwater","situation":"PO1 Davis has orders to Clearwater. The home he likes is in a flood zone. Insurance quotes are high. He has full entitlement.","structure":"VA with flood insurance","numbers":"Price $420,000","why":"VA zero down. BAH supports payment. Flood insurance budgeted.","alternatives":"A home outside the flood zone. FHA.","watch":"Flood and windstorm insurance can exceed estimates in Pinellas County. Elevation certificates affect flood premiums."}],"qa":[{"q":"Can I buy a home before I report to my new duty station?","a":"Yes. With PCS orders, lenders can approve you before arrival. Closing can happen by remote notarization or a VA-compliant power of attorney."},{"q":"Does BAH count as income?","a":"Yes. BAH and BAS are documented on your LES and count as income. Because they're non-taxable, some lenders gross them up (verify)."},{"q":"Can my spouse move in while I'm deployed?","a":"Yes. VA treats spouse occupancy as meeting the occupancy requirement when the servicemember is deployed (verify). Plan the closing signatures in advance."},{"q":"Can I keep my current VA home and buy another?","a":"Often yes, using remaining or second-tier entitlement. How much you can borrow without a down payment depends on the entitlement still in use."},{"q":"Do I have to pay the VA funding fee?","a":"Unless you're exempt, such as receiving VA disability compensation or being a Purple Heart recipient (verify). The fee can be financed."},{"q":"Can rent from my old home help me qualify?","a":"Often, with a signed lease and documentation. FHA and conventional have specific rules for departing residences (verify)."},{"q":"What if I'm separating within a year?","a":"Lenders typically need re-enlistment documentation or a civilian job offer to show income continues. Retirement pay and disability income also count."},{"q":"Can I close if I'm deployed?","a":"Yes, with a VA-compliant specific power of attorney or remote closing where the lender and state allow it."},{"q":"Does the SCRA help me?","a":"It caps interest on debts taken before active duty and provides foreclosure protections. It doesn't lower the rate on a new mortgage."}],"aeQuestions":["What POA language and approvals do you require for VA closings?","How do you document spouse occupancy during deployment?","Do you count departing-residence rental income with a lease only?","What do you need when ETS is within 12 months?","Do you offer remote online notarization in CA, NV, AZ, FL and IL?","How do you calculate second-tier entitlement in high-cost counties?","Do you gross up BAH/BAS?","Turn times on VA appraisals and Tidewater?","Broker comp plan (no term-based comp)?"],"redFlags":["No occupancy intent","Missing PCS orders","ETS without job","POA not VA-compliant","Rental income without lease","Overextended budget"],"pricing":"VA loans usually offer strong pricing and no monthly mortgage insurance, but compare against conventional when the borrower has 20% down or wants to preserve entitlement. Explain the funding fee, exemptions and how it can be financed. Show side-by-side cash to close and payment. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons.","marketing":["Base relocation offices","Military spouse groups","Steven's Navy network","Veteran service organizations","Content on PCS buying"],"checklist":["PCS orders","LES","COE","POA if needed","Lease for departing residence","Spouse docs","Appraisal","Insurance","Credit","Assets"],"updated":"2026-11"},
"c_small_balance_comm":{"matrix":[["Loan size","Typically $500K-$5M (lender-specific)"],["Max LTV","Often 65-75% purchase; lower for cash-out (lender-specific)"],["DSCR minimum","Often 1.20-1.25x (lender-specific)"],["Amortization","20-30 years (lender-specific)"],["Term","5, 7 or 10-year fixed periods; balloon at maturity (lender-specific)"],["Prepayment","Step-down (e.g., 5-4-3-2-1) or yield maintenance (lender-specific)"],["Recourse","Full or partial recourse common; non-recourse for stronger deals (lender-specific)"],["Property types","Retail, office, industrial, mixed-use, small multifamily 5+ units, self-storage"],["Environmental","Phase I ESA or database screen (lender-specific)"],["Borrower","Usually an entity with personal guarantees"],["Credit","Often 660-700+ for guarantors (lender-specific)"],["Reserves/escrows","Taxes, insurance, replacement reserves (lender-specific)"]],"walkthrough":["Collect the rent roll, trailing-12-month operating statement (T-12), current leases and tenant estoppels if available","Rebuild NOI the way lenders do: market vacancy factor, management fee, replacement reserves, actual taxes after sale reassessment","Size the loan by both DSCR (e.g., 1.25x) and LTV (e.g., 70%); the lower result controls","Gather sponsor financials: personal financial statement, schedule of real estate owned, tax returns, liquidity","Choose lender types to approach: community bank, credit union, debt fund, CMBS conduit, life company, SBA (owner-users)","Request and compare term sheets on rate structure, amortization, term, prepayment, recourse and reserves","Form or confirm the borrowing entity and operating agreement","Order appraisal, Phase I environmental (or database screen) and property condition report","Review lease terms for rollover risk, co-tenancy and termination rights","Credit committee approval; negotiate loan documents with counsel","Close; set up tax, insurance and replacement reserve escrows as required"],"incomeExample":{"title":"Illustrative DSCR calculation","steps":["Gross potential rent $360,000","Vacancy/credit loss 5% = $18,000","Operating expenses $102,000","NOI = $360,000 - $18,000 - $102,000 = $240,000","Annual debt service on proposed loan $190,000","DSCR = $240,000 / $190,000 = 1.26x"],"result":"Meets a typical 1.25x minimum; loan size may be constrained by DSCR rather than LTV. Illustrative."},"scenarios":[{"t":"Neighborhood retail strip","who":"Hector, 55, retired engineer turned investor, Escondido","situation":"Hector is buying a 6-tenant neighborhood retail strip for $3.2M. Tenants include a dry cleaner drop-off, a nail salon and a taqueria. Leases are staggered, with two expiring within three years. NOI is about $230,000.","structure":"Community bank loan at 70% LTV, 25-year amortization, 10-year term","numbers":"Loan $2.24M; DSCR ~1.28x (illustrative)","why":"Local banks value relationship deposits and know the trade area. Staggered leases reduce rollover risk. Ten-year term limits refinance exposure.","alternatives":"A CMBS conduit loan offers non-recourse but has yield maintenance and stricter servicing. A debt fund could lend higher leverage at higher cost.","watch":"The dry cleaner drop-off requires environmental review confirming no on-site cleaning. Two near-term lease expirations may require a leasing reserve."},{"t":"Owner-user industrial building","who":"Lisa, 47, electrical contractor, Temecula","situation":"Lisa's contracting company rents a 6,000 sq ft shop for $8,500 a month. The building is for sale at $1.6M. She has strong business cash flow and $400,000 available. She wants to stop paying rising rent.","structure":"Conventional owner-user commercial loan, or SBA 504 if every owner is eligible under 2026 rules (verify)","numbers":"Conventional 75% LTV = $1.2M; SBA 504 at 10% down = $160,000 injection","why":"Owning fixes occupancy costs. Owner-user loans often get better terms than investor loans. SBA 504 could preserve working capital.","alternatives":"Continue leasing with a purchase option to wait for better terms. Buy with a partner investor and lease back.","watch":"Phase I may be required given prior industrial use. SBA eligibility checks every owner's citizenship under current rules."},{"t":"Value-add 10-unit apartment","who":"James, 50, investor, Phoenix","situation":"James is buying a 10-unit 1980s building for $1.8M. Rents are 20% below market. He plans $250,000 of interior upgrades. Current DSCR won't support long-term financing at his target leverage.","structure":"Bridge loan for acquisition and rehab, then refinance to a small-balance multifamily loan","numbers":"Bridge 75% of cost; post-renovation NOI target $150,000","why":"Bridge lenders underwrite to the business plan. Refinancing after stabilization captures the higher value. Long-term debt then fits the improved cash flow.","alternatives":"A bank loan at lower leverage with renovation funded from cash. Agency small-balance multifamily after stabilization.","watch":"Rehab overruns and slower lease-up threaten the refinance. Bridge maturity must allow 12-24 months."},{"t":"Office converted to medical use","who":"Dr. Patel, 52, family physician, Las Vegas","situation":"Dr. Patel is buying a $2.2M two-story office building. She'll occupy the ground floor and lease the upper floor. Build-out for medical use will cost $300,000. Her practice is profitable.","structure":"Bank owner-user loan including build-out","numbers":"Loan ~ 75% of cost","why":"Owner occupancy improves terms. Upper-floor rent offsets cost. The bank finances improvements with the purchase.","alternatives":"SBA 504 with 10% down if eligible. Lease the building instead.","watch":"Build-out permits and ADA compliance. Medical tenant improvement costs often rise."},{"t":"Chicago mixed-use building","who":"Elena, 44, investor, Chicago","situation":"Elena is buying a $1.4M building with ground-floor retail and four apartments. The retail tenant is a long-time cafe. Cook County reassessments recently raised taxes. She has 30% down.","structure":"Community bank portfolio loan","numbers":"Loan $980,000","why":"Banks handle mixed-use well. Residential units diversify income. The long-term cafe lowers vacancy risk.","alternatives":"Agency small-balance if residential share qualifies. A credit union with local lending focus.","watch":"Cook County reassessment after sale may raise taxes; underwrite the post-sale tax bill. The retail tenant's lease term affects DSCR."}],"qa":[{"q":"How much down payment do I need for small commercial property?","a":"Typically 25-35% of the price. Special-purpose properties, weaker tenants or first-time sponsors may need more."},{"q":"Which matters more, DSCR or LTV?","a":"Lenders test both and lend the lower amount. When rents are modest relative to price, DSCR usually limits the loan."},{"q":"Do I need to personally guarantee the loan?","a":"Usually yes for small-balance loans. Non-recourse terms with 'bad-boy' carve-outs are possible on stronger deals, often at lower leverage."},{"q":"Can I pay the loan off early?","a":"Prepayment penalties are common. They range from step-down schedules (like 5-4-3-2-1%) to yield maintenance or defeasance on conduit loans."},{"q":"What is a balloon payment?","a":"Many commercial loans have a 5-10 year term with a longer amortization, so the remaining balance comes due at maturity. Most borrowers refinance or sell before then."},{"q":"How long does closing take?","a":"Often 45-90 days because of appraisals, environmental and condition reports and credit committee review."},{"q":"Are environmental reports required?","a":"Usually a Phase I or at least a database screen. Former gas stations, dry cleaners or industrial uses need extra review."},{"q":"Can I buy in an LLC?","a":"Yes, entity borrowers are standard. The lender will want the operating agreement and guarantees from key principals."}],"aeQuestions":["What max LTV and minimum DSCR do you apply by property type?","Amortization and term options?","Prepayment structure options?","Recourse vs non-recourse thresholds?","Which property types do you avoid?","Environmental and PCR requirements?","Reserves and escrows required?","Turn times to term sheet and close?","Broker fee policy and disclosure?"],"redFlags":["High vacancy","Short leases","Environmental issues","Sponsor weakness","Deferred maintenance","Overstated NOI"],"pricing":"Commercial pricing depends on property type, DSCR, LTV, sponsor strength and prepayment structure. Compare multiple term sheets on total cost, not rate alone. Explain balloon risk and refinance exposure. Disclose all broker fees in writing. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)).","marketing":["Commercial brokers","CPAs","Investor meetups","Content on CRE financing","Past residential investor clients"],"checklist":["Rent roll","T-12","Leases","Entity docs","Sponsor financials","Appraisal","Environmental","PCR","Insurance","Title"],"updated":"2026-11"},
"c_sba":{"matrix":[["Ownership/citizenship","As of March 1, 2026 (Procedural Notice 5000-876626), SBA financing generally requires 100% ownership by U.S. citizens or U.S. nationals; LPR-owned businesses were made ineligible; SOP 50 10 8.1 effective Oct 1, 2026 adds principal-residence requirements - verify current SOP"],["504 structure","Typically 50% bank first lien / 40% CDC debenture / 10% borrower (verify)"],["504 down payment","10% standard; 15% for new business (under 2 years) or special-purpose property; 20% if both (verify)"],["7(a) max","$5M (verify)"],["504 debenture max","$5M standard; $5.5M for manufacturing/energy public policy (verify)"],["Owner occupancy","51% for existing buildings; 60% for new construction (verify)"],["Personal guaranty","Owners of 20%+ guarantee (verify)"],["Term","504: 10, 20 or 25-year debenture; 7(a) real estate up to 25 years (verify)"],["Fees","SBA guaranty fees and CDC fees; agent fees disclosed on SBA Form 159"],["Equity injection","Verified source; seller notes on standby may count (verify SOP)"],["Environmental","Phase I or transaction screen per SOP; gas stations/dry cleaners special rules"],["Credit elsewhere","Lender must document credit not available elsewhere on reasonable terms"]],"walkthrough":["Confirm business eligibility: for-profit, size standard, operating business, and ownership/citizenship under the current SOP and procedural notices","Collect 3 years business returns, interim financials, personal financial statements (SBA Form 413), debt schedule","Calculate global DSCR (business plus personal)","Decide 504 vs 7(a) based on project, equipment, working capital needs","Identify bank partner and CDC (for 504)","Disclose any broker/agent fee on SBA Form 159","Order appraisal and environmental review","Lender submits to SBA (or under delegated authority)","Commitment letter; equity injection verification","Close bank loan; 504 debenture funds later (interim financing)","Monitor owner-occupancy compliance post-closing"],"incomeExample":{"title":"Illustrative global debt service coverage","steps":["Business EBITDA (after owner salary adjustment) $420,000","Proposed debt service on 504 project: bank first $150,000/yr + debenture $110,000/yr = $260,000","Other business debt service $40,000/yr","Business DSCR = $420,000 / $300,000 = 1.40x","Add owner's personal income and expenses for global DSCR; target typically 1.15-1.25x+ (lender-specific)"],"result":"Coverage appears adequate, subject to lender and SBA review. Illustrative only."},"scenarios":[{"t":"Dental practice buys its building","who":"Dr. Kim, 45, dentist, Temecula","situation":"Dr. Kim's practice pays $12,000 a month in rent and the landlord is selling the building for $2.4M. She needs $200,000 of improvements for two more operatories. Her practice has three years of strong returns. She and her husband are the only owners.","structure":"SBA 504: 50% bank first lien, 40% CDC debenture, 10% owner injection, after confirming every owner meets current SBA citizenship rules (verify)","numbers":"Project $2.6M; injection ~ $260,000; bank ~ $1.3M; debenture ~ $1.04M","why":"The 504 structure needs only about 10% down for an existing business in a general-purpose building. The debenture portion carries a long fixed term. Owning replaces rent with equity-building debt service of similar size.","alternatives":"A conventional commercial loan with 20-25% down avoids SBA fees and paperwork but ties up more cash. Leasing with a long-term renewal keeps capital for equipment.","watch":"Global DSCR must hold after improvement costs. Every owner's citizenship and principal-residence status must meet the SOP in effect at application (verify)."},{"t":"Manufacturer expands under a public-policy goal","who":"Frank, 52, machine shop owner, El Cajon","situation":"Frank's shop needs a larger building and two CNC machines for a defense contract. The project totals $6M. Manufacturing projects can qualify for a higher 504 debenture limit. He employs 28 people and expects to hire 10 more.","structure":"SBA 504 using the manufacturing public-policy debenture limit (verify $5.5M)","numbers":"Project $6M; injection ~ $600,000","why":"The higher debenture limit fits the project size. Job creation supports eligibility. Long fixed financing matches equipment and building life.","alternatives":"A 7(a) loan for equipment plus a conventional building loan. Equipment leasing to preserve cash.","watch":"Job creation or retention requirements must be met. Environmental review for machining fluids."},{"t":"Startup restaurant in a special-purpose building","who":"Sofia, 38, chef, Scottsdale","situation":"Sofia opened her restaurant 18 months ago in leased space. She wants to buy a $1.5M freestanding restaurant building. Restaurants are considered special-purpose property. Her business is under two years old.","structure":"SBA 504 with higher injection for a new business and special-purpose property (verify 20%)","numbers":"Injection ~ $300,000","why":"504 still requires less down than most conventional options. Owning protects her location. Her growth supports cash flow.","alternatives":"Continue leasing until the business is two years old, lowering injection. A seller-financed purchase.","watch":"Special-purpose appraisal may come in lower. Restaurant cash flow volatility."},{"t":"Ownership eligibility issue","who":"Raj, 41, IT services owner, Irvine","situation":"Raj and his co-owner each own 50% of a profitable IT services firm. His co-owner is a permanent resident. Under SBA rules effective March 1, 2026, the business may not be eligible (verify). They want to buy an office condo.","structure":"Conventional commercial or bank portfolio loan","numbers":"Project $1.8M; 20-25% down","why":"Applying the SBA rule uniformly means evaluating alternatives. Conventional lenders don't impose the same ownership rule. The business's strength supports conventional terms.","alternatives":"Seller financing. Lease.","watch":"Apply the SBA ownership rule uniformly and never discourage applicants based on national origin. Conventional lenders may need 20-25% down."},{"t":"Veterinary clinic acquisition with 7(a)","who":"Dr. Alvarez, 39, veterinarian, Henderson NV","situation":"Dr. Alvarez is buying the clinic where she works, including real estate and goodwill. The seller will carry a small note. The total is $3.2M.","structure":"7(a) up to $5M covering goodwill and real estate","numbers":"Total $3.2M","why":"7(a) finances goodwill. One loan simplifies. Seller note helps equity.","alternatives":"Split the deal: SBA 504 for the real estate and a smaller 7(a) for goodwill. A larger seller note to reduce the bank loan.","watch":"Seller notes counted toward equity must be on standby per SOP (verify). Every owner must meet current SBA eligibility."}],"qa":[{"q":"How much do I need down for an SBA 504?","a":"Typically 10% for an existing business in a general-purpose building. New businesses or special-purpose properties may need 15%, and both together may need 20% (verify current SOP)."},{"q":"Do I have to occupy the building?","a":"Yes. Your business must occupy at least 51% of an existing building or 60% of new construction (verify). You can lease the rest."},{"q":"Can I use SBA if an owner isn't a U.S. citizen?","a":"Under SBA rules effective March 1, 2026, 100% of owners generally must be U.S. citizens or nationals (verify current SOP). Conventional commercial lending may still be available, and we apply the rule the same way to everyone."},{"q":"What's the difference between 504 and 7(a)?","a":"504 finances fixed assets like real estate and equipment with a bank loan plus a CDC debenture. 7(a) is more flexible and can include working capital and goodwill, with different terms and fees."},{"q":"Do I need a personal guarantee?","a":"Generally yes for owners of 20% or more. Spouses may need to sign in some cases (verify)."},{"q":"Are there prepayment penalties?","a":"504 debentures have a declining prepayment penalty over the first half of the term. 7(a) loans with terms over 15 years have fees for large prepayments in the first three years (verify)."},{"q":"How long does it take?","a":"Often 60-120 days. Lenders with delegated authority can be faster."},{"q":"Can a broker charge a fee?","a":"Yes, but it must be disclosed on SBA Form 159 and be reasonable. All fees are disclosed in writing."},{"q":"Can I include renovation costs?","a":"Yes. 504 projects can include improvements, soft costs and some equipment."}],"aeQuestions":["How are you applying the 2026 citizenship/ownership rules and SOP 50 10 8.1?","Delegated authority (PLP) status?","Typical global DSCR minimum?","Equity injection sourcing rules?","Which CDCs do you partner with?","Environmental requirements by property type?","Turn time to commitment?","Referral/agent fee policy and Form 159 process?","Appetite for startups and special-purpose properties?","Interim financing structure for 504?"],"redFlags":["Owner citizenship/ownership not verified against current SOP","Equity injection from undocumented sources","Declining business revenue","Property largely leased to third parties","Environmental concerns (gas station, dry cleaner)","Undisclosed tax liens or prior federal debt delinquency","Owner unwilling to guarantee"],"pricing":"SBA pricing includes guaranty fees, CDC fees, and lender fees in addition to interest costs. Compare the total cost of 504, 7(a) and conventional commercial alternatives over the expected holding period. Explain prepayment structures clearly. Disclose any broker or referral fee on SBA Form 159. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering a borrower to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)); for commercial deals Steven applies the same standard and discloses all fees in writing.","marketing":["Workshops with CPAs for practice owners (dental, veterinary, medical)","Chambers of commerce and veteran-owned business groups","Content: 'Rent vs own your building'","Commercial real estate brokers","Steven's veteran network for veteran-owned businesses"],"checklist":["Ownership and citizenship documentation for all owners (current SOP)","3 years business tax returns","Interim P&L and balance sheet","Personal financial statements (SBA Form 413)","Personal tax returns","Business debt schedule","Purchase contract/LOI","Appraisal","Environmental report","Equity injection proof","SBA Form 159 (if fees)","Lease (if partial occupancy)","Entity documents","Insurance"],"updated":"2026-11"},
"c_assisted_living":{"matrix":[["CA license","Residential Care Facility for the Elderly (RCFE) licensed by CDSS Community Care Licensing; license is not transferable - buyer must apply for its own (verify)"],["AZ license","Assisted living homes (10 or fewer) and centers licensed by ADHS (verify)"],["NV/FL/IL","NV Division of Public and Behavioral Health; FL AHCA (ALF); IL IDPH assisted living establishments (verify)"],["Financing types","SBA 7(a)/504 (special-purpose property, higher injection), bank/credit union, healthcare lenders, HUD 232 for larger facilities"],["SBA eligibility","2026 SBA ownership/citizenship rules apply to all owners (verify current SOP)"],["Down payment","Often 15-30% depending on structure and experience (lender-specific)"],["Operator experience","Licensed administrator and operating history usually required (lender-specific)"],["DSCR","Typically 1.25x-1.50x on stabilized operations (lender-specific)"],["Appraisal","Going-concern valuation (real estate + FF&E + business) by healthcare-specialist appraiser"],["Licensing timing","New license approval must be coordinated with closing; operations transfer agreements common"],["Zoning","6-or-fewer-bed homes in CA are generally treated as residential use (verify local rules)"],["Insurance","Professional and general liability; abuse/molestation coverage often required"]],"walkthrough":["Confirm the state licensing pathway and timeline for the buyer's own license","Review buyer's operating experience, administrator certification and staffing plan","Collect 2-3 years facility financials, census history and private-pay vs. Medicaid waiver mix","Review survey/citation history from the licensing agency","Choose financing: SBA (if eligible), bank, healthcare lender or HUD 232","Order going-concern appraisal and property condition report","Underwrite DSCR using stabilized census and market-rate staffing","Coordinate operations transfer agreement and license application timing","Clear lender conditions including insurance and licensing","Close and fund; verify license effective date aligns","Post-closing: monitor census and covenant compliance"],"incomeExample":{"title":"Illustrative 6-bed residential care home (CA RCFE)","steps":["Census 6 residents x average $6,200/mo = $37,200/mo revenue","Less 8% vacancy factor = $34,224/mo effective revenue","Operating expenses (24/7 staffing, food, utilities, insurance, admin) $23,500/mo","NOI = $34,224 - $23,500 = $10,724/mo = $128,688/yr","Proposed annual debt service $96,000","DSCR = $128,688 / $96,000 = 1.34x"],"result":"Coverage meets a typical 1.25x minimum but is sensitive to census and wage changes. Illustrative only."},"scenarios":[{"t":"Nurse buys an established 6-bed home","who":"Maria, 45, RN and certified RCFE administrator, Temecula","situation":"Maria has managed a residential care home for 6 years. The owner is retiring and offers her the licensed 6-bed home for $1.45M. It's full with a waitlist. Maria has $300,000 saved.","structure":"SBA 7(a) covering real estate and business if eligible, or bank loan with seller carry-back","numbers":"Injection 15-20% (~$220,000-$290,000); DSCR ~1.34x (see income example)","why":"Her clinical and administrator experience satisfies lenders. Stabilized census supports cash flow. SBA allows lower injection than conventional.","alternatives":"A bank loan with a 10% seller note on standby reduces cash needed. Leasing the property and buying only the business lowers the price.","watch":"Her own RCFE license must be approved before closing. Staffing wage increases can erode DSCR."},{"t":"Converting a residence into an RCFE","who":"Joe, 50, former hospital administrator, Phoenix","situation":"Joe owns a large single-story home in Phoenix. He wants to convert it into a licensed assisted living home for up to 10 residents. Conversion requires fire sprinklers, accessibility upgrades and licensing. He has $250,000 in savings.","structure":"Business-purpose financing for conversion plus a bank operating line","numbers":"Conversion and startup ~ $250,000","why":"Using an owned property lowers acquisition cost. His administrative background helps with licensing. Operating capital covers the ramp-up.","alternatives":"Buy an existing licensed home to avoid startup risk. Partner with an experienced operator.","watch":"ADHS licensing and fire code compliance; zoning for more than 6 residents."},{"t":"Operator adds a second home","who":"Ana, 52, operator, Las Vegas","situation":"Ana has run one profitable six-bed care home in Las Vegas for five years with consistent full census. A nearby licensed home is for sale at $1.2M. Her administrator and lead caregivers can support a second site. She has $300,000 available.","structure":"Bank loan using global cash flow","numbers":"25% down","why":"Proven operations. Global cash flow supports the loan. Bank relationship.","alternatives":"SBA 504 if every owner is eligible under 2026 rules, lowering down payment to 10-15%. A seller carry-back for part of the price to preserve her working capital.","watch":"Staffing depth must cover two sites around the clock. Global DSCR must hold if census at the new home dips during transition."},{"t":"Larger assisted living refinance","who":"Healthcare group, Orlando","situation":"An 80-unit assisted living community in Orlando has stable occupancy above 90%. The owners want to replace a maturing bank loan with long-term fixed financing. Their AHCA survey history is clean. The property is worth about $12M.","structure":"HUD 232 refinance","numbers":"Value $12M","why":"Long fixed term. Low cost. Stable census.","alternatives":"A bank or healthcare debt fund refinance closes faster but with shorter terms and floating rates. A bridge loan now with HUD 232 later if timing is tight.","watch":"HUD 232 approvals can take many months, so the existing loan maturity must allow time. Any AHCA citation during processing could delay approval."},{"t":"Illinois assisted living purchase","who":"Tom, 48, Naperville","situation":"Tom has managed assisted living communities for 12 years and now wants to own one. A 30-unit establishment in the Naperville area is for sale at $3.2M. Census is steady and the community serves mostly private-pay residents. He has 25% down with an investor partner.","structure":"Bank healthcare loan","numbers":"Price $3.2M","why":"Local bank. Experience. Cash flow.","alternatives":"A healthcare specialty lender may offer higher leverage. SBA 7(a) if all owners meet current eligibility rules (verify).","watch":"IDPH licensing must transfer or be reissued before closing. Medicaid program mix affects revenue stability (verify)."}],"qa":[{"q":"Do I need experience to finance a care home?","a":"Most lenders require operating or licensed administrator experience, or a qualified management partner. Experience is one of the biggest factors in approval and terms."},{"q":"Can I use an SBA loan?","a":"Often yes, if the business and every owner meet current SBA eligibility, including the 2026 citizenship rules (verify). Care homes are usually special-purpose property, which raises the required injection."},{"q":"How much down payment will I need?","a":"Usually 15-30%, depending on structure, experience and property type. Startups and conversions are at the high end."},{"q":"Does the license transfer with the sale?","a":"In California, generally no: the buyer applies for a new RCFE license (verify). Licensing timing often drives the closing date."},{"q":"How is the property appraised?","a":"As a going concern, including business value, furniture and equipment, not just the real estate. Lenders often lend against the real estate portion more heavily."},{"q":"How long does it take?","a":"Often 90 days or more because of licensing. Start the license application early."},{"q":"What is HUD 232?","a":"FHA-insured financing for larger residential care and assisted living facilities. It offers long fixed terms but has lengthy approvals."},{"q":"What DSCR do lenders want?","a":"Commonly 1.25x-1.50x on stabilized operations. Lenders stress-test for lower census and higher wages."},{"q":"Can I live in the home too?","a":"Some small-home operators do. Lender and licensing rules vary, so confirm before structuring the loan."}],"aeQuestions":["Minimum operator experience and administrator certification?","Do you finance license-pending acquisitions with an operations transfer agreement?","SBA eligibility review under the 2026 citizenship rules?","Appraisal requirements and approved healthcare appraisers?","DSCR and census assumptions you underwrite to?","Max LTV for going-concern value?","Insurance requirements?","Turn times?","Broker fee policy and disclosure?"],"redFlags":["Buyer has no care-industry experience or management partner","Recent licensing citations or complaints","Census declining or heavy reliance on one referral source","Staffing shortages or wage-and-hour issues","Revenue claims not supported by bank deposits","Zoning or fire-code issues for conversions"],"pricing":"Healthcare real estate carries specialty pricing, and SBA, bank, healthcare lender and HUD 232 options differ widely in fees, terms and timelines. Compare total cost and prepayment structures in writing. Explain that going-concern valuations may limit loan size. Disclose all broker fees in writing. Broker compensation never drives lender choice: originator pay cannot vary with loan terms and steering for higher compensation is prohibited (12 CFR 1026.36(d)/(e)); Steven applies the same standard on business-purpose deals and discloses all fees in writing.","marketing":["Nurse and administrator associations","RCFE administrator certification programs","Senior placement agencies (education only)","CPAs serving care operators","Content on buying vs. starting a care home"],"checklist":["License application status","Administrator certification","2-3 years facility financials","Census reports","Survey/citation history","Staffing plan","Appraisal (going concern)","Property condition report","Insurance quotes","Entity documents","Purchase agreement and operations transfer agreement","Ownership/citizenship documentation for SBA (if used)"],"updated":"2026-11"},
"c_land":{"matrix":[["Raw land max LTV","Often 50-65% (lender-specific)"],["Improved/entitled lot LTV","Often 65-80%; higher when tied to a construction loan (lender-specific)"],["Term/amortization","Often 5-20 years, frequently with balloon or ARM structures (lender-specific)"],["Typical lenders","Local banks, credit unions, Farm Credit associations, seller carry-back"],["Agency/FHA/VA","Raw land alone generally not eligible; lot may be financed within one-time-close construction (verify)"],["USDA","Not for raw land purchase alone; Section 502 can include site purchase with construction (verify)"],["Credit","Often 680-720+ (lender-specific)"],["Due diligence","Legal access, zoning, utilities, perc/septic, well/water, survey, environmental"],["Consumer vs business purpose","Lot for a future primary residence is consumer credit (TRID applies); investment/business land may be business-purpose"],["Appraisal","Land comps are scarce; appraisals often conservative"],["Fire/flood","CAL FIRE hazard zones, FEMA flood zones affect insurability and future building"],["Water rights","Critical in NV and AZ (verify state water law)"]],"walkthrough":["Define the plan and timeline: build within 1-2 years, hold long term, or agricultural use","Verify zoning, minimum lot size and allowed uses (including ADUs) with the county planning department","Confirm legal access via recorded easements and physical access for construction equipment","Check utilities: power line distance, water source (district, well, water rights), sewer vs septic; order a perc test","Review hazards: CAL FIRE severity zone, FEMA flood zone, slope, soils, wetlands","Get insurance quotes for the future home to confirm insurability","Decide financing: land loan now vs one-time-close construction including the lot","Shop local banks, credit unions and Farm Credit; evaluate seller carry-back terms","Order survey and appraisal; review land comparables","Underwrite income, assets and reserves including the carry cost","Close with title insurance covering access","Start construction-loan planning early: plans, builder, budget"],"incomeExample":{"title":"Illustrative land purchase: down payment, carry cost and rollover math","steps":["Parcel price $325,000 (5 acres, Temecula wine country); lender max LTV 70% (lender-specific)","Loan = $325,000 x 70% = $227,500; down payment = $97,500; closing costs incl. survey and perc test ~ $9,000","Illustrative monthly land-loan payment on a 15-year amortization ~ $1,900 (no rate quoted; use lender quote)","Annual carry: payment $22,800 + property tax ~1.1% x $325,000 = $3,575 + liability insurance $600 = ~$26,975/yr","Borrower's DTI must include the land payment with the current housing payment: rent $3,000 + land $1,900 + debts $500 = $5,400 vs income $14,000/mo = 38.6%","Two years later, construction-to-perm: land value $340,000 + build cost $650,000 = $990,000 total; at 80% loan-to-cost the loan is $792,000","Land equity = $340,000 - land balance ~ $205,000 = $135,000, which counts toward the 20% ($198,000) required equity; cash still needed ~ $63,000"],"result":"The $97,500 down payment plus about $27,000 a year in carry secures the lot; at build time, land equity covers roughly two-thirds of the construction loan's equity requirement. Illustrative figures only; lender LTVs, terms and appraisals vary."},"scenarios":[{"t":"Buy now, build in two years","who":"Steve, 40, aerospace engineer, Temecula","situation":"Steve found a 5-acre parcel in Temecula wine country for $325,000. He plans to design a custom home and build within two years. He rents now for $3,000 a month and earns $168,000. He has $140,000 saved.","structure":"Credit union or local bank land loan at 70% LTV; later rolled into a construction-to-perm loan","numbers":"See income example: $97,500 down; ~$27,000/yr carry","why":"Securing the lot now protects him from rising land prices while plans are drawn. A local lender understands rural parcels and wells. His land equity will count toward the construction loan's down payment later.","alternatives":"A one-time-close construction loan that includes the lot avoids two closings, but requires plans and a builder now. A seller carry-back may offer more flexible terms if the seller is willing.","watch":"Perc test, well yield and CAL FIRE severity zone affect buildability and insurance. Confirm the county allows his intended home size and any ADU."},{"t":"Raw desert parcel in Nevada","who":"Ann, 50, retired teacher, Pahrump NV","situation":"Ann wants a 2-acre parcel at $80,000 for a future manufactured home. Banks rarely lend small amounts on raw land. The seller offered to carry a note. Water depends on a domestic well permit.","structure":"Seller carry-back with 25% down, documented by an attorney and recorded","numbers":"Down $20,000; seller note $60,000","why":"Seller financing fills the gap where banks won't lend. Recording the deed of trust protects both parties. The small loan keeps her monthly obligation manageable on her pension.","alternatives":"Pay cash from savings to avoid any debt. A manufactured-home land/home package loan when she is ready to place the home.","watch":"Nevada water law and domestic well rules in Nye County must be verified before closing. Balloon terms on the note need a refinance plan."},{"t":"Improved lot in a planned subdivision","who":"Mike, 45, general contractor, Prescott AZ","situation":"Mike is buying a $150,000 lot with utilities in an HOA subdivision. He will build his own home next year. The HOA requires construction to start within 24 months. He has strong income and 20% down.","structure":"Bank lot loan at 75-80% LTV (lender-specific)","numbers":"Loan $112,500-$120,000","why":"Improved lots with utilities get better LTVs. His construction experience reassures lenders about the build plan. A bank that also offers construction loans can streamline the next step.","alternatives":"A one-time-close construction loan including the lot if his plans are ready. Cash purchase of the lot, then a standard construction loan.","watch":"HOA build-start deadlines can force a sale if missed. Some lenders won't let owner-builders act as their own contractor."},{"t":"Florida lot near wetlands","who":"Jane, 38, nurse, Ocala FL","situation":"Jane found a $90,000 lot priced below others nearby. Part of it borders wetlands and it sits partly in a flood zone. She wants to build in 2027. She has 25% down.","structure":"Bank land loan after flood, wetlands and survey review","numbers":"Loan $67,500","why":"The price reflects real constraints that must be understood before buying. A survey and wetlands delineation show the buildable area. Flood elevation requirements affect construction cost and insurance.","alternatives":"A different lot outside the flood zone, often worth the higher price. A construction-to-perm loan later, after the lot is evaluated.","watch":"Buildable area may be smaller than expected. Flood insurance cost for the future home must fit her budget."},{"t":"Adding farmland in Illinois","who":"Tom, 55, grain farmer, central Illinois","situation":"Tom wants to add 80 acres next to his farm for $900,000. The land has strong soil productivity ratings. He has a long relationship with a Farm Credit association. Current cash rents in the area support part of the payment.","structure":"Farm Credit real estate loan (business-purpose agricultural lending)","numbers":"Typical 65-75% LTV (lender-specific); $225,000-$315,000 down","why":"Agricultural lenders understand farmland values and seasonal cash flow. Long amortizations are available for farmland. Expanding adjacent acreage improves his operation's efficiency.","alternatives":"A local community bank with ag lending. A seller contract for part of the price.","watch":"Commodity price swings affect repayment. The appraisal must use agricultural comparables."}],"qa":[{"q":"How much down payment do I need to buy land?","a":"Typically 25-50%. Raw land without utilities sits at the high end, while improved lots in subdivisions often need 20-30%. Lenders set these individually."},{"q":"Can I use an FHA or VA loan to buy land?","a":"Not for land by itself. The lot can be included in an FHA, VA or conventional construction-to-permanent loan when you build a home (verify program)."},{"q":"Is seller financing a good idea for land?","a":"It's common and can work well. Have an attorney draft the note and deed of trust, record them, and plan for any balloon payment."},{"q":"What is a perc test and why does it matter?","a":"It measures whether soil can absorb water for a septic system. Without a passing perc test you may not get a septic permit, which can make the land unbuildable."},{"q":"How do I know I can actually build on the land?","a":"Verify zoning, minimum lot size, legal access, utilities or well and septic feasibility, and hazard zones with the county before closing. A land-use attorney or planner can help with complex parcels."},{"q":"Why are land loan terms shorter than home loans?","a":"Land is harder to value and slower to sell, so lenders limit their risk with shorter terms, balloons or adjustable rates."},{"q":"Can my land equity count toward a construction loan later?","a":"Usually yes. Many construction loans pay off the lot loan and count your land equity toward the required down payment."},{"q":"How do fire and flood zones affect land?","a":"They can make insurance expensive or unavailable and add building requirements. Check insurability before buying."},{"q":"Is a land loan subject to consumer protections?","a":"A lot bought for your future primary home is generally consumer credit with TRID disclosures. Land bought for investment or business may be business-purpose."}],"aeQuestions":["Max LTV for raw vs improved land?","Amortization, term and balloon options?","Minimum acreage or maximum acreage limits?","Do you require perc test and well certification before closing?","How do you treat land equity in a later construction loan?","Appraisal requirements and comps tolerance?","Do you lend in high fire hazard severity zones?","Turn times?","Broker fee policy and disclosure?"],"redFlags":["No recorded legal access","Unknown or unavailable water source","Failed or missing perc test","Zoning doesn't allow intended use","Very high fire or flood risk without insurance plan","Seller unable to deliver clear title"],"pricing":"Land loans generally carry higher pricing and shorter terms than home loans because collateral is less liquid. Compare a stand-alone land loan with a construction-to-perm that includes the lot. Show total costs including survey, perc and appraisal. Disclose all fees. Broker compensation never drives lender choice: originator pay cannot vary with loan terms and steering for higher compensation is prohibited (12 CFR 1026.36(d)/(e)); Steven applies the same standard on business-purpose land loans and discloses all fees in writing.","marketing":["Land brokers and rural agents","Custom home builders and ADU builders","County planning seminars","Farm bureau and agricultural groups","Content: 'Before you buy land, check these 10 things'"],"checklist":["Purchase contract","Preliminary title and easements","Survey","Zoning verification","Perc test","Well report/water availability","Utility will-serve letters","Hazard reports (fire/flood)","Appraisal","Borrower income and assets","Construction plans (if building soon)","Insurance quote"],"updated":"2026-11"},
"c_hecm":{"matrix":[["Minimum age","62 for youngest borrower (verify)"],["2026 max claim amount","$1,249,125 nationwide (HUD ML 2025-22, case numbers 1/1/2026-12/31/2026)"],["Upfront MIP","2% of maximum claim amount (verify)"],["Annual MIP","0.5% of outstanding balance (verify)"],["First-year disbursement limit","Greater of 60% of principal limit or mandatory obligations + 10% (verify)"],["Counseling","HUD-approved HECM counseling required before application"],["Financial assessment","Credit, property-charge history and residual income; LESA may be required (verify)"],["Occupancy","Principal residence; certify annually"],["Residency","U.S. citizen or LPR; non-permanent residents ineligible per ML 2025-09 for case numbers on/after 5/25/2025 (verify)"],["Property types","1-4 units owner-occupied, FHA-approved condos (or single-unit approval - verify), eligible manufactured homes built after 6/15/1976"],["Non-borrowing spouse","Eligible NBS deferral if conditions met (verify)"],["Payment options","Lump sum (fixed), line of credit with growth, tenure, term, combinations (ARM)"]],"walkthrough":["Discovery call: goals, age of youngest spouse, home value, liens, cash-flow needs","Send HUD-approved counseling agency list; counseling must be completed before application","Run comparison: HECM vs HELOC vs cash-out vs downsizing","Order credit and gather property-charge history for financial assessment","Collect ID, residency proof, income, insurance, tax bills","Order FHA appraisal; review repairs","Underwriter completes financial assessment; LESA determination","Choose payment plan; confirm first-year disbursement limits","Closing with 3-day right of rescission","Post-closing: annual occupancy certification, taxes/insurance education","Set calendar reminder for future HECM-to-HECM review or LOC check-ins"],"incomeExample":{"title":"Illustrative HECM proceeds (no rates quoted)","steps":["Appraised value $900,000; MCA = lesser of value or $1,249,125 = $900,000","Assume illustrative principal limit factor 0.45 (age/rate dependent - verify with calculator)","Principal limit = $900,000 x 0.45 = $405,000","Upfront MIP 2% x $900,000 = $18,000; other closing costs say $12,000","Existing mortgage payoff $150,000 (mandatory obligation)","Mandatory obligations = $150,000 + $30,000 costs = $180,000","Remaining principal limit = $405,000 - $180,000 = $225,000 available as LOC/other per first-year limits"],"result":"Borrower eliminates a $150,000 mortgage payment and keeps roughly $225,000 of principal limit available, subject to first-year limits and LESA. Illustrative only."},"scenarios":[{"t":"Eliminate a mortgage payment on a fixed income","who":"Linda, 68, retired teacher, Temecula","situation":"Linda owes $210,000 on a home worth $780,000. Her pension and Social Security total $4,600 a month, and her $1,650 mortgage payment strains the budget. She wants to stay near her grandchildren. Her credit and tax payment history are clean.","structure":"Adjustable-rate HECM paying off the mortgage, with the remainder as a line of credit","numbers":"MCA $780,000; illustrative principal limit ~ $330,000; payoff $210,000 + costs ~ $30,000; LOC ~ $90,000","why":"Removing the required P&I payment frees about $1,650 a month. The remaining line of credit grows on the unused balance as a reserve. Her clean property-charge history should avoid a LESA.","alternatives":"Downsizing to a smaller home in Murrieta would free equity but uproot her. A rate-and-term refinance to a longer term would lower but not eliminate the payment and requires income qualification.","watch":"First-year disbursement limits cap how much of the LOC she can use initially. Her daughter should attend counseling so heirs understand the payoff options."},{"t":"Line of credit as a longevity reserve","who":"Robert, 74, retired engineer, Carlsbad","situation":"Robert's $1.4M home is free and clear and his portfolio covers living costs. His planner suggests a standby line of credit to draw in down markets instead of selling investments. He has no immediate need for cash. He understands the line grows over time.","structure":"Adjustable HECM line of credit at the $1,249,125 2026 maximum claim amount","numbers":"MCA $1,249,125; illustrative principal limit ~ $600,000+ (verify)","why":"An unused HECM line of credit grows at the loan's rate plus MIP. Drawing in down markets can protect portfolio longevity. The line can't be frozen or reduced for market reasons like a HELOC can.","alternatives":"A proprietary jumbo reverse could provide more on a $1.4M home but often lacks line-of-credit growth. A HELOC costs less upfront but requires payments and can be frozen.","watch":"Upfront MIP of 2% of the MCA is a real cost for a line he may not use. Coordinate strategy with his planner; we give no investment advice."},{"t":"Protecting a younger non-borrowing spouse","who":"Gary, 66, and Maria, 59, Escondido","situation":"Gary is 66 and Maria is 59, too young to be a borrower. They want to pay off a $180,000 mortgage. Both want assurance that Maria can stay if Gary dies first. Their home is worth $720,000.","structure":"HECM with Gary as borrower and Maria as an eligible non-borrowing spouse with deferral protections (verify)","numbers":"Principal limit based on Maria's age, lowering proceeds","why":"The eligible NBS deferral lets Maria remain in the home after Gary's death if conditions are met. Paying off the mortgage still frees cash flow. Using Maria's age protects her even though it reduces proceeds.","alternatives":"Waiting until Maria is 62 would allow both as borrowers with higher proceeds. A proprietary reverse with a lower age minimum may be available in some states (verify).","watch":"Maria must remain married to Gary and occupy the home to keep deferral. Proceeds may not cover the payoff at her younger age."},{"t":"Tenure payments to fund in-home care","who":"Helen, 81, widow, San Diego","situation":"Helen owns her $750,000 home free and clear and needs a part-time caregiver costing about $2,500 a month. Her Social Security is $2,200. Her son lives nearby and helps manage bills. She wants to stay home as long as possible.","structure":"HECM tenure payment plan providing monthly payments for as long as she lives in the home","numbers":"Monthly tenure amount calculated by lender based on age and principal limit","why":"Tenure payments create a steady income stream for care. Her higher age increases the principal limit. No repayment is required while she occupies the home.","alternatives":"Selling and moving to assisted living would provide a lump sum but end her independence. A line of credit offers flexibility for irregular care costs.","watch":"An absence of more than 12 consecutive months for medical reasons can make the loan due. Her son's role must support, not direct, her decision."},{"t":"Paying off a HELOC entering repayment","who":"Tom, 70, retired contractor, Las Vegas","situation":"Tom's $120,000 HELOC is converting from interest-only to amortizing, nearly doubling the payment. His home is worth $500,000. His income is Social Security and a small pension. He wants predictable costs.","structure":"HECM paying off the HELOC","numbers":"Value $500,000; illustrative principal limit ~ $200,000; payoff $120,000","why":"Eliminates the payment shock entirely. The remaining principal limit provides a modest reserve. A fixed-income retiree benefits from no required P&I.","alternatives":"A closed-end home equity loan would fix the payment but still require it. Refinancing into a 30-year first mortgage could lower the payment if income qualifies.","watch":"Nevada property taxes and insurance must be paid on time to avoid default. The remaining reserve is limited."}],"qa":[{"q":"Do I still own my home with a reverse mortgage?","a":"Yes. Title stays in your name. You must pay property taxes, insurance and HOA dues, maintain the home and live there as your principal residence."},{"q":"What happens when I pass away?","a":"The loan becomes due. Your heirs can sell, refinance or pay the lesser of the balance or 95% of the appraised value, and because it's non-recourse they never owe more than the home is worth."},{"q":"Can I lose my home?","a":"Yes, if you don't pay property charges, don't maintain the home or stop living there. The financial assessment and, when needed, a LESA help prevent that."},{"q":"Does it affect Social Security or Medicare?","a":"Generally no. Needs-based benefits like Medi-Cal or SSI can be affected by how you hold the proceeds, so talk to a benefits advisor."},{"q":"Is counseling required?","a":"Yes, from a HUD-approved counselor before you apply. The counselor is independent of the lender."},{"q":"Can I make payments if I want to?","a":"Yes. Voluntary payments are allowed without penalty and, on an adjustable HECM, can restore line-of-credit capacity."},{"q":"Is there an income requirement?","a":"There's no minimum income, but the financial assessment reviews residual income and your history paying property charges. Shortfalls may lead to a set-aside (LESA)."},{"q":"Can a non-citizen get a HECM?","a":"U.S. citizens and lawful permanent residents are eligible. Non-permanent residents became ineligible for case numbers assigned on or after May 25, 2025 under ML 2025-09 (verify)."}],"aeQuestions":["What's your current PLF table and expected rate floor treatment?","How do you handle LESA - fully funded vs partially funded?","Single-unit condo approval turnaround for HECM?","Turn times for appraisal review and financial assessment?","Do you allow NBS with trusts?","Investor requirements for manufactured homes?","Broker comp structure and plan details (no loan-term-based comp)?","Do you offer HECM for Purchase and H2H?","What's your process for repairs set-asides?","How do you verify LPR status post-ML 2025-09?"],"redFlags":["Family member pushing for loan or controlling proceeds","Borrower confused about non-recourse/occupancy","Delinquent property taxes or insurance lapses","Request to buy annuity or investment with proceeds (CA prohibits cross-selling)","Planning to move out within a year","Unpermitted additions affecting appraisal"],"pricing":"HECM pricing involves margin selection, which trades off principal limit against lender credit. Explain upfront MIP of 2% of MCA and annual 0.5%. Compare scenarios with lower margins vs higher lender credits and how they affect LOC growth. Disclose all costs clearly. Never let broker compensation influence which lender or program is chosen; loan originator compensation cannot vary by loan terms and steering to increase compensation is prohibited (12 CFR 1026.36(d)/(e)).","marketing":["Seminars at senior centers on 'Using home equity in retirement'","Partner with financial planners on LOC strategies","Educational mailers to 62+ homeowners (compliant, no misleading 'government program' language)","Steven's Navy retiree network outreach","Blog/video: HECM myths vs facts"],"checklist":["Counseling certificate","ID and residency proof","Mortgage statements","Property tax bills","Insurance declarations","Income docs","Credit report","Appraisal","Financial assessment worksheet","LESA calculation","Payment plan election","Right of rescission","NBS certifications if applicable","Trust docs if vested in trust"],"updated":"2026-11"},
"c_hecm_purchase":{"matrix":[["Age","62+ (verify)"],["Down payment source","Borrower's own funds; no seller concessions toward down payment; no borrowed funds (verify)"],["Occupancy","Within 60 days of closing (verify)"],["MCA","Lesser of price, appraised value or $1,249,125 (2026)"],["Property","1-4 units; new construction must have CO (verify)"],["Seller contributions","Limited; certain costs only (verify)"],["Counseling","Required"],["Financial assessment","Required"],["Residency","U.S. citizen or LPR (verify)"],["Interested-party rules","Per HUD (verify)"]],"walkthrough":["Clarify the move: why, where, timeline, and whether the current home sells first","Confirm youngest borrower is 62+ and that each borrower is a U.S. citizen or permanent resident (ML 2025-09)","Estimate required down payment from the principal limit at the youngest age, using the lesser of price or $1,249,125","Refer to a HUD-approved counselor; the certificate must be dated before application","Verify the source of down payment (sale proceeds, savings); borrowed funds and most seller concessions are not allowed (verify)","Complete financial assessment early: credit, property-charge history, residual income","Brief the listing and buyer's agents on HECM for Purchase timelines and appraisal requirements","Write the offer with realistic financing and appraisal contingencies","Order FHA appraisal; address any required repairs","Determine LESA if needed and confirm property charges budget in the new location","Close with funds to close verified; coordinate simultaneous sale if applicable","Confirm occupancy within 60 days and give the annual occupancy certification calendar"],"incomeExample":{"title":"Illustrative HECM for Purchase down payment","steps":["Purchase price $700,000","Illustrative PLF 0.50 at age 70 (verify)","Principal limit $350,000","Upfront MIP 2% x $700,000 = $14,000; other costs $10,000","Net loan amount available for purchase ~ $326,000","Down payment needed ~ $700,000 - $326,000 = $374,000 plus prepaid items"],"result":"Buyer brings roughly $374,000 (often from sale of prior home) and has no required monthly mortgage payment. Illustrative."},"scenarios":[{"t":"Downsizing from Chicago to be near grandchildren","who":"Carol, 71, retired nurse, moving from Chicago to Temecula","situation":"Carol sold her Chicago bungalow for $500,000 and wants a $650,000 single-level home near her daughter. Her income is a $2,600 pension plus $2,100 Social Security. She doesn't want a mortgage payment in retirement. She wants to keep about $150,000 in savings.","structure":"HECM for Purchase using sale proceeds as the down payment","numbers":"Illustrative principal limit ~ $300,000; down payment ~ $350,000 + prepaids","why":"She buys the home she wants with no required monthly principal and interest. Her remaining sale proceeds stay as savings. The FHA-insured loan is non-recourse for her heirs.","alternatives":"Pay cash for a less expensive home around $500,000, avoiding loan costs but leaving little reserve. A conventional mortgage would keep more cash but adds a monthly payment on a fixed income.","watch":"Financial assessment must show she can pay taxes, insurance and HOA in California. The home must be occupied within 60 days."},{"t":"Navy Chief needs a single-level home","who":"Jim, 76, retired Navy Chief, San Diego","situation":"Jim's two-story Clairemont home is no longer safe after knee surgery. He has $780,000 of equity and receives military retirement and VA disability. He found an $800,000 single-level home in Escondido. He wants to keep cash for medical costs.","structure":"Sell current home; HECM for Purchase on the new home","numbers":"Illustrative principal limit at 76 ~ $380,000; down payment ~ $420,000","why":"Accessibility is the main goal. Using only part of his equity as down payment leaves cash for care. No required monthly payment protects his income.","alternatives":"Remodel the current home with a HECM line of credit if a stair lift and first-floor bedroom are feasible. A cash purchase of a smaller condo would avoid loan costs.","watch":"VA disability income is non-taxable; ensure financial assessment counts it properly. Simultaneous closing timing must work."},{"t":"New construction in a 55+ community","who":"Patricia, 68, retired accountant, Henderson NV","situation":"Patricia is buying a $550,000 new home in an active-adult community. The builder is offering incentives. Construction completes in four months. She has $400,000 from selling her prior home.","structure":"HECM for Purchase closing after certificate of occupancy","numbers":"Illustrative principal limit ~ $260,000; down ~ $290,000","why":"She gets a new home with no mortgage payment. Leftover proceeds of about $100,000 stay invested. The builder's timeline fits HECM closing after completion.","alternatives":"Cash purchase if she prefers no debt. A conventional loan with a larger down payment if she wants lower upfront costs.","watch":"Builder incentives may count as prohibited seller concessions (verify). Closing must wait for the certificate of occupancy."},{"t":"Moving closer to medical care","who":"Ed, 80, retired engineer, Scottsdale","situation":"Ed lives in rural Arizona, two hours from his specialists. He wants a $600,000 home near a Scottsdale hospital. His wife passed last year and his income is Social Security plus a small pension. He has $380,000 from his home sale.","structure":"HECM for Purchase","numbers":"Illustrative principal limit at 80 ~ $310,000; down ~ $290,000","why":"Proximity to care improves his quality of life. Higher age increases the principal limit, reducing the down payment. He keeps about $90,000 in reserve.","alternatives":"Rent near the hospital and keep all sale proceeds liquid. Move into a continuing care community if he needs more support.","watch":"Health changes that require moving out for over 12 months can make the loan due. Discuss his long-term care plans."},{"t":"Florida retirement move with insurance costs","who":"Susan, 66, retired teacher, moving from Illinois to Sarasota","situation":"Susan is buying a $500,000 home in Sarasota with proceeds from her Illinois home. Her teacher pension is $3,800 a month. Florida homeowners insurance quotes are much higher than she expected. She wants no mortgage payment.","structure":"HECM for Purchase with possible LESA for property charges","numbers":"Illustrative principal limit ~ $220,000; down ~ $280,000","why":"No required payment protects her fixed income. A LESA, if required, sets aside funds for taxes and insurance. She keeps some cash for hurricane deductibles.","alternatives":"A smaller condo with lower insurance costs. A conventional loan if she prefers to keep more cash.","watch":"Insurance premium increases must be budgeted. Flood insurance may be required."}],"qa":[{"q":"Can the seller pay my closing costs on a HECM for Purchase?","a":"Only limited, customary items are allowed. Most seller concessions toward the down payment or costs are restricted, so we review the contract before signing (verify HUD rules)."},{"q":"Do I have to sell my current home first?","a":"Not necessarily, but your down payment must come from your own documented funds, not a loan. Many buyers close the sale and purchase on the same day or shortly apart."},{"q":"Can I buy a condo?","a":"Yes, if the project is FHA-approved or eligible under current HECM condo rules (verify). We check approval before you make an offer."},{"q":"Will I have a monthly mortgage payment?","a":"There's no required principal and interest payment. You must still pay property taxes, insurance and HOA dues and maintain the home."},{"q":"Can my heirs keep the home?","a":"Yes. They can pay off the lesser of the loan balance or 95% of the appraised value, or sell and keep any remaining equity."},{"q":"Can I buy new construction?","a":"Yes, once a certificate of occupancy is issued (verify). Builder incentives may be limited."},{"q":"Can I use a bridge loan for the down payment?","a":"Generally no. Borrowed funds are not allowed for the required investment (verify)."},{"q":"How long does it take?","a":"Typically 30-45 days after counseling, similar to a standard purchase. Counseling should be scheduled as soon as you start shopping."},{"q":"How soon must I move in?","a":"Generally within 60 days of closing (verify). You'll certify occupancy each year."}],"aeQuestions":["What seller concessions do you allow on HECM for Purchase?","New construction requirements (CO, builder certifications)?","How do you treat proceeds from the sale of the prior home closing simultaneously?","Bridge loan or HELOC funds for down payment: allowed?","Condo eligibility for HECM purchase?","Financial assessment and LESA approach for buyers relocating from another state?","Turn times and appraisal review?","Margin options and effect on down payment?","Broker comp plan (no term-based comp)?"],"redFlags":["Down payment from undisclosed loan","Seller paying non-allowed costs","Borrower not intending to occupy","Pressure from family","Unrealistic expectations on proceeds","Agents unfamiliar with timing"],"pricing":"HECM for Purchase pricing is margin-based; a lower margin can increase principal limit and reduce the required down payment, while lender credits can offset closing costs. Explain the 2% upfront MIP on the lesser of price, value or $1,249,125 and the 0.5% annual MIP. Compare against buying with cash or a conventional mortgage. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons.","marketing":["Workshops for 55+ community sales offices","Agent CE classes on HECM purchase","Senior relocation specialists","Retirement planners","Mailers to downsizers"],"checklist":["Counseling certificate","Purchase contract","Down payment source docs","ID/residency proof","Income docs","Credit","Appraisal","Financial assessment","Insurance","Title","Occupancy certification"],"updated":"2026-11"},
"c_hecm_h2h":{"matrix":[["Seasoning","Generally 18 months since the existing HECM closed (verify)"],["Benefit (anti-churning) test","Increase in principal limit typically must be at least 5x the total cost of the refinance (verify current HUD rule)"],["Counseling","Required; HUD permits a waiver only in limited H2H cases with specific disclosures (verify)"],["Upfront MIP","Credit for MIP paid on the prior HECM reduces the new upfront MIP (verify)"],["2026 max claim amount","$1,249,125 (ML 2025-22)"],["Financial assessment","Full financial assessment on the new loan; LESA possible"],["Non-borrowing spouse","Refinance can add a now-62 spouse as a borrower"],["Residency","U.S. citizen or LPR; non-permanent residents ineligible for new case numbers since 5/25/2025 (verify)"],["Disclosures","Anti-churning disclosure showing costs vs. benefits (verify)"],["Payment plans","Can change from fixed lump sum to adjustable LOC or vice versa"]],"walkthrough":["Pull the current HECM statement: balance, LOC remaining, margin, MIP paid, closing date","Confirm 18-month seasoning and the client's goal (more LOC, add spouse, lower margin, switch plan)","Estimate new value and run new principal limit at current age and expected rate","Compute total refinance costs and run the 5x benefit test before ordering anything","Refer to a HUD-approved counselor (or confirm waiver eligibility with lender)","Issue anti-churning disclosure and comparison worksheet","Order FHA appraisal; review repairs","Complete financial assessment; determine whether LESA applies","Choose payment plan; confirm first-year disbursement rules","Close with 3-day right of rescission; confirm old HECM payoff and MIP credit","Set an annual review reminder to re-check value and LOC"],"incomeExample":{"title":"Illustrative H2H benefit test (no rates)","steps":["Existing HECM principal limit (from statement): $300,000","New value $950,000; illustrative new principal limit factor 0.46 at age 78 (verify)","New principal limit = $950,000 x 0.46 = $437,000","Increase in principal limit = $437,000 - $300,000 = $137,000","Total refinance costs (net of MIP credit) = $22,000; 5 x $22,000 = $110,000","$137,000 >= $110,000, so the illustrative benefit test passes (verify current test)"],"result":"The refinance appears to provide a meaningful increase relative to cost; still confirm the client's goal is served and disclose that the balance and accruals increase. Illustrative only."},"scenarios":[{"t":"Value growth unlocks more LOC","who":"Frank, 78, retired aerospace engineer, Escondido","situation":"Frank took a HECM in 2017 when his home was worth $560,000 and the limit was lower. His home is now worth about $950,000. His wife may need in-home care within a few years. His current line of credit has about $60,000 remaining.","structure":"Adjustable H2H with larger line of credit","numbers":"Illustrative new principal limit ~$437,000 vs. $300,000 existing; costs ~$22,000 net of MIP credit","why":"The refinance passes the illustrative benefit test with room to spare. A larger line of credit provides a care reserve. Credit for prior MIP reduces the cost of refinancing.","alternatives":"Keep the existing HECM and draw the remaining line first, refinancing only if care needs materialize. A HELOC is unlikely to be approved on his fixed income.","watch":"Refinance only for a documented need such as care costs, not because value rose. The 5x benefit test and 18-month seasoning must both be met (verify)."},{"t":"Add a spouse who turned 62","who":"Nancy, 70, and Luis, 62, Henderson NV","situation":"Nancy took a HECM alone before marrying Luis. Luis just turned 62 and is not protected as a non-borrowing spouse because he wasn't her spouse at closing. If Nancy dies first, Luis could have to leave. Their home is worth $520,000.","structure":"H2H adding Luis as co-borrower","numbers":"Value $520,000; PLF based on Luis's younger age lowers principal limit","why":"Adding Luis as a borrower protects his right to stay for life. That protection is worth more to them than maximizing proceeds. The refinance also updates the loan to current terms.","alternatives":"Leave the loan as-is and plan for Luis to refinance or buy the home later, which is risky. A proprietary reverse naming both could work if the HECM benefit test fails.","watch":"Basing the principal limit on Luis's younger age may cause the benefit test to fail. Explain the protection-versus-proceeds trade-off in writing."},{"t":"Old loan capped by earlier limit","who":"George, 75, retired dentist, Irvine","situation":"George's original HECM was capped at a much lower maximum claim amount than today's $1,249,125. His home is now worth about $1.5M. He wants a larger reserve for travel and gifts to grandchildren. He has no mortgage other than the HECM.","structure":"H2H to the 2026 $1,249,125 MCA, or compare proprietary jumbo reverse","numbers":"MCA rises to $1,249,125; principal limit increase significant","why":"The higher 2026 limit substantially increases his principal limit. The benefit test likely passes. Comparing with a proprietary option ensures he picks the best fit.","alternatives":"A proprietary jumbo reverse may provide more on a $1.5M home without MIP. Keeping the current HECM avoids new costs if his needs are modest.","watch":"Compare total costs against a no-MIP proprietary option side by side. Confirm the benefit test before ordering the appraisal."},{"t":"Switch from fixed lump sum to LOC","who":"Anne, 72, retired librarian, Tucson","situation":"Anne took a fixed-rate lump sum years ago and spent most of it on a roof and medical bills. She now wants flexible access to remaining equity. Her balance is $180,000 and her home is worth $430,000. A fixed HECM has no line of credit.","structure":"Adjustable H2H with LOC","numbers":"Value $430,000; balance $180,000","why":"An adjustable HECM provides a line of credit she can draw as needed. Unused credit grows over time. The new principal limit reflects her older age and higher value.","alternatives":"Keep the fixed HECM and use savings for future needs. A small HELOC is unlikely on her income.","watch":"A growing balance makes the benefit test harder to pass. First-year disbursement limits apply to the new line of credit."},{"t":"Margin improvement only","who":"Joe, 80, retired pilot, Orlando","situation":"Joe heard that refinancing might lower his loan's accrual rate. His principal limit would increase only modestly. Costs would be about $20,000. He doesn't need more cash.","structure":"Run H2H analysis","numbers":"Principal limit increase small relative to costs","why":"The analysis shows the benefit test likely fails. Refinancing would add costs without real benefit. Documenting a no-refinance recommendation protects him.","alternatives":"Keep the current HECM and make voluntary payments if he wants to slow balance growth. Revisit in a few years if values rise.","watch":"Record the analysis and recommendation in the file. Watch for anyone else pressuring him to refinance."}],"qa":[{"q":"How soon can I refinance my HECM?","a":"Generally 18 months after the current HECM closed. The new loan must also pass HUD's benefit test (verify current rules)."},{"q":"Do I pay the 2% upfront MIP again?","a":"You generally receive credit for upfront MIP paid on the prior HECM, which reduces the new premium (verify calculation)."},{"q":"Is counseling required again?","a":"In most cases yes. HUD allows a limited waiver in certain HECM-to-HECM situations with specific disclosures (verify)."},{"q":"Will my heirs owe more?","a":"The balance and accruals continue on the new loan. It remains non-recourse, so heirs never owe more than the home's value."},{"q":"Can I add my spouse?","a":"Yes, if they're 62 or older and meet requirements. This is one of the most common reasons to refinance."},{"q":"Could a proprietary reverse be better?","a":"For homes worth well above $1,249,125, it can produce more proceeds. We compare both side by side."},{"q":"What costs are involved?","a":"Origination, third-party fees such as appraisal and title, and upfront MIP net of credit. Every cost is disclosed before you decide."},{"q":"What if the benefit test fails?","a":"Then we don't proceed. Keeping your existing HECM is often the right answer, and we document that recommendation."},{"q":"Does my line of credit growth restart?","a":"The new line of credit is based on the new principal limit. Unused amounts then grow at the loan's rate plus MIP."}],"aeQuestions":["How do you calculate the 5x benefit test and what costs count?","How is the prior MIP credit applied?","Counseling waiver policy for H2H?","Do you handle NBS-to-borrower additions?","Appraisal review requirements for H2H?","Margin options and how they affect LOC growth?","Turn times from case number to closing?","How do you verify residency status post-ML 2025-09?","Broker comp plan structure (no loan-term-based comp)?","Do you also offer proprietary reverse for comparison?"],"redFlags":["Refinance proposed mainly to generate fees (churning)","Borrower cannot articulate a need for the new funds","Family member directing the transaction","Costs close to or exceeding the benefit threshold","Property charges delinquent","Cognitive decline concerns; elder abuse warning signs"],"pricing":"H2H pricing combines margin choice, origination fee and MIP net of prior credit. Present a written comparison showing the existing loan versus the proposed refinance, including principal limit increase, total costs and the benefit test math. Discuss how margin choice affects both principal limit and future accruals. If the benefit is marginal, recommend staying put and document that advice. Broker compensation never drives lender or program choice: loan originator pay cannot vary with loan terms, and steering a borrower to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide every disclosure required for H2H transactions.","marketing":["Annual 'reverse mortgage check-up' letters to past HECM clients","Co-host workshops with financial planners on LOC strategy","Explain the 2026 HECM limit increase in newsletters","Partner with estate attorneys for spouse-protection reviews","Short video: when a HECM refinance makes sense and when it doesn't"],"checklist":["Current HECM statement and payoff","Seasoning verification","Benefit test worksheet","Counseling certificate or waiver documentation","Anti-churning disclosure","Appraisal","ID and residency documentation","Property tax and insurance proof","Financial assessment worksheet","LESA calculation if applicable","Spouse documentation if adding borrower","Right of rescission","Title report"],"updated":"2026-11"},
"c_jumbo_reverse":{"matrix":[["Minimum age","Typically 62; some lenders offer 55+ in certain states (verify state/lender)"],["Maximum loan","Lender-specific; often up to $4M or more (verify)"],["Mortgage insurance","None (not FHA-insured)"],["Property types","SFR, many non-FHA condos, some 2-4 units (lender-specific)"],["Counseling","Required by many lenders and state laws (verify)"],["Financial assessment","Lender-specific; LESA-like set-asides possible"],["Draw options","Fixed lump sum common; some adjustable LOC versions (lender-specific)"],["Non-recourse","Typically non-recourse (verify loan terms)"],["Residency","Lender-specific; verify status requirements"],["State availability","Not available in all states (verify CA/IL/NV/FL/AZ)"]],"walkthrough":["Confirm age of youngest borrower, home value, existing liens and the client's goal (eliminate payment, reserve, lump sum)","Check whether the HECM cap of $1,249,125 limits proceeds; if value is well above it, a proprietary product may yield more","Confirm the proprietary product is offered in the property's state and at the client's age (some offer 55+ in certain states - verify)","Run HECM and proprietary illustrations side by side: net proceeds, costs, balance growth, draw options","Refer to independent counseling where the lender or state requires it, and confirm completion before application","Screen for elder-financial-abuse signs and confirm the client is making the decision","Review condo or HOA eligibility, title, trusts and any non-borrowing spouse","Order appraisal(s); high values may require two appraisals or a review (lender-specific)","Underwrite including the lender's financial review and any property-charge set-aside","Present the final comparison and explain the non-recourse language in the note","Close; observe the 3-day right of rescission","Post-closing, review property taxes, insurance and maintenance responsibilities with the client"],"incomeExample":{"title":"Illustrative proprietary vs HECM comparison","steps":["Home value $2,500,000","HECM: MCA capped at $1,249,125; illustrative PLF 0.45 = ~$562,000","Proprietary: illustrative lender advance rate 0.38 x $2,500,000 = $950,000 (lender-specific)","Existing mortgage payoff $400,000","HECM net ~ $562,000 - $400,000 - costs","Proprietary net ~ $950,000 - $400,000 - costs"],"result":"For high-value homes, proprietary products may produce substantially more proceeds without MIP, though terms differ. Illustrative only."},"scenarios":[{"t":"Coastal home well above the HECM cap","who":"Margaret, 72, retired attorney, La Jolla","situation":"Margaret owns a $3M home with a $500,000 mortgage. Her income covers living costs but the mortgage payment strains her budget. She wants to stay in the home for life. Her investment portfolio is meant for her grandchildren's education.","structure":"Proprietary fixed-rate or line-of-credit reverse mortgage (lender-specific)","numbers":"Illustrative advance rate 0.35-0.40 x $3M = $1.05M-$1.2M gross; payoff $500,000","why":"A HECM would be limited to $1,249,125 of value, sharply reducing proceeds. A proprietary product can pay off her mortgage and leave a reserve. There is no FHA mortgage insurance premium.","alternatives":"A HECM still pays off her mortgage but leaves less reserve, though it offers federally insured LOC growth. Selling and downsizing would release more equity but she wants to stay.","watch":"A fixed lump sum accrues on the full amount from day one. Confirm non-recourse language and how heirs settle the loan."},{"t":"High-rise condo that isn't FHA-approved","who":"Paul, 69, retired executive, Miami","situation":"Paul's $900,000 high-rise condo is not FHA-approved, so a HECM isn't available. His building recently completed milestone inspections and set reserves under Florida's condo safety law. He has a $150,000 mortgage. He wants to stop making payments.","structure":"Proprietary reverse mortgage accepting non-FHA condos (lender review)","numbers":"Value $900,000; payoff $150,000","why":"Proprietary lenders review condos under their own criteria. Paying off the mortgage reduces his fixed costs. His building's completed inspections help project review.","alternatives":"A HELOC if his income supports payments. Selling and buying a condo in an FHA-approved building with HECM for Purchase.","watch":"Future special assessments are his obligation. Insurance costs in South Florida must fit his budget."},{"t":"Arizona borrower under 62","who":"Linda, 58, consultant winding down, Scottsdale","situation":"Linda wants to reduce work and retire early. She owns a $1.2M home with a $300,000 mortgage. HECM eligibility starts at 62. A few proprietary lenders offer products at 55+ in certain states (verify Arizona availability).","structure":"Proprietary 55+ reverse mortgage if available in Arizona (verify)","numbers":"Value $1.2M; lower advance rate at her age","why":"It eliminates her mortgage payment as her income declines. Proceeds at 58 are lower than at 62, so the payoff must fit. The product may bridge to a later HECM refinance.","alternatives":"A HELOC while she still has income, then a HECM at 62. Downsizing in the Phoenix area.","watch":"Younger age means more years of accrual. Verify state availability before discussing details."},{"t":"Large mortgage on a Newport Beach home","who":"Richard, 75, retired developer, Newport Beach","situation":"Richard has a $1.1M interest-only jumbo resetting soon. His home is worth $3.2M. His income has dropped and the reset payment would be unaffordable. He and his wife want to stay.","structure":"Proprietary reverse mortgage paying off the jumbo","numbers":"Illustrative proceeds ~ $1.2M+ vs payoff $1.1M + costs","why":"Removes the payment shock entirely. The value supports enough proceeds to clear the loan. It avoids a forced sale in a difficult market.","alternatives":"Sell and buy smaller for cash, freeing substantial equity. Refinance into a new jumbo if income can be documented through asset depletion.","watch":"Proceeds may barely cover the payoff, leaving little reserve. Confirm his wife's protection if she is younger or not on title."},{"t":"Estate liquidity request with family involvement","who":"Diane, 80, widow, Incline Village NV","situation":"Diane's $2M home is free and clear. Her son is pushing for a large lump sum to fund his business. Diane says she wants to help but seems unsure. She has adequate retirement income.","structure":"Pause; discuss with Diane privately; counseling; only proceed if her own goals are served","numbers":"Value $2M; any lump sum accrues from day one","why":"Her interests must drive the decision. A reverse mortgage may not be needed given her income. Elder financial abuse indicators require care and possible escalation under company policy.","alternatives":"A smaller line of credit she controls. A gift through her estate attorney with full advice.","watch":"Document her independent decision. Follow company elder-abuse reporting procedures if warranted."}],"qa":[{"q":"Is a jumbo reverse mortgage insured by FHA?","a":"No. It's a private (proprietary) product, so there's no FHA mortgage insurance premium. Terms, fees and protections are set by the lender and state law."},{"q":"Is it non-recourse like a HECM?","a":"Most proprietary reverse loans are non-recourse, so neither you nor your heirs owe more than the home's value. Confirm the exact language in the loan documents."},{"q":"Can I get one before age 62?","a":"Some lenders offer products starting at 55 in certain states. Availability in California, Illinois, Nevada, Florida and Arizona must be verified, and proceeds are lower at younger ages."},{"q":"Will it work for my condo?","a":"Often yes, including many condos that aren't FHA-approved. The lender reviews the project's budget, insurance and litigation."},{"q":"How much can I receive?","a":"It depends on your age, home value, interest rates and the lender's advance rates. For homes worth well above $1,249,125, proceeds often exceed what a HECM can provide."},{"q":"Is there a line of credit option?","a":"Some proprietary products offer lines of credit, but many are fixed-rate lump sums. A lump sum accrues interest on the full amount immediately, so we compare both."},{"q":"What happens when I pass away?","a":"The loan becomes due. Your heirs can sell the home, refinance or pay it off, and they keep any remaining equity."},{"q":"Is counseling required?","a":"Many lenders and some states require independent counseling. We make sure it's completed before application where required."},{"q":"Do I still pay property taxes and insurance?","a":"Yes. Failing to pay property charges or maintain the home can put the loan in default."}],"aeQuestions":["What are your advance rates by age and value band?","Minimum age by state for CA, IL, NV, FL and AZ?","Maximum loan amount and maximum value considered?","Condo and non-warrantable project criteria?","Fixed lump sum vs. line of credit options and draw rules?","Exact non-recourse language in the note?","Set-aside requirements for taxes/insurance?","Appraisal requirements (one or two) for high values?","Turn times from application to closing?","Broker comp plan structure (no term-based comp)?"],"redFlags":["Family member or advisor pushing for a lump sum the borrower doesn't need","Borrower confused about non-recourse terms, occupancy or due-and-payable events","Delinquent property taxes, HOA dues or lapsed insurance","Request to buy an annuity or insurance product with proceeds (CA prohibits tying - verify)","Plans to move out within a year","Product not available in the property's state or at the borrower's age","Proceeds barely cover payoff, leaving no reserve for property charges","Unpermitted additions or deferred maintenance affecting value"],"pricing":"Proprietary reverse pricing varies widely by lender, product and draw type, so always compare against a HECM capped at $1,249,125. Explain that there is no FHA MIP, but rates and origination charges may be higher. Show net proceeds, total costs and projected balance growth over 5, 10 and 15 years. Fixed lump sums accrue on the full amount immediately, so draw only what's needed. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written side-by-side comparisons.","marketing":["Wealth managers","Luxury agents","Estate attorneys","Seminars","Content on HECM limits vs proprietary"],"checklist":["Counseling","ID","Appraisal(s)","Insurance","Taxes","Mortgage statements","Title","Disclosures","Comparison worksheet","HOA docs if condo"],"updated":"2026-11"},
"c_reverse_condo":{"matrix":[["HECM condo eligibility","FHA project approval or single-unit approval (verify HECM availability)"],["Proprietary","Non-FHA condos often eligible (lender-specific)"],["HOA review","Budget, reserves, litigation, owner-occupancy"],["Insurance","Master policy, HO-6"],["FL condo law","Milestone inspections and SIRS (SB 4-D) - verify impact on approvals"],["Age","62+ for HECM; proprietary may differ"],["2026 MCA","$1,249,125"],["Owner occupancy","Project-level ratios per HUD (verify)"]],"walkthrough":["Look up the project on HUD's FHA condo approval list and note the approval expiration date","If not approved, check whether the unit could qualify under single-unit approval rules for HECM (verify current availability and criteria)","If HECM is not possible, identify proprietary lenders that accept the project type","Refer the borrower to a HUD-approved counselor before application","Order HOA documents: budget, reserve study, insurance certificates, litigation disclosure, owner-occupancy and delinquency data","In Florida, request milestone inspection and SIRS status and any pending special assessments (verify)","Run principal-limit and proceeds comparisons for HECM vs proprietary","Complete financial assessment including HOA dues and assessments as property charges","Order appraisal; the appraiser may need project information","Underwrite project and borrower; resolve insurance or litigation conditions","Close with 3-day rescission","Explain ongoing obligation to pay HOA dues and assessments"],"incomeExample":{"title":"Illustrative property-charge check for a condo HECM","steps":["Social Security and pension income $4,200/mo","Property taxes $350/mo + HO-6 insurance $90/mo + HOA dues $520/mo = $960/mo property charges","Other debts $150/mo; utilities and maintenance estimated per HUD residual-income method (verify)","Recent special assessment $40,000 to be paid at closing from proceeds","Financial assessment shows residual income adequate; no LESA required (illustrative)"],"result":"Condo borrowers must budget HOA dues and assessments as property charges; paying a known assessment at closing can strengthen the financial assessment. Illustrative."},"scenarios":[{"t":"Single-unit approval path","who":"Mary, 70, retired nurse, Mission Valley San Diego","situation":"Mary's condo complex let its FHA approval lapse two years ago. She wants a HECM line of credit as a reserve for in-home care later. The HOA is well funded and has no litigation. Her unit is worth about $600,000.","structure":"HECM using single-unit approval if the project meets criteria (verify HECM availability)","numbers":"Illustrative principal limit ~ $270,000","why":"A HECM line of credit grows on the unused portion, which suits a long-term reserve. Single-unit approval avoids requiring the HOA to reapply. The healthy budget helps meet criteria.","alternatives":"A proprietary reverse mortgage if single-unit approval isn't available, though most lack LOC growth. Asking the HOA to renew project approval benefits all owners.","watch":"Owner-occupancy and delinquency thresholds must be met. Single-unit approval rules for HECM change, so verify before promising."},{"t":"Condo-hotel unit","who":"Bill, 74, retired casino manager, Las Vegas","situation":"Bill owns a unit in a condo-hotel with a rental program and lives there most of the year. HECM doesn't allow condo-hotels. He wants to eliminate a $90,000 mortgage. Few lenders finance condotels.","structure":"Proprietary reverse mortgage if a lender accepts the project, otherwise sale","numbers":"Value $400,000; payoff $90,000","why":"HECM is not available for this property type. A proprietary lender may accept it with conditions. Removing his payment helps his fixed income.","alternatives":"Sell and buy a traditional condo using HECM for Purchase. Refinance the mortgage into a lower payment.","watch":"Rental-program participation may conflict with principal-residence requirements. Lender appetite is limited."},{"t":"Florida SIRS special assessment","who":"Joan, 76, retired teacher, Clearwater FL","situation":"Joan's building completed its structural integrity reserve study and levied a $40,000 special assessment. She lives on Social Security and a small pension. She doesn't want to sell. Her condo is worth about $350,000.","structure":"Reverse mortgage paying the assessment at closing if the project is eligible","numbers":"See income example","why":"Paying the assessment avoids a lien or forced sale. Reverse proceeds don't require monthly payments. Her financial assessment improves once the assessment is cleared.","alternatives":"An HOA payment plan if offered. Selling and moving to a building without large assessments.","watch":"More assessments may follow; budget for them. Project eligibility depends on reserves and inspections."},{"t":"Chicago high-rise with FHA approval","who":"Ray, 68, retired transit supervisor, Chicago","situation":"Ray's high-rise is FHA-approved through next year. He has a $90,000 mortgage and wants to eliminate it. His pension covers his other expenses. The unit is worth $500,000.","structure":"HECM paying off the mortgage","numbers":"Illustrative principal limit ~ $210,000; payoff $90,000","why":"FHA approval allows a HECM. Paying off the mortgage removes his largest bill. Remaining principal limit becomes a line of credit.","alternatives":"Proprietary reverse if approval lapses. A HELOC if he prefers making payments.","watch":"The approval expiration date must be after the case number assignment."},{"t":"Phoenix 55+ condo with rising dues","who":"Barb, 72, retired bookkeeper, Phoenix","situation":"Barb lives in a 55+ condo community. HOA dues rose 20% in two years. She owns her unit free and clear. She wants monthly income to cover rising costs.","structure":"HECM tenure payments if the project is FHA-approved","numbers":"Value $300,000","why":"Tenure payments provide steady monthly income. No mortgage payment is required. It helps absorb higher dues.","alternatives":"HECM line of credit. Selling and renting.","watch":"Further dues increases reduce residual income in the financial assessment. Confirm the project's FHA approval is current."}],"qa":[{"q":"Does my condo need FHA approval for a HECM?","a":"A HECM requires the project to be FHA-approved or the unit to qualify under a single-unit approval where HUD allows it (verify current HECM rules). We check status before ordering anything."},{"q":"What if my building isn't eligible?","a":"A proprietary reverse mortgage may accept non-FHA-approved condos. Each lender reviews the project under its own criteria."},{"q":"Do I keep paying HOA dues?","a":"Yes. HOA dues are a property charge, and failing to pay them can cause default on the reverse mortgage."},{"q":"How do special assessments affect me?","a":"They're property charges and are reviewed in the financial assessment. Large known assessments can often be paid off at closing from loan proceeds."},{"q":"Can I rent out my condo?","a":"No. The home must remain your principal residence, and you certify occupancy each year."},{"q":"Why does a condo reverse mortgage take longer?","a":"Project documents, budgets, insurance and possibly approvals must be reviewed. Plan a few extra weeks."},{"q":"How do Florida's condo safety laws matter?","a":"Milestone inspections and structural integrity reserve studies can lead to large assessments and affect project eligibility (verify). We ask for that information early."},{"q":"What happens to my heirs?","a":"Same as any HECM: they can sell, refinance or pay the lesser of the balance or 95% of appraised value. They never owe more than the home is worth."}],"aeQuestions":["Do you process HECM single-unit approvals, and what are the project criteria?","Which proprietary products accept non-FHA condos?","Full list of HOA documents required?","Litigation and special-assessment tolerance?","Investor concentration and owner-occupancy limits?","Florida SIRS/milestone inspection requirements?","Condotel eligibility?","Turn times including project review?","Broker comp plan (no term-based comp)?"],"redFlags":["HOA litigation","Low reserves","Special assessments","Investor concentration","Insurance gaps","Borrower confusion"],"pricing":"Condo reverse files often decide between a HECM (if the project or unit qualifies) and a proprietary product. Compare principal limits, MIP vs. no-MIP, and total costs. Factor HOA dues and potential assessments into the borrower's long-term budget. Disclose all fees in writing. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)).","marketing":["HOA managers","Senior communities","Agents","Seminars","Content on FL condo laws"],"checklist":["FHA approval check","HOA questionnaire","Budget","Insurance","Counseling","ID","Appraisal","Taxes","Title","Disclosures"],"updated":"2026-11"},
"d_visa_npr":{"matrix":[["FHA","Non-permanent residents ineligible for case numbers assigned on/after May 25, 2025 (HUD ML 2025-09); applies to HECM too"],["Fannie Mae conventional","Lawfully present non-permanent residents eligible on same terms as citizens with lender-documented status (verify B2-2-02)"],["Freddie Mac conventional","Non-permanent residents eligible with lawful-residency evidence and valid SSN (verify 5103.2)"],["Visa/EAD validity overlay","Common lender overlays: unexpired status, sometimes 1-3 years remaining or renewal history (lender-specific)"],["Acceptable categories","Commonly H-1B, H-4 EAD, L-1, L-2, E-1/E-2, O-1, TN, TD with EAD (lender-specific)"],["SSN","Generally required for agency; ITIN borrowers use ITIN non-QM"],["Max LTV (conventional)","Same as citizens per agency; some lenders cap NPR at 90-95% (lender-specific)"],["Jumbo","Often 80% max LTV and 12+ months reserves for NPR (lender-specific)"],["Non-QM visa programs","Accept short validity and E-2 business income; often 75-85% LTV (lender-specific)"],["Foreign assets","Allowed when converted to USD and sourced with translations"],["Occupancy","Primary residence most flexible; second homes/investment lender-specific"],["Florida purchases","SB 264 restrictions for domiciliaries of designated countries; attorney review (verify)"]],"walkthrough":["Ask the same status question of every applicant: citizen, permanent resident, or other lawful status (uniform intake)","Collect status documents: passport, visa, I-94, I-797, EAD as applicable","Confirm FHA is not an option for NPR case numbers after 5/25/2025 and explain alternatives neutrally","Run conventional DU/LPA as the first option if documents and overlays fit","Check the wholesale lender's NPR overlay (remaining validity, renewal history, employer letter)","Document 2-year employment history, including prior foreign employment if lender allows","Source down payment: foreign wires, currency conversion, gift letters","If conventional overlays fail, price non-QM visa-holder and jumbo NPR options","For E-2 investors, decide between tax-return income and bank-statement non-QM","Florida purchases: confirm SB 264 review with buyer's attorney","Monitor visa/EAD expiration dates through closing","Close; calendar refinance review when green card is approved"],"incomeExample":{"title":"Illustrative H-1B + H-4 EAD household","steps":["H-1B base salary $165,000/yr = $13,750/mo","Annual bonus averaged over 2 years: $12,000/yr = $1,000/mo","Spouse H-4 EAD income, 14 months at current job, prior 3 years in same field abroad: $60,000/yr = $5,000/mo (lender must accept history - verify)","Total qualifying income = $19,750/mo","Proposed PITI $7,200 + debts $900 = $8,100","DTI = $8,100 / $19,750 = 41%"],"result":"Household fits a typical conventional DTI if the lender accepts the spouse's EAD history; without it, DTI rises to about 55% and non-QM or a lower price may be needed. Illustrative."},"scenarios":[{"t":"H-1B engineer, conventional high-balance","who":"Arjun, 32, software engineer, Sorrento Valley San Diego","situation":"Arjun has been on an H-1B for five years and his employer's I-140 is approved. He tried FHA in 2025 and was told non-permanent residents no longer qualify. He has $95,000 saved and earns $185,000. He wants a $950,000 townhome.","structure":"Conventional high-balance with 10% down, through a lender whose NPR overlay accepts his visa validity","numbers":"Loan $855,000 (within San Diego high-balance limit - verify)","why":"Fannie Mae and Freddie Mac allow lawfully present non-permanent residents on the same terms as citizens (verify). His approved I-140 and long employment support income continuance. Conventional pricing beats non-QM alternatives.","alternatives":"Prime jumbo with 20% down if he prefers a larger home, though NPR jumbo programs often require more reserves. A non-QM visa program if his visa expires within a lender's overlay window.","watch":"If his H-1B expires within 6 months, many lenders require the extension receipt. Keep a copy of every I-797 in the file."},{"t":"L-1 transferee buying quickly","who":"Mei, 41, operations director, Irvine","situation":"Mei transferred from her company's Singapore office 8 months ago on an L-1A. Her prior 6 years were with the same employer abroad. She plans to put 20% down on a $1.2M home using funds from Singapore. She has U.S. credit from a corporate card and a new auto loan.","structure":"Conventional or high-balance with foreign employment with the same employer counted toward history (lender-specific)","numbers":"Down $240,000 wired from Singapore","why":"Continuous employment with the same multinational satisfies the two-year history at many lenders. A large down payment lowers risk and pricing. Documented foreign funds are acceptable when sourced.","alternatives":"A non-QM foreign-income program if her lender won't count overseas employment. Renting for a year to build U.S. credit and history.","watch":"Foreign account statements need translation where required and must show the money leaving and arriving. Currency conversion amounts must match."},{"t":"E-2 treaty investor","who":"Luca, 46, franchise restaurant owner, Scottsdale","situation":"Luca came on an E-2 visa after investing in a franchise 18 months ago. His tax return shows low profit after startup costs. Monthly business deposits average $65,000. He wants a $650,000 home with 25% down.","structure":"Non-QM bank-statement program for visa holders","numbers":"Down $162,500","why":"Bank statements capture his business cash flow. Visa-holder non-QM programs accept E-2 status. Waiting for agency eligibility could take another year or more.","alternatives":"Wait for his second tax return and apply conventionally if the business shows profit. Rent until the business stabilizes.","watch":"E-2 status depends on the business's viability. Non-QM pricing and any prepayment penalty must be disclosed."},{"t":"TN professional with renewal history","who":"Sarah, 35, Canadian nurse on TN status, Henderson NV","situation":"Sarah has worked at a Las Vegas hospital for 6 years under TN status, renewed twice. Her current TN expires in 20 months. She earns $105,000. She wants a $480,000 home with 5% down.","structure":"Conventional with a lender that accepts TN renewal history","numbers":"Loan $456,000","why":"Her renewal record shows continuity. Conventional allows 5% down for eligible NPR borrowers. Her nursing income is stable.","alternatives":"Non-QM visa program if overlays require more remaining validity. Wait for green card if pending.","watch":"Lender overlays on remaining validity vary. TN status is tied to her employer."},{"t":"O-1 researcher with short validity","who":"Dmitri, 38, biotech scientist, La Jolla","situation":"Dmitri's O-1 expires in 9 months and his employer has filed for an extension. He earns $210,000. He wants a $1.1M condo. Several lenders declined due to remaining validity.","structure":"Lender that accepts pending extension receipts, or non-QM visa-holder loan","numbers":"20-25% down","why":"Some lenders accept the receipt notice as evidence. Non-QM provides a backup path. His income is strong.","alternatives":"Rent until extension is approved. Pursue green card first.","watch":"Overlays on remaining validity vary widely; approval can't be promised. Extension receipt must be current at closing."},{"t":"Florida purchase and SB 264 review","who":"Wei, 34, H-1B data scientist, Tampa","situation":"Wei is domiciled in a country designated under Florida's SB 264. The law restricts property purchases with exceptions for some lawful residents (verify). He wants a $450,000 condo.","structure":"Attorney review before contract; conventional financing","numbers":"Price $450,000","why":"State law requires the review. Exceptions may apply. Financing follows normal rules.","alternatives":"Choose a property that meets SB 264 exception criteria per counsel. Buy in another state where no similar restriction applies.","watch":"Apply the rule only as Florida law requires, never based on name or language. Counsel's written review belongs in the file."}],"qa":[{"q":"Can I still get an FHA loan on an H-1B?","a":"Not for new FHA case numbers assigned on or after May 25, 2025. HUD Mortgagee Letter 2025-09 limits FHA to U.S. citizens and lawful permanent residents. Conventional and non-QM options remain available."},{"q":"Can I get a conventional loan with a work visa?","a":"Often yes. Fannie Mae and Freddie Mac allow lawfully present non-permanent residents on the same terms as citizens (verify). Individual lenders may add requirements about remaining visa validity."},{"q":"How much down payment do I need?","a":"Conventional can be as little as 3-5% when you're eligible. Jumbo and non-QM visa-holder programs commonly require 15-25%."},{"q":"What if my visa expires soon?","a":"Some lenders accept a pending extension receipt or a history of renewals, while others require more remaining validity. We match you to a lender whose policy fits your documents."},{"q":"Can my spouse's income count?","a":"Yes, if your spouse has work authorization, such as an H-4 EAD or L-2, and enough employment history. Without work authorization, their income can't be used."},{"q":"Can I use money from overseas?","a":"Yes, if it's transferred to a U.S. account, converted to dollars and documented with statements and wire records. Translations may be required."},{"q":"Do I need U.S. credit?","a":"Agency loans need a U.S. credit report. Some non-QM lenders accept foreign credit reports or alternative credit."},{"q":"Will my green card application help?","a":"An approved I-140 or pending I-485 can help show your income is likely to continue. Once your green card is approved, FHA and more down payment assistance programs open up."},{"q":"Can I buy in Florida?","a":"Usually yes, but Florida's SB 264 restricts purchases by people domiciled in certain countries, with exceptions (verify current law). A Florida real estate attorney should review before you sign a contract."},{"q":"Is my immigration information shared with anyone?","a":"Only as needed to underwrite and close your loan, under federal privacy laws. We apply the same documentation rules to every applicant."}],"aeQuestions":["What is your NPR overlay on remaining visa/EAD validity?","Do you accept pending extensions (I-797 receipt) or renewal history?","Which visa categories are on your eligible list (H-1B, L-1, E-2, O-1, TN, H-4 EAD)?","How do you document foreign employment history toward the 2-year requirement?","Max LTV for NPR on conforming, high-balance and jumbo?","Do you accept foreign credit reports in non-QM?","How do you handle E-2 business income?","Gift funds from relatives abroad: documentation?","Do you offer FHA Streamline for existing NPR FHA borrowers (verify)?","Broker comp plan details (no term-based comp)?"],"redFlags":["Status documents expire before projected closing","Name inconsistencies across passport, SSN and credit","Large foreign deposits without documentation","H-4 spouse income counted without an EAD","Borrower asks to misstate status or occupancy","Intake asks status questions of some applicants and not others (fair-lending risk)","Florida purchase without SB 264 review where it may apply"],"pricing":"Conventional pricing for eligible non-permanent residents follows the same loan-level price adjustments as for citizens; non-QM visa programs and NPR jumbo programs cost more and require more down. Present conventional first when the documents fit, then non-QM as a comparison with the cost difference explained. Factor foreign-asset timing into lock periods. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Show written side-by-side options and never imply that status changes the price beyond the program rules.","marketing":["Homebuyer seminars for tech and biotech employers' visa-holder employees (through HR benefits teams)","Content explaining the 2025 FHA change and what still works","Partnerships with immigration attorneys for education (no referral fees)","Multilingual materials reviewed for accuracy","Indian, Chinese, Filipino, Korean and Mexican professional associations in San Diego","Relocation agents and corporate housing providers"],"checklist":["Passport and visa stamp","I-94","I-797 approval notices","EAD card (front/back) if applicable","SSN verification","Paystubs and W-2s","Employer letter on continuance (lender-specific)","Bank and foreign account statements","Wire/currency conversion records","Gift letters (if any)","Credit report","Appraisal","Florida SB 264 attorney review (if FL)","Visa expiration monitoring note"],"updated":"2026-11"},
"d_green_card":{"matrix":[["FHA","LPR eligible on same terms as citizens; evidence of lawful permanent residency required; SSN card alone insufficient (ML 2025-09)"],["Conventional","LPR eligible with I-551 or acceptable evidence (verify Selling Guide)"],["VA","Eligibility follows veteran status; LPR veterans commonly eligible (verify)"],["USDA","LPRs are qualified aliens; standard USDA eligibility (verify)"],["Conditional 2-year card","Acceptable while valid; if expired, I-751/I-829 receipt notice extending status typically required (verify lender)"],["Expired 10-year card","Status continues but most lenders require I-90 receipt or new card (lender-specific)"],["Credit","Standard minimums; FHA allows non-traditional credit for no-score borrowers (verify)"],["Employment history","2 years; documented foreign employment may count (lender-specific)"],["DPA programs","Most state HFA programs accept LPRs (verify each)"],["Foreign assets","Sourced, converted and documented with translations"]],"walkthrough":["Ask every applicant the same residency question (citizen, permanent resident, other) and record the answer the same way for everyone","Review the green card front and back: category, 'resident since' date and expiration; note whether it is a conditional (2-year) card","If the card is conditional and expired, obtain the I-751 or I-829 receipt notice and confirm its extension period covers closing (verify lender policy)","If a 10-year card is expired, obtain the I-90 receipt or new card per lender overlay","Confirm the SSN matches the name on the card and credit report; resolve hyphenation or transliteration differences early","Pull credit; if the file is thin, gather 12 months of rent, utility, phone and insurance payments for non-traditional credit (FHA and some lenders - verify)","Document two years of employment, including foreign employment with employer letters and certified translations if the lender accepts it","Source down payment, including foreign accounts, wires and currency conversion, with translated statements","Compare FHA (now available to LPRs), conventional, VA if a veteran, USDA if rural, and state DPA eligibility","Issue pre-approval and brief the agent on any document timing","Recheck card or receipt validity a week before closing and close"],"incomeExample":{"title":"Illustrative recent LPR with foreign history","steps":["Current U.S. job 10 months: $72,000/yr = $6,000/mo","Prior 3 years same profession abroad, documented and translated","Lender accepts combined history (verify)","PITI on $480,000 FHA purchase ~ $3,700 (illustrative)","Debts $250","DTI = $3,950 / $6,000 = 65.8% (too high); lower price or add co-borrower"],"result":"Recalculate at a $380,000 price with ~ $2,950 PITI: DTI = $3,200 / $6,000 = 53% - may fit FHA AUS (verify). Illustrative."},"scenarios":[{"t":"Green card reopens FHA and DPA","who":"Priya, 30, pharmacist, Chula Vista","situation":"Priya was on an H-1B in early 2025, when FHA stopped accepting non-permanent residents. Her green card was approved in August 2026. She has $18,000 saved and earns $138,000. She wants a $620,000 townhome.","structure":"FHA purchase, with CalHFA assistance if her income fits county limits (verify)","numbers":"3.5% down $21,700; DPA could cover most of it (illustrative)","why":"As a lawful permanent resident she is eligible for FHA on the same terms as a citizen. FHA's MIP and credit pricing may beat conventional at her 690 score. Pairing with DPA preserves her savings for reserves.","alternatives":"Conventional 5% down avoids lifetime FHA MIP and may be cheaper if her score rises above 720. HomeReady could fit if her income is under the area limit (verify), offering reduced MI.","watch":"CalHFA income limits in San Diego County may exclude her salary (verify). The green card must be in hand, not just an approval notice, for most lenders."},{"t":"Expired conditional card with I-751 receipt","who":"Carlos, 29, electrician, Riverside","situation":"Carlos received a 2-year conditional card through marriage. It expired last month, but he filed the I-751 on time. The receipt notice extends his status for a set period (verify current USCIS extension length). He and his wife want a $540,000 home.","structure":"Conventional 5% down using the I-751 receipt as evidence of continuing status","numbers":"Loan $513,000; combined income $132,000","why":"The receipt notice extends his permanent-resident status while the petition is pending. Lenders that accept it treat him like any LPR. Both spouses' incomes qualify comfortably.","alternatives":"FHA if a lender's conventional overlay rejects receipts. Waiting for the 10-year card removes all questions but may take a year or more.","watch":"The receipt's extension date must cover closing. A name mismatch between the card and his Social Security record must be fixed first."},{"t":"New arrival without a U.S. credit score","who":"Fatima, 37, staff accountant, Chicago","situation":"Fatima immigrated 14 months ago with a green card and has worked at a Chicago firm for 11 months. Before that she was an accountant for 6 years abroad. She has no U.S. credit score but has paid rent, phone and car insurance on time.","structure":"FHA using non-traditional credit and documented foreign employment (lender-specific)","numbers":"Price $300,000; 3.5% down","why":"FHA allows non-traditional credit when there is no score. Her foreign employment in the same field supports her two-year history if the lender accepts it. Her income comfortably supports a modest condo.","alternatives":"Build credit for 12 months with a secured card and buy conventionally later. An IHDA program could help with down payment if she qualifies (verify).","watch":"Many lenders overlay FHA with minimum scores, so few will do no-score files. Foreign employment letters need certified translation."},{"t":"LPR Army veteran uses VA","who":"Juan, 34, Army veteran (LPR), North Las Vegas","situation":"Juan served four years in the Army as a permanent resident and was honorably discharged. He now works as a logistics coordinator earning $68,000. He has little savings and wants a $450,000 home.","structure":"VA purchase with $0 down","numbers":"Loan $450,000 plus funding fee (unless exempt)","why":"VA eligibility is based on military service, and LPR veterans are commonly eligible (verify). VA requires no down payment and has no monthly MI. Residual income analysis may let him qualify where DTI looks high.","alternatives":"FHA with Nevada DPA if VA residual income falls short. Conventional is less attractive with little down.","watch":"Get the Certificate of Eligibility early. If he has a disability rating, the funding fee may be waived."},{"t":"Gift from parents abroad","who":"Minh, 41, nail salon owner, Orlando","situation":"Minh has been an LPR for 9 years and owns her salon. Her parents in Vietnam are gifting $60,000 toward a $380,000 home. The money will arrive by international wire. Her self-employment income is documented on 2 years of returns.","structure":"Conventional with documented foreign gift","numbers":"Gift $60,000 + her funds $16,000","why":"Agency rules allow gifts from relatives, including those living abroad. A gift letter, the donor's statement and the wire trail document the funds. Her 2-year business history supports income.","alternatives":"FHA with smaller down payment if her credit is weaker. A non-QM bank-statement loan if her tax returns understate income.","watch":"Currency conversion and translated statements must match. Wires in pieces need each one sourced."}],"qa":[{"q":"Is a green card holder treated the same as a U.S. citizen for a mortgage?","a":"Yes. Lawful permanent residents are eligible for FHA, conventional, VA (if a veteran) and USDA loans on the same terms as citizens. You need to show proof of permanent residency."},{"q":"My conditional green card expired. Can I still buy?","a":"Usually, if you filed the I-751 (or I-829) and have the receipt notice extending your status. Lenders check that the extension period covers closing, and some have additional requirements."},{"q":"Is my Social Security card enough proof?","a":"No. HUD's 2025 guidance specifically says a Social Security card alone doesn't prove immigration status. Bring your green card or receipt notice."},{"q":"I don't have a U.S. credit score yet. Can I qualify?","a":"FHA and some lenders accept non-traditional credit such as rent, utilities and insurance payments. Not every lender offers it, so we match you to one that does."},{"q":"Does my work experience from another country count?","a":"Some lenders accept documented foreign employment toward the two-year history. You'll need employer letters and certified translations."},{"q":"Can family overseas help with my down payment?","a":"Yes, relatives can give gifts from abroad. We'll need a gift letter, the donor's account statement and the wire records."},{"q":"Can I use down payment assistance programs?","a":"Most state programs accept permanent residents. We'll confirm each program's current rules and income limits."},{"q":"My 10-year card expired. What do I need?","a":"Your permanent-resident status doesn't expire, but most lenders want the I-90 renewal receipt or the new card. Start the renewal early if you plan to buy."}],"aeQuestions":["Do you accept I-751/I-829 receipt notices, and how long must they remain valid?","Policy on expired 10-year cards with I-90 receipt?","Non-traditional credit acceptance for FHA and conventional?","How do you document foreign employment?","Foreign gift documentation requirements?","Translation requirements?","DPA programs you offer?","Turn times?","Broker comp plan (no term-based comp)?"],"redFlags":["Status receipt notice expires before the projected closing date","Only a Social Security card offered as proof of status","Names differ across card, passport, SSN and credit report without explanation","Foreign deposits without statements, translations or wire records","Undisclosed debts in the home country that affect assets","Occupancy plans inconsistent (e.g., spending most of the year abroad)","Intake asks residency questions of some applicants but not others","Third parties holding the borrower's documents or speaking for them without consent"],"pricing":"LPRs receive the same pricing as citizens for the same risk profile. Compare FHA with DPA, conventional and VA if applicable. Explain MI differences. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons.","marketing":["Citizenship class providers (education events)","Immigrant community centers","Employers who sponsored green cards","Past NPR clients now LPR (FHA reopens)","Multilingual first-time buyer seminars"],"checklist":["Green card front/back","I-751/I-829/I-90 receipt if applicable","SSN","Paystubs/W-2s","Foreign employment verification and translations","Bank statements","Gift letters and wire trail","Credit or non-traditional credit","Purchase contract","Appraisal","DPA documents"],"updated":"2026-11"},
"d_asylum_tps":{"matrix":[["FHA","Non-permanent residents ineligible for case numbers on/after 5/25/2025 (ML 2025-09); asylees/refugees without LPR status generally fall outside FHA eligibility (verify)"],["Conventional","May be eligible as lawfully present non-permanent residents with acceptable documentation (EAD, I-94, grant notice) - verify agency guidance and lender overlays"],["USDA","Refugees and asylees are generally 'qualified aliens'; verify current USDA residency verification and TPS treatment"],["TPS designations","Country-by-country; several designations were terminated, shortened or litigated in 2025-2026 - verify Federal Register and court orders for each file"],["EAD auto-extensions","Federal Register notices or receipt rules can extend EAD validity; lender acceptance varies (lender-specific)"],["Refugee/asylee to LPR","Both may apply to adjust status after 1 year (verify); LPR status reopens FHA and broader DPA"],["Non-QM / ITIN","Many lenders accept EAD holders or ITIN borrowers with 10-25% down (lender-specific)"],["SSN","Generally required for agency; ITIN programs for those without SSN"],["Down payment","Program-specific; DPA eligibility varies by HFA (verify)"],["Income continuance","Underwriter may weigh status validity when assessing continuance (lender-specific)"]],"walkthrough":["Use one uniform intake question about citizenship/residency for every applicant","Collect the documents the borrower has: EAD, I-94, asylum grant/refugee admission, SSN, any I-485 receipt","Explain neutrally which programs accept those documents today (FHA does not for non-LPRs)","For TPS holders, confirm the current designation status and EAD validity for their country (verify)","Submit to conventional lenders whose overlays accept the documentation","Price non-QM/ITIN alternatives as a comparison, with costs explained","If LPR adjustment is pending or close, show the trade-off of waiting (FHA/DPA access) vs buying now","Refer immigration questions to the borrower's attorney or accredited representative","Issue pre-approval with conditions tied to status validity","Monitor document expiration dates through closing","Protect documents under GLBA safeguards; share only as needed to underwrite","Close and calendar a refinance review if LPR status later improves options"],"incomeExample":{"title":"Illustrative asylee household","steps":["Borrower, asylee, warehouse supervisor 4 years: $58,000/yr = $4,833/mo","Spouse, asylee with EAD, caregiver 2 years: $36,000/yr = $3,000/mo","Total income $7,833/mo","Proposed PITI on $420,000 conventional purchase with 10% down ~ $3,050 (illustrative)","Debts $350","DTI = $3,400 / $7,833 = 43%"],"result":"Ratios fit typical conventional limits if a lender accepts the status documents; otherwise a non-QM option with larger down payment may be compared. Illustrative."},"scenarios":[{"t":"Asylee with stable job","who":"Yonas, 36, certified nursing assistant, El Cajon","situation":"Yonas received asylum three years ago and works as a certified nursing assistant. His EAD is valid for 18 more months and his green card application is pending. He has $40,000 saved. He wants a $520,000 condo in El Cajon.","structure":"Conventional with a lender accepting asylee documentation; non-QM as backup","numbers":"Price $520,000; 5-10% down","why":"His asylum grant and EAD document lawful presence that some conventional lenders accept. Three years of steady employment support income continuance. Conventional pricing is far below non-QM if a lender's overlay fits.","alternatives":"Wait for his pending green card, which reopens FHA and CalHFA assistance and may lower cash needed. A non-QM program with 10-15% down if he wants to buy now and conventional overlays don't fit.","watch":"Lender overlays may require 12+ months remaining on the EAD at closing. Keep the green card application receipt in the file."},{"t":"Refugee close to adjustment","who":"Amina, 31, medical interpreter, Phoenix","situation":"Amina was admitted as a refugee 14 months ago and has filed for her green card. She works as a medical interpreter earning $54,000. She has $20,000 saved. She wants a $360,000 home in Phoenix.","structure":"Compare buying now with non-QM vs waiting for LPR to use FHA + Home Plus DPA","numbers":"Price $360,000; non-QM 15% down vs FHA 3.5% plus DPA after LPR","why":"Waiting for permanent residency may cut her required cash from about 15% to 3.5% with FHA plus Home Plus. Buying now would cost more through non-QM. Showing both paths lets her choose with full information.","alternatives":"Buy now with a non-QM program at higher cost and refinance after LPR approval. A conventional lender that accepts refugee documentation, if one fits her file.","watch":"Green card processing times are unpredictable; don't promise a date. Home Plus income caps and funding change over time (verify)."},{"t":"Long-tenured TPS holder","who":"Jose, 45, construction foreman, Las Vegas","situation":"Jose has held TPS for 15 years and works as a construction foreman. His EAD is currently valid, but his country's designation status recently changed (verify). He has $90,000 saved. He wants a $430,000 home.","structure":"Only proceed with lenders that accept the current documents; otherwise ITIN/non-QM or postpone","numbers":"Price $430,000; 15-20% down for non-QM","why":"His long work history and savings make him a strong borrower on paper. Status continuity drives whether lenders will proceed. Only lenders accepting his current documents should be approached.","alternatives":"An ITIN or non-QM program accepting EAD holders with 15-20% down. Continue renting and saving until his status situation is clearer.","watch":"Designation termination or litigation could change eligibility mid-process"},{"t":"Florida TPS family facing uncertainty","who":"Marie, 39, home health aide, Miami","situation":"Marie works as a home health aide in Miami under TPS. Her country's designation was affected by 2025-2026 actions (verify). She has been saving for a down payment. She wants to know if she can buy now.","structure":"Pause; refer to immigration counsel; revisit when status is clear","numbers":"N/A","why":"Committing a deposit while her status is uncertain could cost her money. Her immigration counsel is best placed to advise on status. A savings and credit plan keeps her ready.","alternatives":"Revisit once her attorney confirms her status. Build credit and savings in the meantime so she's ready to move quickly.","watch":"Never give immigration advice or predictions. Follow up when she or her attorney reports a status change."},{"t":"Chicago asylee buying a condo","who":"Dmytro, 33, IT support specialist, Chicago","situation":"Dmytro was granted asylum and works in IT support in Chicago. He has an EAD and SSN. He wants a $285,000 condo with 5% down.","structure":"Conventional with warrantable condo; non-QM if overlays fail","numbers":"Price $285,000; 5% down","why":"His asylum status and SSN support conventional eligibility at some lenders. The low price point keeps the payment manageable. Five percent down fits his savings.","alternatives":"Wait for permanent residency to access IHDA assistance (verify eligibility). A non-QM option if conventional overlays don't accept his EAD.","watch":"The condo must be warrantable for conventional financing. EAD validity must extend past closing per lender overlay."}],"qa":[{"q":"Can I get an FHA loan with asylum or refugee status?","a":"Under HUD's 2025 rule, FHA generally requires U.S. citizenship or permanent residency (verify). FHA is typically available once you have a green card."},{"q":"Can I get a conventional loan?","a":"Possibly. Some lenders accept asylee, refugee or TPS documentation under Fannie Mae and Freddie Mac rules, so we check which lenders accept your documents."},{"q":"How does TPS affect my application?","a":"It depends on your country's current designation and your EAD's validity. These change often, so we verify before and during the process."},{"q":"Should I wait for my green card?","a":"Sometimes waiting opens FHA and down payment assistance. We'll show both paths so you can choose."},{"q":"Will my immigration information be kept private?","a":"Yes. We use it only to underwrite and close your loan and protect it under federal privacy rules."},{"q":"Can you help with my immigration case?","a":"No. We're not immigration advisors, so please work with your attorney or an accredited representative."},{"q":"How much down payment will I need?","a":"Conventional may allow 3-10% if you're eligible. Non-QM and ITIN programs usually require 10-25%."},{"q":"What if I don't have a Social Security number?","a":"ITIN loan programs may be an option. They require larger down payments and cost more."},{"q":"What if my EAD is about to expire?","a":"Bring your renewal receipt or proof of an automatic extension. Lenders vary on what they accept."}],"aeQuestions":["Do you accept asylee and refugee EADs and I-94s for conventional loans?","What is your TPS policy given 2025-2026 designation changes?","Do you accept Federal Register EAD auto-extensions or I-765 receipts?","Minimum remaining validity on status documents?","Non-QM/ITIN programs: max LTV and documentation?","How do you assess income continuance for these borrowers?","Do your DPA partner programs accept non-LPR applicants?","Turn times?","Broker comp plan (no term-based comp)?"],"redFlags":["EAD expired with no valid extension evidence","TPS designation for the borrower's country currently terminated or enjoined (verify)","Borrower requests immigration advice or predictions","Intake asks more questions of some applicants than others","Unsourced cash or informal savings without paper trail","Third parties (notarios) controlling the borrower's documents"],"pricing":"Eligible conventional borrowers receive the same loan-level pricing as anyone else with the same risk profile. Non-QM and ITIN programs cost more and require more down; explain why and show conventional first when documents fit. Show the cost of buying now versus waiting for LPR status where that's realistic. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons and avoid any pricing that varies by national origin.","marketing":["Education partnerships with refugee resettlement agencies","Legal aid and DOJ-accredited representative clinics (education, no referral fees)","Multilingual first-time buyer workshops with qualified interpreters","Faith-based community center financial literacy nights","Credit-building and savings-plan content in multiple languages"],"checklist":["EAD front/back","I-94 (refugee/asylee)","Asylum grant or refugee admission documentation","Federal Register/receipt evidence for auto-extensions","SSN verification (or ITIN for ITIN programs)","Paystubs and W-2s","Tax returns","Bank statements","Credit report","Purchase contract","Appraisal","Status-validity monitoring note"],"updated":"2026-11"},
"d_crypto":{"matrix":[["Agency down payment/closing funds","Crypto must be sold, converted to USD and deposited in a U.S. financial institution before it counts; full trail required (verify current Selling Guides)"],["FHFA directive","June 25, 2025 order directed Fannie/Freddie to prepare proposals to count crypto held on U.S.-regulated centralized exchanges as reserves without conversion; final implementation - verify"],["Volatility treatment","FHFA directed haircuts and caps on crypto share of reserves (details - verify)"],["Seasoning","Typically 2 months statements for assets; converted funds sourced back to exchange (verify)"],["Large deposits","Must be sourced with exchange withdrawal records matching bank deposits"],["Non-QM reserves","Some lenders count crypto at 50-70% of value without liquidation (lender-specific)"],["Non-QM asset depletion","Crypto may count after conversion or at haircut (lender-specific)"],["Crypto-collateralized loans","A small number of structures (e.g., Bitcoin/USDC-pledged dual-loan) exist - verify product status and risks"],["Stocks/RSUs","Vested shares count; down payment from stocks requires proof of liquidation if value is needed"],["Self-custody wallets","Harder to document; move to regulated exchange with statements well before application"],["Tax","Capital gains on sale; CPA input for large liquidations"],["Foreign exchanges","Generally unacceptable for agency sourcing (lender-specific)"]],"walkthrough":["Inventory digital assets: exchanges, wallets, stablecoins, amounts, purchase history","Estimate how much is needed for down payment, closing costs and reserves","Advise documentation only (no investment or tax advice); suggest CPA consult on gains","Move self-custody assets to a U.S.-regulated exchange early to create statements","Obtain 2 months of exchange statements showing ownership","Plan the sale and withdrawal timing; consider price-volatility cushions","Sell and transfer to the U.S. bank account; save trade confirmations and withdrawal records","Match exchange withdrawal to bank deposit for underwriting","If buyer prefers not to liquidate, compare non-QM crypto-reserve programs","Update statements if required close to closing","Close; keep a full asset trail in the file"],"incomeExample":{"title":"Illustrative crypto asset sourcing and non-QM reserves","steps":["BTC holdings value $260,000 on a U.S. exchange; ETH $40,000 in self-custody","Need: down payment $180,000 + closing costs $25,000 = $205,000","Sell $215,000 of BTC (cushion for price moves); withdraw to U.S. bank; trail documented","Remaining BTC $45,000; non-QM lender counts 60% for reserves = $27,000 (lender-specific)","Required reserves: 6 months PITI x $6,000 = $36,000","Add $10,000 checking + 401(k) vested $50,000 x 60% = $30,000 -> total reserves $67,000"],"result":"Down payment fully sourced through conversion; reserves satisfied with crypto haircut plus traditional assets. Illustrative only."},"scenarios":[{"t":"Early Bitcoin holder buys a first home","who":"Kyle, 34, software developer, Carlsbad","situation":"Kyle holds about $400,000 in Bitcoin on a U.S. exchange and has $30,000 in checking. He wants a $1.0M home with 20% down. His W-2 income easily qualifies. He worries about selling during a dip.","structure":"Conventional purchase; sell needed Bitcoin 60+ days before closing and deposit to his U.S. bank","numbers":"Down $200,000 + costs $25,000 from conversion","why":"Agency pricing applies once funds are converted and documented. Selling early removes price risk from the closing. His remaining crypto stays invested.","alternatives":"A non-QM program counting unconverted crypto for reserves, if he wants to sell less. A smaller down payment with PMI to keep more Bitcoin.","watch":"Capital gains tax on the sale should be planned with his CPA. Exchange statements must show his name and account."},{"t":"Self-custody wallet holder","who":"Nadia, 29, graphic designer, Las Vegas","situation":"Nadia holds $60,000 in Ethereum in a hardware wallet. She needs it for her down payment on a $400,000 condo. She has no exchange statements. Her W-2 income qualifies.","structure":"Transfer to a U.S. exchange, accumulate statements, convert and deposit","numbers":"Need $60,000","why":"Moving to an exchange creates documentation. Converting provides agency-acceptable funds. The trail shows ownership.","alternatives":"A family gift for part of the down payment. FHA with smaller down payment.","watch":"Wallet transfer history should show her ownership. Allow time for statements."},{"t":"Founder paid in tokens","who":"Ethan, 41, startup founder, Irvine","situation":"Ethan's income is partly in tokens and his salary is low. He has $2M in assets after conversion. He wants a $1.5M home.","structure":"Non-QM asset depletion with converted funds","numbers":"Assets $2M","why":"Asset depletion qualifies on wealth. Converted funds are documented. Income is otherwise complex.","alternatives":"Bank statement program. Larger down payment.","watch":"Token liquidity may be limited, and large sales can move prices. Converted funds need a complete trail for asset-depletion calculations."},{"t":"Retiree with crypto reserves","who":"Paul, 63, Scottsdale","situation":"Paul retired at 63 with crypto making up about 30% of his $1.5M in assets. He wants a $700,000 home in Scottsdale with 30% down. His income is pension and IRA distributions. He prefers not to sell more crypto than necessary.","structure":"Conventional with converted funds; non-QM reserve haircut on the rest","numbers":"Price $700,000","why":"Combined assets qualify. Conversion for closing. Reserves met.","alternatives":"Sell enough crypto to meet all reserve requirements in dollars, avoiding non-QM costs. Use retirement-account reserves instead of crypto for the reserve requirement.","watch":"Crypto reserves at a lender haircut can fall below minimums if prices drop before closing. We provide no investment advice on his concentration."},{"t":"Offshore exchange holdings","who":"Leo, 37, Miami","situation":"Leo holds about $120,000 in crypto on an offshore exchange. He needs those funds for closing on a $600,000 Miami condo. Agency lenders generally won't accept sourcing from offshore exchanges. He has six months before he wants to buy.","structure":"Move to U.S.-regulated exchange before use","numbers":"$120,000","why":"Agency sourcing needs acceptable institutions. AML review. Clean trail.","alternatives":"Delay the purchase until funds have a clean U.S. exchange history. Use a family gift for part of the down payment while the transfer is documented.","watch":"Transfers from offshore platforms can trigger AML reviews. Every withdrawal and deposit needs matching statements."}],"qa":[{"q":"Can I use cryptocurrency for my down payment?","a":"Yes, once it's sold, converted to dollars and deposited into a U.S. bank account. Underwriters need a documented trail from the exchange to your bank."},{"q":"Do Fannie Mae and Freddie Mac count crypto now?","a":"FHFA directed them in June 2025 to prepare proposals to count crypto held on U.S.-regulated exchanges as reserves. Final guidance must be verified; until then, converting to dollars is the safe path."},{"q":"Do I have to sell all my crypto?","a":"No, only what you need for closing. Some non-QM lenders count remaining crypto toward reserves at a discount."},{"q":"When should I sell?","a":"Early enough that funds are deposited and documented before underwriting, often 30-60 days before closing. Ask your CPA about the tax impact first."},{"q":"My crypto is in a hardware wallet. Is that a problem?","a":"It's harder to document ownership and history. Moving it to a regulated U.S. exchange early creates statements lenders can use."},{"q":"Will price changes affect my approval?","a":"They can if reserves are counted at market value and statements are updated. Convert what you need early and keep a cushion."},{"q":"Can I get a loan secured by my Bitcoin instead?","a":"A few specialized crypto-collateralized products exist. They have different risks, such as requirements to add collateral if prices fall, so review the terms carefully (verify)."},{"q":"Do stablecoins count?","a":"They're usually treated like other crypto: convert to dollars and document the trail (verify lender)."},{"q":"Do I need to report the sale on my taxes?","a":"Selling crypto is usually a taxable event. Consult your CPA; we don't give tax advice."}],"aeQuestions":["What is your current policy for converted crypto funds and required trail?","Have you implemented any FHFA-directed crypto reserve guidance? Haircuts and caps?","Do your non-QM programs count unconverted crypto for reserves? At what percentage?","Which exchanges are acceptable?","Asset depletion with crypto: eligible and formula?","Seasoning requirements for converted funds?","Do you offer crypto-collateralized products?","Documentation for self-custody transfers?","Broker comp plan (no term-based comp)?"],"redFlags":["Funds from offshore or unregulated exchanges","Peer-to-peer transfers without records","Multiple small deposits suggesting structuring","Third-party wallets not owned by borrower","Sudden large conversions with no history","Borrower asks to time sale to hide gains or debts"],"pricing":"Agency pricing applies when converted funds are documented. Non-QM crypto-reserve programs cost more; compare whether liquidating more crypto lowers the total cost of the loan. Don't give investment or tax advice; refer to CPA or advisor. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons including cash-to-close scenarios.","marketing":["Educational content: 'How to buy a home with crypto'","Crypto-literate CPA partnerships (education)","Tech and fintech employer seminars","Local crypto and founder meetups","Webinars explaining the 2025 FHFA directive and current status"],"checklist":["Exchange statements (2 months)","Trade confirmations for sales","Withdrawal records","Bank statements showing deposits","Wallet transfer history (if self-custody)","Brokerage/RSU statements","CPA note on tax impact (optional)","Reserve calculation worksheet","Large deposit letters","Gift letters if applicable","Credit report","Appraisal"],"updated":"2026-11"},
"d_k1":{"matrix":[["Ownership under 25%","Generally K-1 income with distribution history or business liquidity; business returns not required (verify Fannie B3-3.4 / Freddie 5304.1)"],["Ownership 25%+","Treated as self-employed: personal and business returns, cash-flow analysis (Fannie Form 1084/Freddie Form 91)"],["Returns required","Typically 2 years; 1 year possible with AUS approval and 5-year business history (verify)"],["Distribution/liquidity test","K-1 ordinary income usable if consistent distributions or adequate business liquidity (quick/current ratio) (verify)"],["Guaranteed payments","Partnership guaranteed payments count (often averaged)"],["W-2 from own S-corp","Counts; add K-1 share of income/loss per analysis"],["Add-backs","Depreciation, depletion, amortization, casualty losses; subtract notes payable <1 year and non-deductible meals (verify)"],["Losses","K-1 losses must be deducted from qualifying income"],["Declining income","Requires analysis; may use lower year"],["FHA","Business returns required for 25%+; 2-year history (verify)"],["Jumbo","Often 2 years returns and YTD P&L; stricter liquidity reviews (lender-specific)"],["Non-QM","Bank-statement or P&L programs when returns understate income"]],"walkthrough":["Collect every K-1 and note the entity type (1065 partnership or 1120-S S-corp) and the borrower's ownership percentage in each","Get personal returns (1-2 years per AUS) and, for any 25%+ entity, the business returns","Check distribution history on the K-1 or business bank statements; if distributions are below K-1 income, run the business liquidity test (verify)","Complete the lender's cash-flow worksheet (Fannie Form 1084 / Freddie Form 91), adding back depreciation, depletion and amortization","Subtract notes payable in under 1 year and non-deductible expenses from the business's cash flow","Deduct losses from any other K-1 entities, including passive real estate partnerships","Compare years; use the lower year if income declined without explanation","Request a YTD P&L and balance sheet if the lender or AUS requires","Decide between agency, jumbo or non-QM (bank statement / P&L) based on results","Verify business existence through CPA letter or state records","Underwrite; respond to liquidity and trend questions with CPA input","Close"],"incomeExample":{"title":"Illustrative S-corp owner (50%) cash-flow","steps":["W-2 wages from S-corp: 2024 $120,000; 2025 $130,000","K-1 ordinary income (50% share): 2024 $80,000; 2025 $90,000","Depreciation add-back (50% share): 2024 $10,000; 2025 $12,000","Notes payable <1 year (50% share): -$5,000 each year","Totals: 2024 $205,000; 2025 $227,000","Two-year average = $216,000/yr = $18,000/mo (business liquidity verified)"],"result":"Qualifying income ~ $18,000/mo using a two-year average; if 2025 was lower, the lower year may apply. Illustrative."},"scenarios":[{"t":"Anesthesiology group partner","who":"Dr. Hernandez, 44, anesthesiologist, San Diego","situation":"Dr. Hernandez is a 10% partner in an anesthesia group. He receives $350,000 in guaranteed payments plus a $90,000 K-1 share. Distributions match his K-1 income each year. He wants a $2.1M home with 20% down.","structure":"Jumbo using guaranteed payments and K-1 income (under 25% ownership)","numbers":"$440,000/yr qualifying","why":"Ownership under 25% means business returns usually aren't needed. Distribution history supports the K-1 income. Jumbo pricing rewards his strong profile.","alternatives":"Physician loan with lower down payment, though typically priced higher. Portfolio bank relationship loan.","watch":"Capital calls or a change in partnership share can affect income. Jumbo reserves are higher."},{"t":"HVAC company owner with S-corp","who":"Mark, 50, HVAC company owner, Temecula","situation":"Mark owns 100% of an S-corp that pays him $130,000 in W-2 wages plus K-1 income. His cash-flow analysis averages $216,000 over two years. The business has strong cash reserves. He wants a $950,000 home.","structure":"Conventional high-balance with Form 1084 analysis","numbers":"Average $216,000/yr","why":"Business returns and liquidity support his K-1 income. Agency pricing is lower than non-QM. His income comfortably supports the payment.","alternatives":"Bank-statement non-QM if a lender won't accept business liquidity. Jumbo if price rises.","watch":"Declining YTD revenue would reduce income. Business debt maturing within a year reduces cash flow."},{"t":"Real estate syndicator with paper losses","who":"Lisa, 42, real estate fund GP, Scottsdale","situation":"Lisa earns a management salary and K-1 income, but several passive partnerships show depreciation losses. Her taxable income is far below her actual cash flow. She wants a $1.2M home.","structure":"Conventional or jumbo with careful add-backs, or asset-depletion non-QM","numbers":"Losses reduce qualifying income","why":"Losses must be deducted, but add-backs may offset some. Asset depletion can capture wealth not shown on returns. Comparing paths finds the best fit.","alternatives":"Portfolio bank lending on assets. Bank-statement program.","watch":"Passive losses can offset income significantly. Add-backs require full partnership returns."},{"t":"Law firm equity partner","who":"James, 55, equity partner, Chicago","situation":"James is an equity partner in a large law firm with a $600,000 K-1. Distributions are consistent. He owns under 5%. He wants a $1.8M home.","structure":"Jumbo","numbers":"K-1 $600,000","why":"Small ownership means K-1 and personal returns suffice. Consistent distributions document income. Jumbo fits the size.","alternatives":"Portfolio bank. Asset-based lending.","watch":"Required capital contributions reduce liquidity. Jumbo reserves must be met after closing."},{"t":"Minority owner in a family business","who":"Ana, 38, operations director, Orlando","situation":"Ana owns 15% of her family's restaurant group and receives a W-2 plus K-1 income of $70,000. Distributions vary year to year. She wants a $480,000 home.","structure":"Conventional","numbers":"W-2 + K-1","why":"Under 25% ownership simplifies documentation. Distribution history is key. Agency pricing fits.","alternatives":"Qualify on W-2 alone. Non-QM.","watch":"Low distribution history may limit usable K-1 income. Business liquidity tests may be needed."}],"qa":[{"q":"Do you need my business tax returns?","a":"If you own 25% or more of the entity, usually yes, along with a cash-flow analysis. Under 25% ownership, lenders often need only your K-1s and personal returns."},{"q":"Why does my distribution history matter?","a":"Agency guidelines want proof you actually receive the K-1 income or that the business has enough liquidity to pay it. Without that, the income may not be usable."},{"q":"Can depreciation be added back?","a":"Yes. Depreciation, depletion and amortization are non-cash expenses that are usually added back to cash flow."},{"q":"What if one year was lower than the other?","a":"Underwriters analyze trends and often use the lower year. A CPA letter explaining a one-time dip can help."},{"q":"Can I qualify with one year of returns?","a":"Possibly, if the AUS allows it and the business has a long history (verify). Many jumbo lenders still require two years."},{"q":"Do K-1 losses count against me?","a":"Yes. Losses from any entity, including passive investments, reduce your qualifying income."},{"q":"How are guaranteed payments treated?","a":"Guaranteed payments to partners count as income and are usually averaged over two years."},{"q":"Is a non-QM loan better for me?","a":"Only if agency or jumbo calculations can't capture your income fairly. Non-QM costs more, so we check agency first."}],"aeQuestions":["Which income worksheet do you use?","Distribution vs liquidity test details?","One-year return allowance?","YTD P&L requirements?","How do you treat K-1 losses from passive investments?","Jumbo K-1 overlays?","Turn times for self-employed underwriting?","Broker comp plan (no term-based comp)?"],"redFlags":["K-1 income without distributions or liquidity","Declining income","Unfiled extensions","Large K-1 losses","Business debt maturing","Inconsistent ownership percentages"],"pricing":"Agency and prime jumbo options generally price better than non-QM, so the first job is calculating K-1 income the way agency underwriters do. If distributions or liquidity don't support the income, consider whether a non-QM bank-statement program captures it fairly, and show the cost difference. Coordinate with the borrower's CPA on extensions and filing timing to avoid delays. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide a written comparison of options.","marketing":["CPA partnerships","Medical/dental group administrators","Law firm events","Business owner associations","Content on K-1 income"],"checklist":["Personal tax returns (1-2 years)","All K-1s","Business returns for 25%+ ownership (1065/1120-S)","YTD P&L and balance sheet (if required)","Operating/partnership agreement","Business bank statements (liquidity)","Distribution history","Income worksheet (Form 1084/91)","Business verification (CPA letter/license)","Credit report","Appraisal","Asset statements"],"updated":"2026-11"},
"d_hero":{"matrix":[["Florida Hometown Heroes","First-time buyers in eligible occupations; up to $35,000 (capped at a % of loan - verify) 0% deferred second; FY 2026-27 funding reopened 7/13/2026 (verify availability)"],["Nevada Home Is Possible for Heroes","Eligible occupations include military, veterans, first responders, teachers, healthcare workers; terms vary (verify)"],["California","No statewide hero-only DPA currently (verify); CalHFA MyHome and Dream For All (lottery rounds) open to eligible buyers generally"],["Arizona","Home Plus statewide DPA (income cap updated 2026 - verify); no hero-only state program known (verify)"],["Illinois","IHDA programs open to eligible buyers; no hero-only statewide program known (verify)"],["Good Neighbor Next Door","50% off HUD homes in revitalization areas for eligible teachers, LEOs, firefighters, EMTs (see GNND entry)"],["First-time buyer","Most programs: no ownership in 3 years (exceptions) - verify"],["Income/price limits","County-based (verify)"],["Homebuyer education","Usually required"],["Private rebate networks","Allowed only if permitted by state law, the loan program and disclosed on CD (verify)"]],"walkthrough":["Verify the borrower's occupation and employer against each candidate program's eligible-occupation list (job title alone isn't enough; some require full-time or specific employers)","Confirm first-time buyer status (typically no ownership in 3 years) and note exceptions such as veterans","Check income and purchase-price limits for the county; note whether the program counts borrower or household income","Check program funding status the same day you quote it (e.g., Florida Hometown Heroes funding windows)","Choose the first mortgage that pairs with the assistance: FHA, VA, USDA or HFA conventional","Enroll the borrower in the required homebuyer education course before writing offers","Issue pre-approval showing assistance amount, repayment terms and backup plan if funds run out","Reserve assistance immediately after contract acceptance; track reservation expiration","Obtain employer verification of eligible occupation on the program's form","Submit compliance package to the HFA and clear conditions before closing","Provide written disclosure of second-lien repayment or forgiveness terms","Close; record second lien and calendar repayment triggers in the client file"],"incomeExample":{"title":"Illustrative Hometown Heroes stacking","steps":["Price $400,000; FHA 3.5% down = $14,000","Closing costs ~ $10,000","Hometown Heroes second (illustrative) up to 5% of loan ~ $19,300 (verify cap)","Buyer funds needed ~ $24,000 - $19,300 = ~$4,700"],"result":"Assistance covers most cash needed. Illustrative."},"scenarios":[{"t":"Florida firefighter with Hometown Heroes","who":"Andre, 35, firefighter/paramedic, Tampa","situation":"Andre has served 8 years with the county fire department and rents an apartment. He has $9,000 saved and 700 credit. He wants a $400,000 home near his station. Hometown Heroes reopened in July 2026 with new funding (verify availability).","structure":"FHA first mortgage plus Hometown Heroes 0% deferred second (verify maximum and percentage cap)","numbers":"FHA 3.5% down $14,000 + closing ~ $10,000; assistance up to $35,000 capped by % of loan (verify)","why":"Firefighters are an eligible occupation and he is a first-time buyer. The deferred second covers most of his cash needs. Keeping his savings intact gives him reserves for hurricane-season repairs.","alternatives":"Florida Assist or other Florida Housing DPA if Hometown Heroes funds are exhausted. A VA loan if he has qualifying military service, with no down payment at all.","watch":"Funding can be fully reserved within weeks. The second is repaid on sale, refinance or payoff of the first (verify), so refinancing later requires planning."},{"t":"Nevada teacher using Home Is Possible for Heroes","who":"Rosa, 29, middle school teacher, Henderson NV","situation":"Rosa earns $58,000 in her fourth year of teaching. She has $6,000 saved and a car payment. Henderson prices put most homes near $420,000. Nevada's Home Is Possible for Heroes lists teachers among eligible occupations (verify current terms).","structure":"Home Is Possible for Heroes assistance paired with FHA or conventional (verify)","numbers":"Price $420,000; assistance per current program grid (verify)","why":"The hero program is designed for her occupation. Assistance closes her down payment gap. Pairing with FHA works with her moderate DTI.","alternatives":"Standard Home Is Possible DPA if hero-specific terms change. A condo near $300,000 would lower her DTI and cash needs.","watch":"DTI with her car payment is tight. Confirm the assistance repayment terms and any rate trade-off."},{"t":"California nurse without a statewide hero program","who":"Jenny, 32, ICU nurse, Murrieta","situation":"Jenny earns $125,000 and assumed there was a California nurse program. California currently has no statewide hero-only DPA (verify). She has $15,000 saved. Homes she likes cost about $580,000.","structure":"CalHFA MyHome with FHA or CalHFA conventional, if her income fits Riverside County limits (verify)","numbers":"CalHFA MyHome up to 3.5% of price (verify) = ~ $20,300","why":"CalHFA programs serve eligible buyers regardless of occupation. Her savings plus assistance cover down payment and costs. Being honest about what exists builds trust.","alternatives":"Conventional 3% down with seller credits if her income exceeds CalHFA limits. Dream For All in a future lottery round if she is a first-generation buyer (verify).","watch":"Her income may exceed county limits. Avoid marketing that implies a nonexistent 'nurse grant'."},{"t":"Deputy buys a HUD home through GNND","who":"Mike, 40, sheriff's deputy, Riverside","situation":"Mike patrols a revitalization area where a HUD-owned home is listed at $400,000. Good Neighbor Next Door offers 50% off list for eligible law enforcement officers. He must live in the home 3 years. He has excellent credit.","structure":"GNND purchase with FHA ($100 down) plus HUD's silent second for the discount","numbers":"List $400,000; price $200,000; silent second $200,000 (verify)","why":"The discount is the largest benefit available to him. FHA allows $100 down on GNND purchases. The silent second is forgiven if he meets the occupancy term.","alternatives":"A standard FHA or VA purchase elsewhere if no GNND homes fit. A conventional purchase if he wants a larger home outside revitalization areas.","watch":"GNND uses a lottery among eligible bidders. Selling or moving within 3 years triggers repayment of the second (verify)."},{"t":"Arizona EMT using Home Plus","who":"Carlos, 27, EMT, Mesa","situation":"Carlos earns $52,000 plus overtime and has 660 credit. Arizona has no EMT-specific state program, but Home Plus is statewide (verify). He wants a $380,000 home. He has $5,000 saved.","structure":"FHA with Home Plus DPA (assistance percentage per current program - verify)","numbers":"Assistance ~ 3-5% of loan (verify)","why":"Home Plus pairs with FHA and fits his credit. His income is under the statewide cap (verify 2026 limit). The assistance covers most of his down payment.","alternatives":"A private rebate network if allowed and disclosed, though savings are usually smaller. Building savings for 6-12 months to add reserves.","watch":"Overtime counts only with history. Arizona Is Home has run out of funds for 2026 (verify), so don't quote it."}],"qa":[{"q":"Is there a special home loan program for teachers in California?","a":"There's no statewide teacher-only down payment program right now (verify). Teachers can use CalHFA programs, Dream For All when a lottery round opens, some district or city workforce-housing programs, and HUD's Good Neighbor Next Door."},{"q":"How much assistance can I get?","a":"It depends on the program. Florida Hometown Heroes offers up to $35,000, capped by a percentage of the loan (verify). Other programs use a percentage of the price or loan amount."},{"q":"Do I have to be a first-time buyer?","a":"Most state hero and down payment programs require that you haven't owned a home in the last 3 years. Veterans and buyers in targeted areas are sometimes exempt."},{"q":"Can I combine hero assistance with a VA loan?","a":"Some programs allow a VA first mortgage, while others pair only with FHA or conventional. We check each program's current rules before you write an offer."},{"q":"Do I have to pay the assistance back?","a":"Many are deferred second loans repaid when you sell, refinance or pay off the first mortgage. Some forgive over time. We review the exact terms in writing before you commit."},{"q":"What happens if the program runs out of money?","a":"Funding windows can close in weeks. We keep a backup plan with another program or a standard loan so your purchase isn't derailed."},{"q":"Are 'Homes for Heroes' rebate programs legitimate?","a":"Some private rebate networks are legitimate where state law and the loan program allow rebates. The rebate must be disclosed on the Closing Disclosure (verify each offer)."},{"q":"Is a lender's 'hero discount' always the best deal?","a":"Not necessarily. Compare the full cost of the loan, including rate, fees and assistance, rather than the label."},{"q":"Do part-time or contract healthcare workers qualify?","a":"It depends on the program's occupation and employment rules. Some require full-time employment with an eligible employer, so we verify with your employer before you rely on it."}],"aeQuestions":["Which state hero/DPA programs are you approved for in CA, IL, NV, FL and AZ?","Current funding status and reservation process for each?","How do you verify eligible occupations?","Can the assistance pair with VA, FHA, USDA and conventional?","Stacking rules with local programs?","Policy on agent rebates or private hero-network credits?","Overlays on FICO/DTI for DPA files?","HFA compliance turn times?","Broker comp treatment for DPA files (no term-based comp)?"],"redFlags":["Program funding exhausted or reservation expired","Occupation doesn't match the program's eligible list","Borrower income or household income over the program limit","Prior homeownership within 3 years disqualifying first-time status","Agent rebate not disclosed or not permitted by the investor","'Hero discount' marketing that offers no real savings","Borrower doesn't understand repayment triggers on the second","Co-marketing arrangements that could violate RESPA Section 8"],"pricing":"Hero programs often pair with HFA first mortgages whose pricing may differ from standard loans, so compare total cost over the expected holding period, not only cash to close. Explain the subordinate lien's repayment triggers in writing. Be skeptical of 'hero discounts' that simply re-label normal pricing. Disclose any rebates on the CD. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written side-by-side comparisons.","marketing":["Teacher union and school district benefits fairs","Hospital HR and nurse residency program workshops","Fire, police and EMS association newsletters","Military and veteran organizations (Steven's Navy network)","Social posts when funding windows open (e.g., FL Hometown Heroes reopening)","Agent co-hosted seminars (no referral fees; RESPA Section 8)"],"checklist":["Occupation verification","Education certificate","Income docs","Reservation","Purchase contract","Appraisal","Compliance package","Credit","Assets","Second lien docs"],"updated":"2026-11"},
"d_gig":{"matrix":[["Agency 1099/Schedule C","Self-employment: typically 2 years tax returns; 12-24 months possible with AUS and prior same-field history (verify)"],["Net income","Schedule C net profit plus allowable add-backs (depreciation, business use of home, mileage depreciation portion) (verify)"],["Rideshare/delivery","Mileage deduction reduces net income; depreciation portion of standard mileage may be added back (verify)"],["Royalties","Fannie: 12 months receipt; 3-year continuance (verify)"],["Union entertainment W-2s","Multiple W-2s averaged over 2 years; industry-typical gaps analyzed (verify)"],["Athlete contracts","Continuance per contract; signing bonuses typically non-recurring (verify)"],["Non-QM 1099-only","1-2 years 1099s, expense factor (often 10%) (lender-specific)"],["Non-QM bank statement","12-24 months deposits; 50% expense factor or CPA P&L (lender-specific)"],["Platform payouts","Annual summaries reconcile to tax returns"],["Foreign income","Must appear on U.S. returns for agency"],["Reserves","Higher for volatile income (lender-specific)"],["DTI","Agency up to 50% (AUS); non-QM up to 50-55% (lender-specific)"]],"walkthrough":["Inventory every income stream: each platform, 1099 client, royalty, residual, endorsement or contract, with start dates","Collect 2 years of personal returns, all 1099s and platform annual summaries; reconcile 1099 totals to Schedule C gross receipts","Calculate agency qualifying income: Schedule C net plus add-backs (depreciation, business use of home, depreciation component of standard mileage - verify)","Check the trend: compare years and YTD deposits; a declining year may control","For union entertainment workers, average total W-2 earnings across all employers for 2 years and note industry gaps","For royalties, document 12 months of receipt and 3 years of expected continuance (verify)","For athletes and performers, review contracts for guaranteed amounts and terms","If agency income is short, run 1099-only and bank-statement non-QM comparisons with the lender's expense factor","Confirm reserves: variable earners often need more (lender-specific)","Issue pre-approval with the chosen documentation path","Underwrite; answer large-deposit and gap questions with documents","Close"],"incomeExample":{"title":"Illustrative rideshare driver Schedule C","steps":["Gross receipts 2024 $68,000; 2025 $74,000","Standard mileage deduction 2025: 40,000 miles x IRS rate (e.g., ~$0.70) = ~$28,000","Depreciation portion of mileage add-back (e.g., ~$0.30/mile x 40,000) = $12,000 (verify rate)","Net profit 2025 = $74,000 - $28,000 - other expenses $4,000 = $42,000","Qualifying 2025 = $42,000 + $12,000 = $54,000; 2024 similarly $48,000","Average = $51,000/yr = $4,250/mo"],"result":"Agency qualifying income ~ $4,250/mo; a 1099-only non-QM might use $74,000 x 90% = $66,600/yr (lender-specific) at higher cost. Illustrative."},"scenarios":[{"t":"Multi-app rideshare and delivery driver","who":"Marcus, 33, full-time rideshare and delivery driver, Chula Vista","situation":"Marcus has driven full time for two years across three apps. His 1099s total $74,000 but his mileage deduction is large. Net Schedule C income is about $42,000. He wants a $430,000 condo with 3.5% down.","structure":"FHA purchase using Schedule C net plus the depreciation portion of mileage","numbers":"Qualifying ~ $4,250/mo; PITI ~ $3,100 with HOA; DTI ~ 47% with small debts (illustrative)","why":"FHA pricing and low down payment fit his budget. Adding back mileage depreciation raises usable income meaningfully. His two-year history is stable.","alternatives":"A 1099-only non-QM using gross 1099s less a 10% factor would show more income but costs more. A lower-priced condo would reduce DTI without changing programs.","watch":"Mileage add-back rates differ by tax year. The condo must be FHA-approved."},{"t":"Content creator with rising income","who":"Bella, 27, YouTube creator, Pacific Beach","situation":"Bella's net income was $95,000 in 2024 and $180,000 in 2025 from ads and sponsorships. Her 2026 deposits are running even higher. She wants a $900,000 condo. She has $200,000 saved.","structure":"Conventional using 2-year average, or bank-statement non-QM if more income is needed","numbers":"Agency average $137,500; bank statements ~ $15,000/mo deposits","why":"Agency income may be enough with her large down payment. Rising income supports averaging. Comparing paths shows the true cost of non-QM.","alternatives":"Wait for the 2026 return to raise her average. Buy at a lower price with agency financing.","watch":"Sponsorship revenue is volatile; keep reserves strong. Platform policy changes can affect income."},{"t":"Union actor with residuals","who":"Tom, 45, SAG-AFTRA actor, Burbank","situation":"Tom received W-2s from ten production companies last year plus residuals. His two-year total averages $95,000. He has gaps between projects typical of the industry. He wants to refinance and take some cash out.","structure":"Conventional cash-out averaging 2 years total earnings","numbers":"Average $95,000","why":"Underwriters understand industry patterns. His history spans many years. Agency pricing is best.","alternatives":"Bank-statement non-QM if a lender won't accept the gaps. A HELOC for smaller cash needs.","watch":"Residuals must be documented for continuance. Union earnings records support gaps."},{"t":"Professional athlete on a guaranteed contract","who":"Derrick, 28, MLB pitcher, Scottsdale","situation":"Derrick signed a 3-year guaranteed contract at $2M per year. He wants an offseason home near spring training. His agent provided the contract. He has substantial savings.","structure":"Jumbo using guaranteed contract income","numbers":"Guaranteed $2M/yr through 2028","why":"Guaranteed salary documents continuance. Strong assets support jumbo reserves. A portfolio bank may also compete.","alternatives":"Portfolio bank relationship loan with asset-based pricing. Cash purchase and later cash-out.","watch":"Only guaranteed salary counts. Career-length risk affects lender appetite."},{"t":"Las Vegas residency performer","who":"Rita, 38, musician, Henderson NV","situation":"Rita performs in a Las Vegas residency and earns royalties. Her 1099s total $140,000, but write-offs reduce net income to $60,000. Her residency contract runs two more years. She wants a $600,000 home.","structure":"1099-only non-QM","numbers":"1099s $140,000 x 90% = $126,000 (lender-specific)","why":"Tax returns understate cash flow. 1099-only programs use gross with an expense factor. Her contract supports continuance.","alternatives":"Conventional with Schedule C at a lower price. Bank-statement program.","watch":"Residency contract end date limits continuance. Non-QM pricing and terms must be disclosed."}],"qa":[{"q":"Can I get a mortgage with gig or 1099 income?","a":"Yes. Agency loans typically use 2 years of tax returns. Non-QM 1099-only or bank-statement programs are alternatives when write-offs reduce taxable income."},{"q":"Why is my qualifying income lower than what I earned?","a":"Lenders use net income after business expenses, not gross receipts. Some non-cash items like depreciation are added back, which helps."},{"q":"Can the mileage deduction be added back?","a":"The depreciation component of the IRS standard mileage rate can often be added back (verify lender method). The rest of the deduction stays as an expense."},{"q":"Do royalties count as income?","a":"Usually yes, with about 12 months of receipt and evidence they'll continue for 3 years (verify). Royalty statements and contracts document both."},{"q":"How are athlete contracts treated?","a":"Guaranteed salary can count for the guaranteed period. Signing bonuses and incentives are usually excluded unless they recur."},{"q":"I'm a union actor with many W-2s. Is that a problem?","a":"No. Underwriters average total earnings across all employers over 2 years and understand gaps typical of the industry."},{"q":"What is a bank-statement loan?","a":"A non-QM loan that calculates income from 12-24 months of deposits, minus an expense factor. It costs more than agency financing and often needs a larger down payment."},{"q":"Do I need more reserves?","a":"Often, because income varies. Requirements are lender-specific."},{"q":"Can I qualify with only one year of 1099 income?","a":"Sometimes, with AUS approval and prior work in the same field. Some non-QM programs also allow 12 months."}],"aeQuestions":["How do you add back the depreciation portion of standard mileage?","1099-only program: expense factor and years required?","Bank-statement program: expense factor options and CPA letter requirements?","Royalty income documentation and continuance?","Treatment of athlete guaranteed vs non-guaranteed pay?","How do you handle entertainment-industry W-2 gaps?","Reserves for variable-income borrowers?","Max DTI and minimum FICO by program?","Broker comp plan (no term-based comp)?"],"redFlags":["Declining income","Commingled accounts","Cash income","Short contracts","Large one-time payments","Unfiled returns"],"pricing":"Agency financing is generally the lowest-cost path when tax returns support the income. Non-QM 1099-only and bank-statement programs cost more and often require larger down payments and reserves; compare them only when agency income falls short. Show how waiting for another year of tax returns might change the picture. Don't advise on tax strategy; coordinate with the borrower's CPA. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written side-by-side comparisons.","marketing":["Driver hubs and online driver communities (educational content)","Creator and podcaster meetups in San Diego and LA","SAG-AFTRA/IATSE financial wellness events","Sports agents and athlete business managers","Short videos: 'How lenders see 1099 income'"],"checklist":["Tax returns","1099s","Platform summaries","Contracts","Royalty statements","Bank statements","Credit","Appraisal","Union records","P&L"],"updated":"2026-11"},
"d_variable":{"matrix":[["Fannie Mae bonus/OT/commission","Generally 2-year history recommended; 12-24 months acceptable with positive factors (verify B3-3.1-01)"],["Freddie Mac","At least 12 months with 2-year history typical; documented likelihood of continuance (verify)"],["FHA","2-year average; 1-2 years acceptable with justification (verify 4000.1)"],["VA","Similar 2-year averaging for variable pay (verify)"],["Averaging","Typically 2-year + YTD average; declining income uses lower/current figure"],["Seasonal employment","2-year history and expectation of rehire; seasonal unemployment compensation may count with 2-year history (verify)"],["Commission job change","New commission role may need fresh history (lender-specific)"],["WVOE","Breaks out base, OT, bonus, commission (Form 1005 or electronic)"],["Tax returns","May be required if commission is significant or unreimbursed expenses exist (lender-specific)"],["Tip income","Documented on W-2/paystubs; 2-year history (verify)"]],"walkthrough":["Collect 30 days of paystubs with YTD totals and 2 years of W-2s","Order a WVOE (Form 1005 or The Work Number) that breaks out base, overtime, bonus and commission by year","Calculate base pay separately from the hourly rate or salary and hours","For each variable component, compute the 2-year plus YTD average","Compare years: if the current or most recent year is lower, use the lower figure unless stabilization is documented","For commission earners, check whether tax returns and unreimbursed expenses are required (lender-specific)","For seasonal workers, get the rehire letter and 2-year history; include seasonal unemployment compensation if documented (verify)","Confirm with the employer that the pay type is expected to continue","Issue pre-approval on the conservative number and explain the math to the borrower","Advise against job changes or pay-structure changes before closing","Underwrite and clear any income conditions","Close"],"incomeExample":{"title":"Illustrative nurse with overtime","steps":["Base pay $48/hr x 36 hrs x 52 = $89,856/yr = $7,488/mo","Overtime 2024 $22,000; 2025 $26,000; 2026 YTD (10 months) $23,000","OT average (2024 + 2025 + YTD) / 34 months = $71,000 / 34 = $2,088/mo","Trend stable/increasing, so average used","Total qualifying = $7,488 + $2,088 = $9,576/mo"],"result":"Overtime adds about $2,088/mo when history and trend support it. Illustrative."},"scenarios":[{"t":"ICU nurse with steady overtime","who":"Kim, 34, ICU nurse, Murrieta","situation":"Kim's base pay is $89,856, and she has worked consistent overtime for three years. Her OT was $22,000, then $26,000, and $23,000 so far this year. Base pay alone won't support the $640,000 home she wants. She has 5% down.","structure":"Conventional 5% down with OT averaged over 2 years plus YTD","numbers":"Qualifying $9,576/mo vs $7,488 base only","why":"Her history and stable trend support counting overtime. The hospital confirms OT continues due to staffing needs. Adding OT moves her into the price range she needs.","alternatives":"Qualify on base pay only at a lower price around $520,000. FHA with lower down payment if her DTI is tight.","watch":"A hospital policy limiting OT would reduce income. The WVOE must state OT is likely to continue."},{"t":"Commissioned pharmaceutical rep","who":"Brian, 40, pharmaceutical sales rep, Carmel Valley San Diego","situation":"Brian has been with the same employer for five years. His base is $70,000 and commission has averaged $80,000. His territory was recently expanded. He wants an $1.1M home with 20% down.","structure":"Conventional high-balance using 2-year average commission","numbers":"Base $70,000 + commission average $80,000 = $150,000/yr","why":"Long tenure with the same employer supports commission continuance. Averaging smooths swings. High-balance conforming offers better pricing than jumbo.","alternatives":"Prime jumbo with larger down payment. Wait for current-year commissions if they're much higher.","watch":"Changing employers before closing would reset commission history. Expanded territory pay must be confirmed by WVOE."},{"t":"Seasonal vineyard supervisor","who":"Rosa, 38, vineyard supervisor, Temecula Valley","situation":"Rosa works March through November each year and receives seasonal unemployment in winter. She has done this for 8 years with the same winery. Her wages are $38,000 and UI is about $6,000. She wants a $350,000 home.","structure":"FHA or USDA (if property eligible) using seasonal wages plus documented seasonal unemployment","numbers":"Total ~ $44,000/yr averaged","why":"Her long history with the same employer shows continuity. Seasonal UI can count when documented on tax returns. FHA and USDA fit her income.","alternatives":"Conventional with wages only at a lower price. A CalHFA program if eligible (verify).","watch":"The winery must provide a rehire letter. UI must appear on her tax returns for both years."},{"t":"Bonus-heavy analyst with a dip","who":"Ryan, 32, financial analyst, Chicago","situation":"Ryan's bonus fell from $40,000 to $28,000 last year after a slow market. His base is $95,000. His employer says bonuses are discretionary. He wants a $500,000 condo.","structure":"Conventional using the lower recent bonus","numbers":"Bonus counted at $28,000","why":"Underwriters use declining figures. Base pay is stable. The condo price still works with the lower bonus.","alternatives":"Wait for the current-year bonus. Qualify on base only.","watch":"Discretionary bonuses get extra continuance scrutiny. Use the lower recent figure unless stabilization is documented."},{"t":"Tipped casino dealer","who":"Lina, 29, blackjack dealer, Las Vegas","situation":"Lina's base pay is $28,000, and tips reported through payroll add $34,000. She has worked at the same casino for 4 years. She wants an FHA loan on a $350,000 home. Her credit is 670.","structure":"FHA with reported tips documented on W-2s and paystubs","numbers":"Total $62,000/yr","why":"Reported tips are documented income. Her tenure supports continuance. FHA fits her credit.","alternatives":"Conventional if her score rises. A smaller condo.","watch":"Unreported cash tips cannot be used. Tip income must appear on W-2s for two years."}],"qa":[{"q":"Does overtime count as income?","a":"Yes, when you have a history (usually 2 years) and your employer confirms it's likely to continue. Lenders average it over that period."},{"q":"How much history do I need for bonus, overtime or commission?","a":"Typically 2 years. 12-24 months may work with strong factors such as a steady employer and rising pay (verify program)."},{"q":"What if my bonus went down last year?","a":"Underwriters usually use the lower, more recent figure. If the decline was one-time and pay has stabilized, a written explanation and documents can help."},{"q":"How is commission income calculated?","a":"Usually a 2-year plus YTD average. Some lenders require tax returns to check unreimbursed business expenses."},{"q":"I'm a seasonal worker. Can I qualify?","a":"Yes, with a 2-year history in the same seasonal work and a reasonable expectation of rehire. Seasonal unemployment compensation may count when it shows on your tax returns (verify)."},{"q":"Do tips count?","a":"Tips reported on your W-2s and paystubs can count with history. Unreported cash tips can't be used."},{"q":"Can you use my YTD pay annualized?","a":"Usually not if prior years were lower. Lenders average to avoid overstating income."},{"q":"What if I change jobs?","a":"A new commission or bonus structure can reset your history. Talk to us before switching jobs during the process."},{"q":"What is a WVOE?","a":"A written verification of employment from your employer that breaks out base, overtime, bonus and commission. It speeds up variable-income underwriting."}],"aeQuestions":["Minimum history for OT/bonus/commission by program?","Do you accept a WVOE (Form 1005) instead of W-2s for breakdown?","How do you treat a declining variable component?","Do you require tax returns for commission income?","Seasonal unemployment compensation: documentation and history?","Tip income documentation?","Commission borrowers who changed employers in the same field?","Turn times?","Broker comp plan (no term-based comp)?"],"redFlags":["Declining variable income","Recent job change into new pay structure","Unreported cash tips","Employer won't confirm continuance","YTD annualized higher than history","Seasonal rehire uncertain"],"pricing":"Variable income doesn't change pricing directly; it changes how much income qualifies and therefore the loan size and program fit. Run conservative calculations up front so pre-approvals hold through underwriting. Compare conventional, FHA, VA and USDA where eligible. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons.","marketing":["Hospital nursing units and unions","Sales teams at dealerships, brokerages and SaaS firms","Agricultural employers in Temecula Valley and Central Valley","Casino and hospitality HR in Las Vegas","Content: 'How lenders count overtime and bonus'"],"checklist":["30 days paystubs with YTD","2 years W-2s","WVOE with breakdown","Tax returns (if required)","Seasonal rehire letter","Unemployment compensation records (seasonal)","Employer continuance confirmation","Income worksheet","Credit report","Appraisal","Asset statements"],"updated":"2026-11"},
"d_trust":{"matrix":[["Fannie revocable trust","Inter vivos revocable trust eligible when requirements met (verify B2-2-05)"],["Freddie revocable trust","Eligible per Guide 4101.1 requirements (verify)"],["FHA living trust","Allowed with beneficiary-occupant borrower conditions (verify 4000.1)"],["VA","Trust vesting possible with lender approval (verify)"],["Irrevocable trust","Generally non-agency; portfolio/non-QM"],["Inherited property seasoning","Exempt from cash-out seasoning under agency rules (verify)"],["Heir buyout","Structure varies by program (verify)"],["HECM heir payoff","Lesser of balance or 95% of appraised value"],["CA Prop 19","Parent-child exclusion limited to family home becoming heir's primary residence within 1 year, value cap (verify)"],["Title","Successor trustee affidavit or court order"]],"walkthrough":["Find out how title is held today: revocable trust, joint tenancy, sole name with a will, or no estate plan","For a trust: obtain the certification of trust (or full trust if the lender requires) and confirm the trustee has power to borrow","For a death: obtain the death certificate and successor trustee acceptance, or letters testamentary/administration if probate is needed","List all heirs or beneficiaries and their shares; confirm everyone agrees on the buyout figure","Choose the program and transaction type (limited cash-out, cash-out or purchase) based on how title will pass (verify investor rules)","Check the inherited-property exemption from cash-out seasoning for the chosen program (verify)","Order the appraisal; the value drives both the buyout and LTV","Coordinate with the estate attorney and title officer on deeds, trust transfer and payoff instructions","If a HECM is being paid off, confirm the servicer's due date and request extensions if needed","Underwrite the heir's income to carry the full new payment","Close; escrow pays siblings their shares and records the new vesting","Remind California clients about Prop 19 claim forms with the county assessor"],"incomeExample":{"title":"Illustrative heir buyout","steps":["Value $780,000","Daniel's share 1/3 = $260,000 equity","Siblings' shares 2/3 = $520,000","Existing loan $40,000","New loan = $520,000 + $40,000 + costs $15,000 = $575,000","LTV = $575,000 / $780,000 = 73.7%"],"result":"Fits typical cash-out LTV limits; DTI must support the payment. Illustrative."},"scenarios":[{"t":"Siblings keep mom's home","who":"Daniel, 47, firefighter, Temecula","situation":"Daniel and two siblings inherited their mother's home through her living trust. It's worth about $780,000 with a $40,000 loan. Daniel wants to live there and pay his siblings their thirds. He earns $135,000.","structure":"Conventional refinance after the successor trustee distributes the home to Daniel, paying siblings' shares at closing","numbers":"Siblings' shares $520,000 + payoff $40,000 + costs $15,000 = $575,000; LTV 73.7%","why":"It keeps the family home while treating siblings fairly. Inherited property is generally exempt from cash-out seasoning. His income supports the payment on his own.","alternatives":"Sell and split the proceeds if the payment is too high. Have one sibling co-own and co-borrow, sharing the payment.","watch":"Prop 19 requires the home to become his principal residence within one year for the exclusion. The trust distribution deed must record before or at closing."},{"t":"Living-trust vesting on a new purchase","who":"Helen, 66, retired teacher, Carlsbad","situation":"Helen is buying a $900,000 condo with 30% down. Her estate attorney wants the property vested in her revocable living trust. Her trust was drafted years ago. She is the trustee and beneficiary.","structure":"Conventional purchase vested in the revocable trust meeting agency requirements","numbers":"Loan $630,000","why":"Vesting in the trust at closing avoids a later transfer deed. Agency rules accept revocable trusts that meet requirements. Her estate plan stays intact.","alternatives":"Vest in her own name and transfer to the trust after closing, which most lenders allow. Use a different lender if one balks at the trust.","watch":"The trust must give the trustee power to borrow and encumber real property."},{"t":"Heir pays off a HECM to keep the home","who":"Maria, 52, office manager, Chula Vista","situation":"Maria's mother passed with a HECM balance of $520,000 on a home worth about $600,000. The servicer sent a due-and-payable notice. Maria wants to keep the home. She earns $92,000.","structure":"Conventional purchase/refinance by Maria paying off the HECM","numbers":"Payoff = lesser of balance or 95% of value = $520,000","why":"She keeps the family home. HECM non-recourse rules cap the payoff. Her income supports a new loan of that size.","alternatives":"Sell the home and keep the remaining equity. Request a servicer extension while she qualifies.","watch":"HECM servicer deadlines are strict; request extensions in writing early. Maria's loan must close before the due-and-payable deadline."},{"t":"Irrevocable trust ownership","who":"Robert, 71, retired physician, Las Vegas","situation":"Robert's home is held in an irrevocable trust for estate planning. He wants a $500,000 loan for home updates and travel. Agency lenders turned him down. The trust is managed by his son as co-trustee.","structure":"Portfolio or non-QM lender that accepts irrevocable trusts","numbers":"Value $1.2M; LTV ~ 42%","why":"Portfolio lenders can review trust terms individually. Low LTV makes the loan attractive to them. It preserves his estate plan.","alternatives":"A proprietary reverse mortgage if the trust structure allows. Liquidating other assets.","watch":"Trustees' powers and beneficiary consent must be confirmed by counsel."},{"t":"Florida homestead inheritance","who":"Ken, 44, high school coach, Tampa","situation":"Ken and two siblings inherited their father's Florida homestead without a trust. Florida homestead descent rules apply. Ken wants to keep it. Title must be cleared through probate or summary administration.","structure":"Buyout refinance after probate or summary administration","numbers":"Value $420,000; siblings' shares $280,000","why":"Clear title is needed before a lender will refinance. Keeping the home preserves his family's ties. His income supports the payment.","alternatives":"Sell and split proceeds. Keep as co-owners and rent it.","watch":"Florida homestead rules may limit how title passed; title insurance must be available."}],"qa":[{"q":"Can my mortgage be in my living trust's name?","a":"Yes. Fannie Mae, Freddie Mac and FHA allow eligible revocable living trusts when the trust meets their requirements, including giving the trustee power to borrow. The lender reviews a certification of trust or the trust itself."},{"q":"How do I buy out my siblings after inheriting a house?","a":"Usually by refinancing into your own name and paying their shares through escrow at closing. Title typically needs to pass to you first, or the lender must accept the transaction structure."},{"q":"Is there a waiting period before cash-out on inherited property?","a":"Agency rules generally exempt inherited property from the usual ownership seasoning for cash-out refinances (verify). That lets heirs act soon after title passes."},{"q":"Will my property taxes go up in California?","a":"Under Prop 19, the parent-child exclusion applies only if the family home becomes your principal residence within one year, and it's limited by a value cap (verify). Talk to a tax professional and file with the assessor promptly."},{"q":"What if my parent had a reverse mortgage?","a":"Heirs can pay off the lesser of the loan balance or 95% of the current appraised value. The loan is non-recourse, so you never owe more than the home is worth."},{"q":"Do I need probate before refinancing?","a":"If the home wasn't in a trust or held jointly, probate or another legal process usually must transfer title first. A small-estate procedure may apply in some states."},{"q":"Can a lender work with an irrevocable trust?","a":"Usually only portfolio or non-QM lenders. Agency programs generally don't accept irrevocable trusts as borrowers."},{"q":"Who signs the loan documents?","a":"The trustee(s) and any individual borrowers, according to the trust and lender requirements. The title company confirms signing authority."}],"aeQuestions":["Do you require the full trust or accept a certification of trust?","Trust vesting rules for purchase vs refinance?","Inherited-property seasoning exemption for cash-out?","How do you treat heir buyouts (limited cash-out vs cash-out)?","Irrevocable trust acceptance?","FHA living trust requirements?","Turn times on trust review?","Title requirements for successor trustees?","Broker comp plan (no term-based comp)?"],"redFlags":["Trust lacks borrowing power","Title not yet vested in heir","Disputes among heirs","Elderly trustee influenced by others","HECM due-and-payable deadlines approaching","Prop 19 reassessment overlooked"],"pricing":"Heir buyouts priced as limited cash-out can cost less than cash-out refinances, so structure matters. Compare agency, FHA and portfolio options; trust vesting itself typically doesn't change pricing. Consider timing with probate and any HECM payoff deadlines. Refer property tax and estate questions to professionals. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons.","marketing":["Estate planning attorney seminars","Professional fiduciary groups","Senior real estate specialists","Content: 'Keeping an inherited home in California under Prop 19'","Past reverse mortgage client families (education)"],"checklist":["Trust certification or full trust","Death certificate","Letters testamentary/administration (if probate)","Successor trustee documents","Heir buyout agreement","Payoff statements (incl. HECM)","Appraisal","Title commitment","Borrower income and assets","Credit report","Prop 19/BOE filing reminder","Homeowners insurance"],"updated":"2026-11"},
"d_probate":{"matrix":[["CA court confirmation","Required unless PR has full IAEA authority (verify Probate Code)"],["Overbid","Minimum overbid increment and 10% deposit typical in CA (verify)"],["Contingencies","Often limited/as-is in court-confirmed sales (verify)"],["Owner-occupant renovation","FHA 203(k), HomeStyle, CHOICERenovation"],["Investor financing","Bridge/fix-and-flip/hard money (lender-specific)"],["Heir refinance","After title vests; inherited property exempt from cash-out seasoning (verify)"],["Minimum property standards","FHA/VA require safety/soundness; renovation loans can cure"],["Lock periods","Plan for 60-120 days due to court timelines"]],"walkthrough":["Confirm the sale type with the listing agent: court-confirmed sale or personal representative with full IAEA authority (CA)","Pre-approve the buyer with a renovation option (203(k), HomeStyle, CHOICERenovation) if the home is dated","Have the agent submit the offer with probate addenda and understand the deposit required for any overbid","Arrange inspections where allowed; many court-confirmed sales are as-is with limited contingencies","Obtain contractor bids early and, for 203(k) Standard, engage a HUD consultant","Lock for 60-120 days or negotiate an extension policy because court dates move","Track the confirmation hearing date; the buyer or agent attends prepared for overbids","Order as-is and as-completed appraisals once the sale is confirmed or scheduled","Collect letters testamentary/administration and the court order confirming sale for title","Underwrite and clear conditions so the loan can fund soon after the court order","Close; for renovation loans, set up the draw schedule and contingency reserve","For heirs keeping the home, wait for title to vest, then refinance or renovate"],"incomeExample":null,"scenarios":[{"t":"Owner-occupant buys a dated probate home","who":"Jessica, 34, physical therapist, Escondido","situation":"Jessica found a 1970s home listed through probate at $560,000. It needs a roof, electrical panel and kitchen. The executor does not have full IAEA authority, so a court confirmation hearing is required. She has $30,000 saved.","structure":"FHA 203(k) Standard financing purchase plus $95,000 in renovations, with a lock long enough for the court date","numbers":"Total $655,000; 3.5% down ~ $22,900","why":"One loan covers purchase and repairs that would fail FHA standards. Her savings fit the down payment with some reserve. Probate pricing leaves room for the renovation to create equity.","alternatives":"Fannie HomeStyle if her credit supports conventional pricing and she wants to avoid lifetime MIP. Buying a move-in-ready home would cost more but close faster.","watch":"An overbid at the hearing could push the price beyond her budget. Lock extensions cost money if the hearing is continued."},{"t":"Heir keeps and renovates parents' home","who":"Tony, 41, electrician, Riverside","situation":"Tony and two siblings inherited their parents' home through probate. The siblings agree he can keep it for $200,000 to each of them. It needs $60,000 of updates. He earns $105,000 and wants a single loan.","structure":"After title vests, HomeStyle renovation refinance or cash-out plus renovation (inherited property seasoning exemption - verify)","numbers":"As-is $520,000; as-completed $610,000; buyout $400,000 + reno $60,000","why":"Combining buyout and renovation avoids two closings. Inherited property is generally exempt from cash-out seasoning. The as-completed value supports the loan.","alternatives":"Cash-out refinance for the buyout now and renovate later with a HELOC. Selling and splitting the proceeds if the payment is too high.","watch":"Title must be in his name before the refinance. Siblings' agreement should be documented by the estate attorney."},{"t":"Investor buys an estate property to renovate","who":"Samir, 46, investor, Chula Vista","situation":"Samir wants to buy a $480,000 estate home, renovate it for $80,000 and resell around $680,000. The sale requires court confirmation. He must bring a 10% deposit if he overbids. He has done six flips.","structure":"Fix-and-flip bridge loan funding purchase and rehab draws","numbers":"Purchase $480,000; rehab $80,000; ARV $680,000","why":"Bridge lenders accept as-is condition and close quickly after confirmation. His experience earns better terms. Profit margin supports the higher cost.","alternatives":"Pay cash and then refinance into a DSCR loan if he keeps it as a rental. Partner with a private lender for faster funding.","watch":"Court timelines extend holding costs. The overbid deposit must be available in certified funds."},{"t":"Executor with full IAEA authority","who":"Linda, 39, teacher, Temecula","situation":"Linda is buying a $650,000 probate home where the executor has full authority under the Independent Administration of Estates Act. No court confirmation is needed, but heirs receive a Notice of Proposed Action. She has 10% down and good credit. The home is in good condition.","structure":"Conventional purchase with standard contingencies as counsel confirms","numbers":"Loan $585,000","why":"Full authority avoids the overbid process. Normal timelines make locking straightforward. The home's condition supports conventional financing.","alternatives":"FHA if she wants a lower down payment. HomeStyle if she wants to add improvements.","watch":"An heir objection during the notice period can delay or require court involvement."},{"t":"Arizona informal probate sale","who":"Greg, 52, warehouse supervisor, Mesa","situation":"Greg is buying a $390,000 home from an estate in informal probate. The personal representative can sell without court confirmation (verify). The house is dated but livable. Greg has 640 credit.","structure":"FHA purchase","numbers":"3.5% down ~ $13,650","why":"FHA fits his credit and the home meets minimum standards. Informal probate keeps the timeline short. Title needs only the PR's letters and deed.","alternatives":"FHA 203(k) Limited to update the kitchen and flooring. Conventional if his score improves.","watch":"Confirm the PR's authority on the letters. Title should verify no creditor claims."}],"qa":[{"q":"Can I get a regular mortgage on a probate home?","a":"Yes, if the home meets the program's property standards. If it doesn't, renovation loans such as FHA 203(k) or HomeStyle can finance the repairs."},{"q":"Why do probate sales take so long?","a":"In California, many probate sales need court confirmation, which can take weeks to months. If the executor has full IAEA authority, no confirmation is needed and timelines are shorter."},{"q":"What is an overbid?","a":"At the confirmation hearing, other buyers can bid higher than your accepted offer, with a required minimum increase and deposit. You can bid again too."},{"q":"Can I include repairs in the loan?","a":"Yes, with FHA 203(k), Fannie HomeStyle or Freddie CHOICERenovation. You'll need contractor bids and the appraisal will consider the as-completed value."},{"q":"Do I get inspection contingencies?","a":"Court-confirmed sales are often as-is with limited contingencies. Your agent and attorney will explain what protections you have."},{"q":"What happens to my rate lock if the court date moves?","a":"Your lock could expire. We plan a longer lock or price the extension cost up front."},{"q":"I inherited a house. Can I refinance right away?","a":"Once title is in your name you can refinance, and inherited property is generally exempt from cash-out seasoning (verify). Probate or trust administration must be complete first."},{"q":"Can investors use hard money on probate deals?","a":"Yes, bridge and fix-and-flip loans are common for estate properties. They cost more but close quickly and accept as-is condition."}],"aeQuestions":["Do you finance court-confirmed probate purchases, and how do you handle lock extensions?","203(k)/HomeStyle appetite on probate properties?","Required documentation: letters, court order, IAEA authority?","As-is appraisal requirements?","Inherited property seasoning for cash-out?","Fix-and-flip/bridge terms for estate purchases?","Turn times?","Broker comp plan (no term-based comp)?"],"redFlags":["Executor lacks authority","Court date uncertain or repeatedly continued","Property fails minimum standards without renovation plan","Unpermitted additions","Title defects from incomplete administration","Heirs disputing sale"],"pricing":"Renovation loans and bridge loans cost more than standard purchase loans; compare total cost including lock extensions caused by court timelines. Show the trade-off between paying a lock extension and floating. For heirs, compare renovation refinance vs cash-out plus separate financing. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons.","marketing":["Probate attorney and fiduciary education sessions","Probate-specialist agents","Estate liquidators and cleanout services","Investor meetups","Content: 'Buying a probate home in California'"],"checklist":["Letters testamentary/administration","IAEA authority evidence or court order confirming sale","Purchase agreement with probate addenda","Overbid deposit plan","Contractor bids and scope","203(k) consultant report (if Standard)","As-is and as-completed appraisal","Title commitment","Lock extension plan","Borrower income and assets","Insurance (vacant property)"],"updated":"2026-11"},
"d_contract_deed":{"matrix":[["Rent credit (Fannie)","Above-market rent portion under lease-option may count toward down payment (verify)"],["Rent credit (FHA)","Amount exceeding market rent with documentation (verify)"],["Land contract payoff (Fannie)","May be limited cash-out refinance; within 12 months LTV based on lower of acquisition cost or value (verify)"],["FHA land contract","Per 4000.1 refinance rules (verify)"],["Payment history","12+ months documented"],["Title","Must confirm seller ownership and liens"],["Credit","Standard; non-traditional where allowed"],["State law","IL Installment Sales Contract Act; AZ agreement-for-sale forfeiture rules; CA Civil Code 2985 (verify)"]],"walkthrough":["Read the lease-option, rent-to-own or land contract in full","Identify option price, deadlines, payment history and who holds title","Collect 12-24 months of payment proof (cancelled checks, bank statements)","Order title search early to find seller liens, judgments or an underlying mortgage","Obtain seller's payoff statement or contract balance","Order appraisal with market rent analysis (for rent credit)","Determine transaction type under the chosen program (purchase vs limited cash-out - verify)","Refer to a real estate attorney for unrecorded or problematic contracts","Underwrite with non-traditional credit if needed","Close; ensure deed is recorded and seller's liens are released"],"incomeExample":{"title":"Illustrative rent credit","steps":["Contract rent $2,600/mo","Appraiser market rent $2,300/mo","Excess $300/mo x 36 months = $10,800","Credit toward down payment (verify)"],"result":"Reduces cash needed by $10,800. Illustrative."},"scenarios":[{"t":"Lease-option tenant exercises her option","who":"Andrea, 36, dental assistant, Menifee","situation":"Andrea signed a 3-year lease with an option to buy at $520,000. She has paid $2,600 a month, $300 above market rent, specifically as option credit. The option expires in four months. She has $9,000 saved and 680 credit.","structure":"FHA purchase applying the above-market rent as a credit toward her required investment (verify program documentation)","numbers":"36 x $300 = $10,800 potential credit; 3.5% of $520,000 = $18,200","why":"FHA and Fannie allow credit for rent paid above market under a documented lease-purchase. The credit plus her savings covers most of the required investment. Closing before the option deadline preserves her contract price.","alternatives":"Conventional 3-5% down without rent credit if documentation is weak, using a gift for the gap. Negotiate a seller credit for closing costs within interested-party limits.","watch":"The appraiser must establish market rent to support the credit. Cancelled checks or bank records must show all 36 payments."},{"t":"Paying off an Arizona agreement for sale","who":"Luis, 44, landscaping business owner, Phoenix","situation":"Luis bought on an 'agreement for sale' from a private investor four years ago at a high contract rate. He owes $210,000 and the home appraises around $340,000. The seller still has a mortgage on the property. Luis has 2 years of tax returns from his business.","structure":"Conventional or FHA refinance treated per program rules for land contract payoff (verify LCOR vs purchase treatment)","numbers":"New loan ~ $215,000; LTV ~ 63%","why":"A mortgage at market terms likely costs far less than his contract. Paying off the contract delivers recorded title in his name. Arizona forfeiture rules make staying on a contract risky.","alternatives":"Ask the seller to refinance the contract at a lower rate, which keeps title risk. A non-QM bank-statement loan if his tax returns understate income.","watch":"The seller's underlying mortgage and any liens must be paid at closing. Title must confirm the seller can convey."},{"t":"Unrecorded installment contract in Illinois","who":"Keisha, 38, certified nursing assistant, south Chicago suburbs","situation":"Keisha has paid on an installment contract for five years, but it was never recorded. She owes $90,000 on a home worth about $160,000. The seller is elderly and his children are now involved. She wants a mortgage to finish the purchase.","structure":"Attorney review and cure (recording, seller's estate documents) followed by FHA or conventional refinance/purchase","numbers":"Loan ~ $95,000 including costs","why":"Illinois' Installment Sales Contract Act imposes disclosure and recording duties on sellers (verify). Clearing title protects her equity. A conventional or FHA loan ends contract terms she can't control.","alternatives":"If title can't be cleared quickly, legal action to enforce the contract. An IHDA program may help with closing costs if she qualifies (verify).","watch":"If the seller passes away, probate may be needed before he can convey. Her payment proof must be complete."},{"t":"Exiting a rent-to-own company program","who":"Tyrone, 33, warehouse lead, Las Vegas","situation":"Tyrone entered a corporate rent-to-own program that requires him to buy within three years at a preset price. The deadline is in five months. His price is $380,000, and similar homes recently sold for about $365,000. His credit is 640.","structure":"FHA purchase from the company at a price supported by appraisal, or negotiate the price","numbers":"3.5% down on appraised value","why":"FHA fits his credit. Comparing the preset price to market avoids overpaying. The loan is based on the lower of price or appraised value, so a low appraisal requires renegotiation or more cash.","alternatives":"Ask the company for an extension or price adjustment. Walk away and buy another home with FHA if the program price stays above market.","watch":"Any company 'credits' must be documented to count. Program fees on the closing statement need review."},{"t":"Family contract for deed in Florida","who":"Gloria, 50, school cafeteria manager, Orlando","situation":"Gloria bought her aunt's home on an informal contract for deed six years ago. She owes $120,000 and has paid by check each month. Her aunt wants to be paid off. Florida may treat contracts for deed like mortgages for some purposes (verify).","structure":"Conventional payoff with non-arm's-length disclosure","numbers":"Value $300,000; loan ~ $125,000","why":"Her payment history is clean and documented by checks. The low LTV makes the refinance straightforward. Disclosing the family relationship meets underwriting rules.","alternatives":"FHA if credit is a concern. A gift of equity from her aunt could reduce the payoff if the aunt wants to help.","watch":"Title must confirm the aunt still holds title free of liens. The contract's terms should be reviewed by an attorney."}],"qa":[{"q":"Can my lease payments count toward my down payment?","a":"Sometimes. The portion of rent you paid above market rent under a lease-purchase agreement can be credited if the lease and payments are documented and an appraiser confirms market rent (verify program)."},{"q":"How do I pay off a contract for deed?","a":"You take out a mortgage that pays the seller's remaining balance and any liens, and the seller transfers recorded title to you at closing. Title and escrow handle the payoff."},{"q":"What if the seller still has a mortgage on the house?","a":"Their mortgage must be paid off at closing from the proceeds. Title will find it, which is one reason to order title early."},{"q":"Is a land contract payoff a purchase or a refinance?","a":"It depends on the program and how long the contract has existed. Fannie Mae may treat it as a limited cash-out refinance, with special rules if it's under 12 months old (verify)."},{"q":"What payment records do I need?","a":"Usually 12-24 months of cancelled checks, bank statements or receipts showing on-time payments. Cash payments without receipts are hard to use."},{"q":"What if the contract was never recorded?","a":"An attorney may need to help record it or clear title before closing. Recording problems can delay but often not prevent the loan."},{"q":"What if my contract price is higher than the appraisal?","a":"The loan is based on the lower value, so you'd bring more cash or renegotiate. Lease-option prices set years ago can be above or below market."},{"q":"Can I use an FHA loan?","a":"Often yes, under FHA's purchase or refinance rules for these transactions (verify). FHA's credit flexibility helps many contract buyers."}],"aeQuestions":["Rent credit policy and documentation?","Land contract payoff treatment (LCOR vs purchase)?","12-month rule for contract seasoning?","Non-traditional credit acceptance?","Title requirements for unrecorded contracts?","FHA land contract rules?","Turn times?","Broker comp plan (no term-based comp)?"],"redFlags":["Payments made in cash without receipts","Seller cannot deliver clear title or has judgments/liens","Contract price far above market value","Option or contract deadline close to or before realistic closing date","Seller threatening forfeiture to pressure the buyer","Unrecorded contract with seller deceased or incapacitated","Rent-to-own company fees not disclosed","Buyer encouraged into a higher-cost loan when FHA or conventional fits"],"pricing":"Refinancing out of a contract for deed often lowers cost significantly; show comparison of current contract vs mortgage. Rent credits reduce cash to close but not pricing. Disclose all fees. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons.","marketing":["HUD-approved counselors","Tenant advocacy groups","Real estate attorneys","Content: 'From renter to owner'","Community land trusts"],"checklist":["Lease/option or contract","Payment history 12-24 months","Seller payoff statement","Title search","Appraisal with market rent","Credit","Income docs","Assets","Attorney review","Insurance"],"updated":"2026-11"},
"d_secondhome_nonqm":{"matrix":[["Agency second home","One-unit, part-year occupancy, reasonable distance, no rental pool/management control (verify)"],["Non-QM doc types","Bank statement, 1099, asset depletion, full-doc (lender-specific)"],["Max LTV","Often 75-85% (lender-specific)"],["Reserves","Often 6-12 months (lender-specific)"],["FICO","Often 660-700+ (lender-specific)"],["Condotel","Specialty non-QM; often 25-35% down"],["STR","Some lenders allow limited STR on second homes (lender-specific)"],["Prepayment penalty","Possible; restricted on some owner-occupied/second homes by state/lender (verify)"]],"walkthrough":["Confirm the borrower genuinely intends part-year personal use (not an investment disguised as a second home)","Check agency second-home eligibility first: one unit, distance, no rental pool or management control","If income documentation is the issue, select the right non-QM doc type (bank statement, 1099, asset depletion, full-doc)","If the property is the issue (condotel, non-warrantable), find a lender that accepts that project type","Review HOA documents, rental restrictions and insurance availability","Calculate DTI including the primary residence payment","Confirm reserves after down payment","Issue pre-approval","Order appraisal; review project/HOA","Disclose any prepayment penalty and non-QM cost differences","Close; remind borrower of occupancy certification accuracy"],"incomeExample":{"title":"Illustrative bank-statement second home","steps":["24 months business deposits $480,000","Expense factor 50% (lender-specific)","Qualifying = $240,000/24 = $10,000/mo","Primary PITI $3,500 + second home PITI $3,800 + debts $500 = $7,800","DTI 78% - too high; reduce price or add income"],"result":"Second home PITI must fit with primary housing; illustrative."},"scenarios":[{"t":"Self-employed buyer in Palm Springs","who":"Carla, 49, salon owner, Temecula","situation":"Carla's salon deposits about $40,000 a month, but write-offs leave modest taxable income. She wants a $650,000 condo in Palm Springs for weekends and summers. She has $180,000 saved. Her primary home payment is $3,500.","structure":"Non-QM 24-month bank-statement second-home loan","numbers":"20-25% down; DTI includes both housing payments","why":"Bank statements reflect her salon's real cash flow. She qualifies without changing her tax strategy. A second-home loan matches her personal use.","alternatives":"Agency second home using tax returns at a much lower price. A HELOC on her primary home for a larger down payment, reducing the non-QM loan size.","watch":"Palm Springs and HOA short-term rental rules limit renting. Keep personal use genuine."},{"t":"Retiree buying a winter home","who":"Gene, 67, retired executive, Chicago","situation":"Gene wants a $900,000 winter home in Scottsdale. He has $3M in investments and limited monthly income. His Chicago home is paid off. He doesn't want to sell investments.","structure":"Asset-depletion non-QM or agency using retirement distributions","numbers":"Assets $3M; down 25%","why":"Asset-based income captures his wealth. Agency may work with documented distributions. He keeps investments intact.","alternatives":"Cash purchase from investments. Portfolio bank loan with asset pledge.","watch":"Arizona HOA rules and summer vacancy may affect insurance. Asset haircuts reduce eligible assets."},{"t":"Condo-hotel unit in Las Vegas","who":"Amir, 41, physician, Irvine","situation":"Amir likes a $420,000 condo-hotel unit on the Strip for trips. The unit participates in a hotel rental program when he's away. Agency loans don't allow condotels. He has strong income.","structure":"Non-QM condotel loan","numbers":"25-30% down","why":"Specialty lenders accept condotels. His income easily qualifies. The structure fits the property.","alternatives":"A traditional condo with agency financing. A cash purchase.","watch":"Rental program terms may conflict with second-home personal use. Resale liquidity is limited."},{"t":"Lake Tahoe second home","who":"Julie, 45, tech executive, San Diego","situation":"Julie is buying a $2.2M home on the Nevada side of Lake Tahoe. Her income includes large RSU vests. She has 25% down.","structure":"Jumbo second home or non-QM full-doc","numbers":"Loan $1.65M","why":"Jumbo fits if RSU income is documented. Non-QM backup if needed. Strong reserves help.","alternatives":"Portfolio bank. Cash.","watch":"Wildfire insurance availability at Tahoe can delay closing. RSU income must have vesting history."},{"t":"Florida beach condo","who":"Tom, 58, contractor, Phoenix","situation":"Tom found a $500,000 beach condo in an older building with structural reserve issues. Agency loans won't work because the project is non-warrantable. He has 25% down.","structure":"Non-QM non-warrantable condo loan","numbers":"Loan $375,000","why":"Non-QM accepts the project. His down payment meets requirements. The building is otherwise sound.","alternatives":"A different building with full warrantability. Cash.","watch":"Special assessments may follow structural reviews. Insurance costs in coastal Florida are rising."}],"qa":[{"q":"What makes a home a second home and not an investment property?","a":"Under agency rules, you occupy it for part of the year, it's suitable for year-round use, and it isn't under a rental pool or management agreement that controls occupancy. It must also be a one-unit property a reasonable distance from your primary home."},{"q":"Can I rent out my second home sometimes?","a":"Agency rules restrict rental arrangements that give someone else control. Some non-QM lenders allow limited short-term rental on second homes (lender-specific)."},{"q":"Why would I need a non-QM loan for a second home?","a":"Usually because your income documentation doesn't fit agency rules, such as heavy write-offs, or the property type isn't eligible, such as a condotel. Non-QM fills those gaps at higher cost."},{"q":"How much down payment will I need?","a":"Often 15-30% for non-QM second homes. Condotels and non-warrantable condos are at the higher end."},{"q":"Can I use bank statements to qualify?","a":"Yes, with a bank-statement program that uses 12-24 months of deposits and an expense factor. Your primary housing payment still counts in the ratios."},{"q":"Are condotels financeable?","a":"Through specialty non-QM lenders, typically with 25-35% down. Agency loans don't allow them."},{"q":"Will there be a prepayment penalty?","a":"Some non-QM second-home loans include one, depending on lender and state rules. We disclose it and compare options without one."},{"q":"Can I use a DSCR loan for my second home?","a":"No. DSCR loans are for investment properties. Using one for a home you personally occupy would misstate the loan's purpose."}],"aeQuestions":["Second home max LTV by doc type?","STR allowance on second homes?","Condotel/non-warrantable eligibility?","Reserves?","Prepayment penalty options?","Asset depletion for second homes?","Turn times?","Broker comp plan (no term-based comp)?"],"redFlags":["Second home actually intended as full-time rental","Property too close to primary residence","Rental pool agreement","HOA litigation","Insurance unavailability","Borrower can't afford both homes"],"pricing":"Non-QM second-home pricing reflects documentation type, LTV, credit and property type, and often exceeds agency pricing meaningfully. Compare agency second-home options first; sometimes a larger down payment or different property makes agency possible. Disclose prepayment penalties and how they work. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written side-by-side comparisons.","marketing":["Resort-area agents","CPAs of self-employed clients","Snowbird communities","Content on second-home vs investment rules","Past clients upgrading lifestyle"],"checklist":["Income docs per program","Bank statements","Asset statements","HOA questionnaire","Occupancy certification","Appraisal","Insurance quote","Credit","Rental restrictions review","Purchase contract"],"updated":"2026-11"},
"d_business_purpose":{"matrix":[["TILA exemption","Business-purpose credit exempt (12 CFR 1026.3(a)) - purpose test per commentary (verify)"],["RESPA exemption","Business-purpose exempt (12 CFR 1024.5(b)(2))"],["DSCR cash-out LTV","Often 65-75% (lender-specific)"],["DSCR minimum","Often 1.0-1.25x (lender-specific)"],["Business-purpose HELOC","Bank/credit union, investment property (lender-specific)"],["Owner-occupied","Heightened scrutiny; many lenders decline"],["Guarantees","Personal guarantees common"],["Prepayment","Step-down or yield maintenance (lender-specific)"],["State licensing","Varies (verify)"],["SBA alternative","2026 citizenship/ownership rules (verify)"]],"walkthrough":["Document the business need, amount and use of proceeds","Confirm collateral is investment or commercial property (owner-occupied requires extra review)","Compare SBA (if eligible), bank lines, DSCR cash-out and bridge options","Gather entity documents, EIN, operating agreement","Collect leases/rent rolls and property information","Calculate DSCR and LTV","Obtain term sheets; review prepayment and guaranty terms","Order appraisal","Execute business-purpose and use-of-proceeds certifications","Close; proceeds disbursed to business account","Keep documentation of proceeds use in file"],"incomeExample":{"title":"Illustrative DSCR cash-out","steps":["Market rent $3,800","PITI on $420,000 loan ~ $3,300 (illustrative)","DSCR = 3,800/3,300 = 1.15x","Meets 1.0-1.1x minimum (lender-specific)"],"result":"Qualifies on property cash flow; illustrative."},"scenarios":[{"t":"Rental equity funds a second coffee shop","who":"Tina, 44, coffee shop owner, Temecula","situation":"Tina owns two free-and-clear rental homes and a profitable coffee shop. She needs $250,000 to build out a second location. Her bank offered a small line but not enough. Her tax returns show modest income due to depreciation.","structure":"DSCR cash-out refinance on one rental with a signed business-purpose certification","numbers":"Rental value $600,000; 70% LTV = $420,000; rent $3,800 vs PITI ~ $3,300 = DSCR 1.15x (illustrative)","why":"DSCR loans qualify on the property's rent rather than her tax returns. Proceeds go directly to the business, supporting the business-purpose exemption. Closing can take weeks rather than months.","alternatives":"An SBA 7(a) loan may cost less over time if her business is eligible under 2026 ownership rules (verify). A smaller bank line plus equipment financing avoids encumbering her rental.","watch":"Proceeds must be deposited to the business account and used as certified. DSCR loans often carry 3-5 year prepayment penalties."},{"t":"Contractor needs bonding and equipment capital","who":"Ray, 50, general contractor, El Cajon","situation":"Ray won a larger public contract that requires more bonding capacity and new equipment. He owns a fourplex as an investment. His credit union offers business-purpose HELOCs on investment property. He wants flexibility to draw as needed.","structure":"Business-purpose HELOC on the fourplex (credit union, lender-specific)","numbers":"Line $150,000","why":"A revolving line matches uneven project cash needs. Interest accrues only on what he draws. The credit union knows his business.","alternatives":"Equipment financing secured by the equipment itself, keeping real estate unencumbered. An SBA Express line if eligible (verify).","watch":"Credit union business-purpose HELOCs often require personal guarantees and annual reviews. Payments rise as he draws on the line."},{"t":"Partner buyout with a bridge loan","who":"Sam, 47, IT services owner, Henderson NV","situation":"Sam's business partner wants out within 60 days for $400,000. Sam owns three rentals with equity. A bank loan would take too long.","structure":"Short-term bridge on rentals, refinanced into DSCR loans","numbers":"Bridge $400,000","why":"Speed meets the partner's deadline. DSCR refinances follow. Sam keeps control of the business.","alternatives":"Seller note from the partner. SBA 7(a) acquisition loan if eligible.","watch":"The bridge loan must be refinanced into DSCR loans before maturity. Rents must support DSCR minimums at refinance."},{"t":"Franchise purchase when SBA isn't available","who":"Nina, 39, Scottsdale","situation":"Nina and a co-owner want to buy a franchise. Under 2026 SBA rules, ownership eligibility may exclude them (verify). Nina owns an investment condo.","structure":"Business-purpose cash-out on the condo","numbers":"$300,000","why":"Provides capital outside SBA. The condo's equity supports it. Eligibility rules are applied uniformly.","alternatives":"Conventional business term loan. Franchisor financing.","watch":"Apply SBA eligibility rules uniformly without discouraging on national origin. Business-purpose certification must match actual use of proceeds."},{"t":"Owner-occupied home request","who":"Ben, 55, Chicago","situation":"Ben wants to tap equity in his Chicago primary residence to expand his consulting business. His home is worth $500,000 with a $150,000 mortgage. A business-purpose lender suggested labeling the loan business-purpose. Ben lives in the home.","structure":"Consumer HELOC or cash-out with full TILA protections","numbers":"Value $500,000","why":"Owner-occupied homes call for consumer protections. A business-purpose label shouldn't be used to avoid them. Consumer products may cost less.","alternatives":"SBA. Business line.","watch":"Using a business-purpose label on an owner-occupied home to avoid TILA protections is a compliance risk. A consumer product gives Ben rescission rights and disclosures."}],"qa":[{"q":"What makes a loan 'business-purpose'?","a":"Its primary purpose is business or commercial, judged by factors like the relationship to your business, who manages the property and how proceeds are used. Such loans are generally exempt from TILA and RESPA consumer rules."},{"q":"Can I use my rental property's equity to fund my business?","a":"Yes. DSCR cash-out refinances and business-purpose loans on investment properties are common for this. Proceeds should go to the business."},{"q":"Can I use my primary home for a business-purpose loan?","a":"It's possible in limited cases but heavily scrutinized. Often a consumer HELOC or cash-out refinance with full consumer protections is the right tool."},{"q":"Do I need to show personal income?","a":"DSCR loans qualify mainly on the property's rent. Other business-purpose loans may review business financials and guarantor credit."},{"q":"Are there prepayment penalties?","a":"Often yes, such as step-down penalties over 3-5 years (lender-specific). We disclose them and compare options without penalties."},{"q":"Will I sign a business-purpose certification?","a":"Yes. How you use the proceeds must match the certification, or the loan could lose its exemption."},{"q":"Is SBA cheaper?","a":"Often, if your business is eligible under current SBA rules, including 2026 ownership and citizenship changes (verify). SBA also takes longer to close."},{"q":"How fast can it close?","a":"DSCR loans often close in 2-4 weeks. Bridge loans can be faster but cost more."}],"aeQuestions":["Max cash-out LTV for business-purpose?","DSCR minimum?","Business-purpose HELOC availability?","Prepayment structures?","Entity requirements?","Use-of-proceeds documentation?","Turn times?","Broker fee policy and disclosure?"],"redFlags":["Proceeds used for personal consumer purposes","Owner-occupied home labeled business-purpose to avoid TILA","No real business","Inconsistent purpose statements","Over-leveraged portfolio","Bridge with no exit"],"pricing":"Business-purpose loans price above consumer loans and often include prepayment penalties. Compare to SBA (if eligible), bank lines and consumer HELOCs. Disclose all fees in writing. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)); on business-purpose loans Steven applies the same standard and discloses all fees in writing. Provide written comparisons.","marketing":["CPAs and business brokers","Chambers of commerce","Investor meetups","Content: 'Using rental equity to grow your business'","Commercial bankers' referral of smaller deals (no paid referrals)"],"checklist":["Business purpose certification","Use-of-proceeds statement","Entity documents","EIN","Leases/rent roll","Appraisal","Insurance","Credit","Bank statements","Title"],"updated":"2026-11"},
"d_non_arms":{"matrix":[["FHA identity of interest","85% LTV max generally; exceptions: family principal residence, tenant 6+ months, builder employee, corrective transfer (verify 4000.1)"],["Fannie Mae","Non-arm's-length allowed for primary/second; new construction restrictions (verify)"],["Freddie Mac","Allowed with conditions (verify)"],["VA","Permitted with review (verify)"],["Appraisal","Independent, market value"],["IPC limits","Program-specific"],["Disclosure","Relationship disclosed on application/contract"],["Short sales","Arm's-length affidavits often required"]],"walkthrough":["Identify the relationship between buyer, seller, agents, builder or lender at first contact","Check program rules for that relationship (FHA identity-of-interest exceptions, agency non-arm's-length rules, investment-property limits)","Decide whether a gift of equity is part of the deal","Have the purchase contract drafted by an agent, attorney or escrow with the relationship disclosed","Document tenancy (lease plus 6+ months of rent) or employment for exceptions","Confirm seller credits stay within interested-party contribution limits","Order an independent appraisal; never share a 'target value'","Underwrite with relationship disclosed on the application","Verify no side agreements or cash back","Close through escrow with all parties' roles clear"],"incomeExample":null,"scenarios":[{"t":"Tenant buys from landlord","who":"Marisol, 37, school office manager, Oceanside","situation":"Marisol has rented the same house for 4 years. Her landlord offered to sell it to her for $620,000 without agents. It appraises around $640,000. She has $25,000 saved and 690 credit.","structure":"FHA purchase using the tenant-landlord exception to the identity-of-interest LTV limit (tenancy 6+ months - verify)","numbers":"3.5% down $21,700","why":"The exception keeps standard FHA financing. Buying below appraisal gives her instant equity. Skipping commissions saves the landlord money, supporting the lower price.","alternatives":"Conventional 5% down to avoid lifetime MIP if her score improves. A gift of equity is not available from a landlord, so seller credits within limits may cover costs.","watch":"Lease and 6+ months of rent payments must be documented. An escrow company or attorney should prepare the contract."},{"t":"Son buys parents' home","who":"David, 31, sheriff's deputy, Murrieta","situation":"David's parents are moving to a retirement community and want to sell him their home. It's worth $600,000. They offer a $90,000 gift of equity. David earns $98,000.","structure":"Conventional with gift of equity","numbers":"Loan $510,000; 85% LTV","why":"Family sales are allowed with disclosure. The gift of equity covers his down payment. Price at market value keeps underwriting clean.","alternatives":"FHA with family-member exception. A larger gift to reach 80% LTV and remove MI.","watch":"Relationship disclosed on contract and application; parents consult CPA on gift tax."},{"t":"Builder employee buys a new home","who":"Ashley, 29, sales associate, Menifee","situation":"Ashley works in sales for a homebuilder in Menifee. The builder offers employees a $15,000 discount on a $540,000 new home. The builder's affiliated lender is offering incentives too. She has 5% down.","structure":"FHA builder-employee exception or conventional","numbers":"Net price $525,000","why":"Exceptions exist for builder employees. Discount treatment must be documented. Standard LTV may apply.","alternatives":"Conventional. Independent lender.","watch":"Determine whether the discount is a price reduction or an interested-party contribution. Affiliated-lender incentives must be compared against independent quotes."},{"t":"Loan officer buys own home","who":"Jordan, 35, LO, Henderson NV","situation":"Jordan is a loan officer buying a $480,000 home in Henderson. He'd like to use his own company. Company policy requires that someone else originate and underwrite employee loans. He has 10% down.","structure":"Conventional per company policy","numbers":"Price $480,000","why":"Compliance requires separation. Company policy governs. Independent underwriting.","alternatives":"Use an independent lender to avoid any conflict-of-interest concerns. Have a colleague originate under company employee-loan policy.","watch":"Company employee-loan policy and loan originator compensation rules apply. Underwriting must be independent of Jordan."},{"t":"Business partners transfer a 2-flat","who":"Mike and Tony, 50s, Chicago","situation":"Mike and Tony have co-owned a Chicago 2-flat rental for 10 years. Mike wants to buy Tony's half. The building is worth $650,000 with a $200,000 loan. Rental income covers expenses.","structure":"Conventional investment (verify)","numbers":"Value $650,000","why":"Ownership transition. Rental income supports. Market value appraisal.","alternatives":"A portfolio bank loan that underwrites the property's rents. A seller note from Tony for part of his equity.","watch":"Agency rules on non-arm's-length investment transactions must be verified. The appraisal must be independent of both partners."}],"qa":[{"q":"Can I buy a home from a relative?","a":"Yes. Every major program allows family sales when the relationship is disclosed. A gift of equity from the relative can cover your down payment."},{"q":"Does FHA limit non-arm's-length deals?","a":"FHA generally limits identity-of-interest transactions to 85% LTV. Exceptions keep standard financing for family members buying a principal residence, tenants of 6+ months, builder employees and some others (verify)."},{"q":"Can I buy the home I'm renting from my landlord?","a":"Yes, tenant purchases are common. FHA's exception requires documented tenancy, usually a lease and rent payments for at least 6 months."},{"q":"Do we still need an appraisal?","a":"Yes, an independent appraisal is required. The loan is based on the lower of price or appraised value."},{"q":"Can we skip real estate agents?","a":"Yes, but an attorney or escrow company should prepare the contract and handle funds. Proper documents prevent underwriting delays."},{"q":"Can the seller give me money back at closing?","a":"No cash back beyond allowed credits, and seller credits must stay within program limits. Side agreements are not allowed and can be fraud."},{"q":"Can I buy my employer's house?","a":"Usually, with the relationship disclosed and standard underwriting. Any discount must be documented and treated under program rules."},{"q":"Is a relative sale for an investment property allowed?","a":"Rules differ for investment properties and some programs restrict them. We verify before you sign a contract."}],"aeQuestions":["Non-arm's-length overlays by program?","FHA identity-of-interest documentation?","Builder employee policy?","LO/employee loan policy?","Investment property non-arm's-length eligibility?","IPC limits?","Turn times?","Broker comp plan (no term-based comp)?"],"redFlags":["Relationship not disclosed","Cash back or side agreements","Inflated price","Short tenancy claimed as long","Seller credits over limits","Occupancy misrepresentation"],"pricing":"Non-arm's-length purchases price like any comparable loan, but LTV limits such as FHA's 85% identity-of-interest cap (when no exception applies) can change which program fits best. Compare FHA, conventional and VA structures, including gift-of-equity options. Show cash to close under each. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons and keep the relationship documentation in the file.","marketing":["Landlords with long-term tenants","Estate attorneys","Family-transfer seminars","HR departments","Content: 'Buying from family the right way'"],"checklist":["Purchase contract disclosing relationship","Lease and rent history (tenant)","Gift of equity letter (if any)","Employer letter (employee sales)","Appraisal","Title","Income docs","Credit","Assets","Disclosure of relationship on application"],"updated":"2026-11"},
"d_multigen":{"matrix":[["HomeReady boarder income","Up to 30% of qualifying income with 12 months shared residency (verify)"],["ADU rental income","Allowed on 1-unit with ADU under conditions (verify)"],["Non-occupant co-borrower","Allowed; FHA family higher LTV (verify)"],["2-4 unit owner-occupied","Rental income per program"],["Title","Joint tenancy, TIC, trust"],["HomeReady income limit","Borrower income only (verify)"],["FHA","Family members can be co-borrowers"],["VA","Joint loans with non-spouse veterans possible (verify)"]],"walkthrough":["Map the household: who will live there, who will be on the loan, who will be on title","Identify every potential income source: borrowers, boarder rent, ADU rent, other units","Check property eligibility: legal ADU or JADU, 2-4 unit zoning, HOA rules","Choose program: conventional, HomeReady, FHA, VA (joint loans) or 2-4 unit","Run scenarios with and without each income source","Recommend attorney-drafted co-ownership agreement","Pre-approve with structure documented","Order appraisal with rent schedule where income is used","Underwrite; document shared residency or rent receipts","Close with agreed vesting","Review insurance coverage for multiple households"],"incomeExample":{"title":"Illustrative boarder income","steps":["Borrower income $5,500/mo","Boarder rent $900/mo with 12-month history","Max 30% of qualifying income (verify)","Total qualifying = $6,400/mo"],"result":"Boarder income increases buying power under HomeReady. Illustrative."},"scenarios":[{"t":"Adult daughter buys with her retired parents","who":"Grace, 36, accountant, Chula Vista","situation":"Grace's parents are selling their condo for $500,000 and want to live with her. They need a home with a casita so everyone has privacy. Grace earns $110,000 and her parents have $5,800 a month in pension and Social Security. They want a $950,000 home.","structure":"Conventional with Grace and both parents as occupying co-borrowers; parents contribute $250,000 from their condo sale","numbers":"Loan ~ $700,000; LTV ~ 74%","why":"Combining three incomes and the parents' equity makes the price workable. All three occupy, so standard primary-residence rules apply. The casita gives the parents a separate living space.","alternatives":"Grace buys alone with parents as non-occupant co-borrowers, but they'd lose their homestead and simplicity of shared ownership. Buy a duplex so the parents' unit is fully separate and potentially rentable later.","watch":"An attorney-drafted co-ownership agreement should cover the parents' $250,000 contribution. The casita must be permitted if any rental use is planned."},{"t":"HomeReady boarder income from a brother","who":"Luis, 40, warehouse manager, Riverside","situation":"Luis's brother has lived with him for two years and pays $900 a month toward rent. Luis earns $66,000. He is buying a $480,000 home and his DTI is just over the limit. His income is under the HomeReady limit for the area (verify).","structure":"HomeReady using boarder income (up to 30% of qualifying income with 12 months shared residency - verify)","numbers":"$5,500 + $900 = $6,400/mo qualifying","why":"Boarder income is a HomeReady feature that recognizes multi-generational and extended-family households. Two years of documented payments meet history. The added income brings DTI within limits.","alternatives":"Add the brother as a co-borrower, which counts all his income but makes him liable. Buy at a lower price around $420,000 without boarder income.","watch":"Payments must be documented (bank transfers or checks). The brother must live in the new home too."},{"t":"Permitted ADU helps qualify","who":"Anh, 45, nurse, Garden Grove","situation":"Anh is buying a $1.1M home with a permitted ADU where her mother will live. Later she may rent the ADU. She earns $140,000. The appraiser can provide a rent estimate for the ADU.","structure":"Conventional with ADU rental income per Fannie Mae rules if eligible (verify)","numbers":"ADU market rent $1,800/mo; usable amount per guideline","why":"Fannie allows certain ADU income on one-unit properties. The ADU gives her mother independence nearby. Future rent adds flexibility.","alternatives":"Qualify without ADU income at a lower price. Buy a duplex with explicit rental income.","watch":"The ADU must be legal and permitted. If her mother lives there rent-free, that income can't count."},{"t":"Siblings co-buy in Phoenix","who":"Maya, 30, and Raj, 33, siblings, Phoenix","situation":"Maya and Raj each can't afford a home alone. Together they earn $150,000. They want a $500,000 home with two primary suites. Both will live there.","structure":"Conventional with both as occupying co-borrowers","numbers":"5-10% down","why":"Pooling income makes ownership possible. Both occupy, so primary-residence pricing applies. A co-ownership agreement protects each sibling.","alternatives":"Each buys a smaller condo. FHA if credit is weaker.","watch":"An exit plan is needed if one sibling marries or moves. Both are fully liable for the whole loan."},{"t":"Chicago two-flat with parents upstairs","who":"Carmen, 42, Chicago","situation":"Carmen buys a two-flat; her parents live upstairs and pay rent. She lives downstairs. She has 3.5% down.","structure":"FHA 2-unit owner-occupied","numbers":"Price $480,000","why":"Rental income from the upper unit counts. FHA allows low down payment on 2-units. Parents stay close.","alternatives":"Single-family home with in-law suite. Conventional 2-unit.","watch":"Rent from her parents must be documented with a lease. FHA 2-unit rental income rules apply."}],"qa":[{"q":"Can my parents' income help us qualify?","a":"Yes if they're borrowers on the loan. If they won't live there, non-occupant co-borrower rules apply, and FHA allows family members at higher LTVs (verify)."},{"q":"What is boarder income?","a":"Rent paid by someone who lives in your home, like a relative. Under HomeReady it can count up to 30% of qualifying income with 12 months of shared-residency history (verify)."},{"q":"Does rent from an ADU count?","a":"Fannie Mae allows ADU rental income on eligible one-unit properties under specific conditions (verify). The ADU must be legal and the rent supported by the appraiser."},{"q":"How should we hold title?","a":"Joint tenancy, tenancy in common or a trust each work differently for inheritance and ownership shares. An attorney should advise based on your family's goals."},{"q":"What if we disagree later or someone wants out?","a":"A written co-ownership agreement covering contributions, expenses and exit terms helps prevent disputes. Decide this before closing."},{"q":"Can friends or siblings buy together?","a":"Yes, as co-borrowers. Each is fully liable for the whole loan."},{"q":"Do household members' incomes count against HomeReady limits?","a":"Generally only borrower income counts toward HomeReady income limits (verify). Non-borrower household members don't push you over."},{"q":"Can we buy a duplex so parents have their own unit?","a":"Yes. Owner-occupied 2-4 unit purchases allow rent from the other unit to help qualify under program rules."},{"q":"Can a caregiver live with us?","a":"Yes. Household makeup doesn't affect eligibility, and familial status is protected under fair housing law."}],"aeQuestions":["Boarder income policy?","ADU income rules?","Non-occupant co-borrower overlays?","2-4 unit rental income?","Title vesting options?","HomeReady income limits?","Turn times?","Broker comp plan (no term-based comp)?"],"redFlags":["Unpermitted ADU","No co-ownership agreement","Undocumented boarder rent","Occupancy confusion","Elder financial exploitation risk","Unequal contributions without documentation"],"pricing":"Pooling assets can lower LTV and improve pricing, while adding co-borrowers may change which credit score drives pricing. Compare structures: all co-borrowers vs non-occupant co-borrower vs 2-4 unit purchase. Show the effect of ADU or boarder income on loan amount without overstating it. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons.","marketing":["Senior centers","ADU builders","Immigrant multigenerational communities","Estate planners","Content on co-buying"],"checklist":["Co-ownership agreement","Income docs for all borrowers","Shared residency proof (boarder)","ADU permits","Appraisal with rent schedule","Title vesting instructions","Credit","Assets","Occupancy certifications","Insurance"],"updated":"2026-11"},
"d_hybrid_income":{"matrix":[["Agency W-2","Standard documentation"],["Agency secondary SE","2-year history; 12-24 months with AUS (verify)"],["Losses","Must be deducted"],["Omitting side income","Possible if not needed and no loss (verify)"],["Non-QM mixed-doc","W-2 + bank statements (lender-specific)"],["Expense factor","30-50% (lender-specific)"],["DTI","Agency 50% max; non-QM 50-55% (lender-specific)"],["FICO","Non-QM often 660+ (lender-specific)"]],"walkthrough":["List every income stream separately: W-2 job(s), Schedule C, K-1, 1099 and rental, with start dates","Get two years of personal returns and confirm whether any side activity shows a loss","Calculate W-2 income from paystubs, W-2s and WVOE as for any employee","Calculate side self-employment income on the lender's worksheet, adding back depreciation and business use of home","Run the file both ways: W-2 only (with any losses deducted) and W-2 plus side income","If the side business is under 2 years, check whether AUS accepts 12-24 months with same-field history (verify)","If tax returns understate the side income, price a non-QM mixed-doc option with 12-24 months of bank statements for that portion (lender-specific)","Confirm the mixed-doc lender allows combining full-doc and alternative-doc income; many don't","Separate business and personal deposits for any bank-statement analysis","Obtain CPA letter or business verification if the side income is used","Pre-approve with the chosen documentation path and close"],"incomeExample":{"title":"Illustrative hybrid","steps":["W-2 $110,000 = $9,167/mo","Schedule C 2-year avg $28,000 = $2,333/mo","Total $11,500/mo","PITI $4,200 + debts $500 = DTI 40.9%"],"result":"Illustrative."},"scenarios":[{"t":"Staff nurse with per-diem 1099 shifts","who":"Tasha, 38, RN, Temecula","situation":"Tasha works full time at a hospital earning $110,000 on W-2. For three years she has also picked up per-diem shifts at a surgery center paid on 1099. Her Schedule C nets $28,000 after modest expenses. She wants a $720,000 home with 10% down.","structure":"Conventional counting W-2 plus 2-year averaged Schedule C income","numbers":"$9,167 + $2,333 = $11,500/mo; PITI ~ $4,900; DTI ~ 47% with car (illustrative)","why":"She has more than two years of the same per-diem work, so agency underwriting can count it. Her expenses are modest, so tax-return income reflects reality. Agency pricing beats any non-QM alternative.","alternatives":"Qualify on W-2 alone at a lower price around $600,000, avoiding self-employment documentation. A high-balance conforming loan may be needed if the loan exceeds the baseline limit in Riverside County (verify).","watch":"If 2026 per-diem income is down, the lower figure may be used. Mileage and license expenses must be reviewed for add-backs."},{"t":"Engineer whose side consulting shows a loss","who":"Mark, 42, aerospace engineer, San Diego","situation":"Mark earns $160,000 on W-2. He started a drone-consulting LLC two years ago that shows an $8,000 loss each year from equipment purchases. He doesn't need the consulting income to qualify. He assumed the side business wouldn't matter.","structure":"Conventional using W-2 income minus the Schedule C loss","numbers":"$13,333 - $667 = $12,666/mo qualifying","why":"Agency rules require deducting self-employment losses even when that income isn't used. The reduction is small relative to his salary. Being upfront avoids an underwriting surprise late in the process.","alternatives":"Adding back the equipment depreciation may shrink the loss on the lender's worksheet. Closing the business won't erase the past returns, so it doesn't help this loan.","watch":"Depreciation add-backs depend on the return details; get both years' Schedule C and Form 4562."},{"t":"Teacher with an 18-month tutoring business","who":"Elena, 35, high school teacher, Phoenix","situation":"Elena earns $58,000 teaching. She started an SAT tutoring business 18 months ago that netted $15,000 last year. She taught test prep part time as a W-2 employee for 3 years before. She wants $15,000 more qualifying income to reach a $400,000 home.","structure":"Conventional or FHA counting tutoring income if AUS accepts the shorter history with related experience (verify)","numbers":"$4,833 + $1,250 = $6,083/mo","why":"Related prior tutoring employment can support a shorter self-employment history. Her teaching income is stable and long-tenured. The side income bridges a modest gap rather than carrying the loan.","alternatives":"Arizona Home Plus DPA could reduce the needed loan amount (verify income cap). Waiting one more tax year removes the history question.","watch":"Summer tutoring revenue concentrates in a few months; the lender uses the annual return, not monthly deposits."},{"t":"Sales manager with e-commerce write-offs","who":"Darnell, 45, sales manager and online store owner, Las Vegas","situation":"Darnell earns $90,000 on W-2 managing a dealership team. His four-year-old e-commerce store deposits about $10,000 a month, but heavy write-offs leave $9,000 of taxable profit. He wants a $600,000 home. Agency math using tax returns falls short.","structure":"Non-QM mixed-doc: W-2 full documentation plus 12-month business bank statements for the store (lender-specific)","numbers":"Bank statements $120,000/yr x 50% expense factor = $60,000; total ~ $150,000/yr","why":"Bank statements reflect the store's real cash flow. Combining it with documented W-2 income keeps the file stronger than a pure bank-statement loan. Not every lender permits mixing, so the lender choice matters.","alternatives":"Agency using W-2 alone at a lower price near $420,000. A CPA-prepared P&L program may support a lower expense factor than 50%.","watch":"Business and personal deposits must be separated. Non-QM pricing and possible prepayment terms must be disclosed and compared."},{"t":"W-2 spouse and self-employed spouse","who":"Ken, 44, and Sue, 42, Chicago suburbs","situation":"Ken is a W-2 project manager earning $120,000. Sue has run a bookkeeping practice for four years, netting $80,000 last year and $72,000 the year before. They want a $650,000 home. Both have strong credit.","structure":"Conventional full documentation for both incomes","numbers":"$10,000 + $6,333 (2-year average) = $16,333/mo","why":"Both incomes have long histories. Sue's rising income allows a two-year average. Agency documentation is straightforward and pricing is favorable.","alternatives":"If Sue's current year drops, qualify on Ken's income plus her lower year. A jumbo isn't needed at this price in most Chicago-area counties.","watch":"Sue's business returns are needed if she owns 25% or more of an entity. A YTD P&L may be requested."}],"qa":[{"q":"Can I use both my W-2 salary and my side-business income?","a":"Yes, if the side income has enough history, usually 2 years and sometimes 12-24 months with prior experience in the same field (verify). It must appear on your tax returns for agency loans."},{"q":"What if my side business lost money on my tax return?","a":"The loss must be subtracted from your qualifying income even if you don't use the side income. Depreciation and other non-cash items may reduce the loss on the lender's worksheet."},{"q":"How long do I need the side business?","a":"Usually 2 years for agency loans. A shorter history may work if you did the same type of work before and the AUS approves."},{"q":"Can I leave the side income off my application?","a":"If you don't need it and it doesn't show a loss, the lender may not require it (verify). You can never leave off a loss."},{"q":"What is a mixed-doc or hybrid loan?","a":"A non-QM loan that uses full documentation for your W-2 job and bank statements or 1099s for your self-employment income. It helps when write-offs make your tax returns understate the side income. Not every lender allows mixing."},{"q":"Is a mixed-doc loan more expensive?","a":"Yes, non-QM loans generally cost more and may require larger down payments. We compare against agency options first."},{"q":"Do I need a CPA letter?","a":"Some bank-statement programs require a CPA letter confirming the business, ownership or expense ratio. Agency loans may need one only for business verification."},{"q":"Does my spouse's self-employment count the same way?","a":"Yes, a co-borrower's self-employment is documented and calculated the same way."}],"aeQuestions":["Do you allow mixed-doc (W-2 + bank statement)?","Expense factor for SE portion?","Secondary SE history requirements?","Treatment of Schedule C losses?","CPA letter requirements?","Max DTI?","Turn times?","Broker comp plan (no term-based comp)?"],"redFlags":["Schedule C or K-1 loss ignored in the income calculation","Business and personal deposits mixed in the same account","Side business under 12 months being counted","Side income declining year over year","Unfiled current-year return when the lender needs it","Income story changes between application and underwriting","Mixed-doc requested from a lender that doesn't allow combining documentation types","Large one-time side-business deposits treated as recurring"],"pricing":"When tax returns support the side income, agency financing is usually the lowest-cost path. Non-QM mixed-doc programs cost more and may require more down payment, so show the cost difference and whether W-2 income alone qualifies. Explain how deducting a side-business loss can change buying power. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons.","marketing":["CPAs","Nurse staffing agencies","Teacher associations","Freelancer communities","Content on side-business income"],"checklist":["Paystubs","W-2s","Tax returns","1099s","Bank statements","CPA letter","Business license","Credit","Appraisal","Assets"],"updated":"2026-11"},
"d_tribal_land":{"matrix":[["Security","Leasehold interest approved by BIA or tribe under HEARTH Act (verify)"],["TSR","Required from BIA LTRO"],["USDA 502","Possible with approved lease (verify)"],["VA NADL","Native veterans on trust land"],["Conventional","Lender-specific leasehold (verify)"],["Lease term","Typically exceeds loan term (verify)"],["Tribal consent","Often required"],["Jurisdiction","Tribal court ordinances affect lender appetite"]],"walkthrough":["Confirm land status: tribal trust, individual allotment, restricted fee, or fee simple","Meet tribal housing department to understand leasing ordinance and consent process","Obtain or apply for residential lease (BIA-approved or HEARTH Act tribal approval)","Request the Title Status Report from the BIA Land Titles and Records Office","Compare Section 184, VA NADL (veterans), USDA 502 and conventional leasehold","Collect borrower income, credit and asset documentation","Order appraisal and construction documents if building","Confirm lease term exceeds loan term per program","Obtain tribal resolution/consent to encumber leasehold","Underwrite and clear conditions","Close and record leasehold mortgage with BIA","Coordinate construction draws if applicable"],"incomeExample":{"title":"Illustrative USDA 502 Direct payment-assistance comparison on trust land","steps":["Household income $52,000/yr ($4,333/mo); household of 4 in a USDA low-income area (verify limits)","Home construction cost on leasehold site $300,000","Standard amortized payment at note rate (illustrative) principal and interest ~ $1,900/mo","USDA Direct payment assistance can reduce the effective rate, potentially lowering P&I substantially (verify current program terms)","Add taxes (often minimal on trust land - verify tribal/county treatment) $50 and insurance $150","Compare housing ratio with and without payment assistance against program limits"],"result":"Payment assistance can make a site-built home affordable on trust land for low-income households where a guaranteed loan would not fit. Numbers are illustrative; USDA Direct terms and funding must be verified."},"scenarios":[{"t":"Building on a tribal lease site in San Diego County","who":"Rosa, 41, tribal administrator, North County San Diego reservation","situation":"Rosa is an enrolled member and the tribe has approved a residential lease site for her family. She earns $74,000 and her husband earns $38,000. They want to build a $420,000 home. The tribe has a HEARTH Act-approved leasing ordinance (verify for her tribe).","structure":"Compare Section 184 with USDA Section 502 Guaranteed or a conventional leasehold construction loan","numbers":"Construction $420,000; Section 184 down payment as low as 2.25% (verify) vs USDA 0%","why":"Both programs are designed to lend on approved leaseholds. HEARTH Act approval can shorten lease timelines. Comparing guarantee fees and down payment shows which program costs less overall.","alternatives":"Tribal housing authority down payment assistance could stack with Section 184. Buying off-reservation in Valley Center would be faster but forgo the family's land.","watch":"The Title Status Report must be current. The lease term must exceed the loan term by the program's required margin (verify)."},{"t":"Native veteran builds on the Navajo Nation","who":"James, 52, Navy veteran and enrolled member, Navajo Nation (AZ)","situation":"James retired from the Navy after 20 years and receives retirement pay plus VA disability. He has a homesite lease from the Navajo Nation. He wants to build a modest home near family in Arizona. Few private lenders work in his area.","structure":"VA Native American Direct Loan (NADL) on the homesite lease","numbers":"Construction ~ $300,000; $0 down; funding fee waived with disability compensation (verify)","why":"NADL is a direct VA loan for Native veterans on trust land. The tribe has a memorandum of understanding with VA (verify). His disability exemption removes the funding fee.","alternatives":"Section 184 if NADL timelines are too long. Tribal housing programs may supplement construction costs.","watch":"Infrastructure (water, power, road access) can delay construction. Homesite lease approval timing drives everything."},{"t":"Non-member spouse in a Paiute colony","who":"Lisa, 35, nurse, northern Nevada Paiute colony","situation":"Lisa is not enrolled, but her husband is. The family lives on colony trust land and wants to buy an existing home there from another member. The tribe's rules decide who may hold a residential lease. Her income is the larger of the two.","structure":"Leasehold mortgage with the member spouse as lessee and both as borrowers if tribal law allows (verify)","numbers":"Purchase $250,000; Section 184 or USDA","why":"Including Lisa's income is essential to qualify. Tribal law on non-member leaseholders controls structure. Working with tribal housing staff early prevents a failed closing.","alternatives":"Qualify on the husband's income with a lower price. Buy fee land just outside the colony if tribal rules don't allow joint lease.","watch":"Tribal consent to the leasehold mortgage and any lease assignment must be in writing."},{"t":"Conventional leasehold for a tribal employee","who":"Mark, 40, tribal enterprise manager, South Florida","situation":"Mark works for a tribal enterprise and wants to buy a home on tribal land. He has 20% down and strong credit. He would prefer to avoid mortgage insurance and guarantee fees. Few conventional lenders lend on tribal leaseholds.","structure":"Conventional leasehold loan with a lender familiar with tribal land (lender-specific)","numbers":"Purchase $350,000; 20% down","why":"With 20% down a conventional loan may avoid guarantee fees altogether. A lender experienced with tribal leaseholds understands jurisdiction and title. It can be cheaper if available.","alternatives":"Section 184 is more widely available on tribal land and allows low down payments. A tribal credit union or Native CDFI may hold the loan in portfolio.","watch":"Fannie leasehold eligibility and tribal foreclosure ordinances must satisfy the investor (verify)."},{"t":"Low-income family needs payment assistance","who":"Ana, 33, school aide, Tohono O'odham Nation (AZ)","situation":"Ana and her partner earn $52,000 combined with three children. They have a homesite lease. Standard loan payments would exceed their budget. They have very little savings.","structure":"USDA Section 502 Direct with payment assistance (verify availability on trust land and funding)","numbers":"See income example; $0 down","why":"Direct loans with payment assistance target very-low and low-income households. Payment assistance can bring housing costs within program ratios. Tribal housing staff often help package these applications.","alternatives":"Tribal housing authority rental or lease-to-own programs. Section 184 with tribal down payment assistance if payment fits.","watch":"USDA Direct funding is limited and timelines are long. Income limits and household size must be verified annually."}],"qa":[{"q":"Can I get a mortgage on tribal trust land?","a":"Yes. Because trust land can't be mortgaged in fee, the loan is secured by an approved residential leasehold interest. Several federal programs and some private lenders do this."},{"q":"What is a Title Status Report (TSR)?","a":"The Bureau of Indian Affairs' official record of ownership and encumbrances on trust land. Lenders need a current TSR to close, and requesting it early avoids delays."},{"q":"What programs exist besides Section 184?","a":"VA's Native American Direct Loan for Native veterans, USDA Section 502 Direct and Guaranteed loans, some conventional leasehold lending, and tribal or Native CDFI programs. Each has different fees, down payments and eligibility."},{"q":"Why does it take longer than a normal mortgage?","a":"Lease approval, tribal consent, the TSR and recording with the BIA add steps. Planning those before locking a rate prevents expensive extensions."},{"q":"Does my tribe need to approve the loan?","a":"The tribe usually approves the residential lease and may need to consent to the leasehold mortgage. Tribes with HEARTH Act-approved regulations can approve leases themselves."},{"q":"What is the HEARTH Act?","a":"A 2012 federal law that lets tribes with approved leasing regulations approve residential leases without BIA approval of each lease. It can shorten timelines significantly."},{"q":"Can a spouse who isn't a tribal member be on the loan?","a":"It depends on tribal law and the program. We confirm with tribal housing staff before structuring the application."},{"q":"How are homes appraised on trust land?","a":"Comparable sales are often limited, so appraisers may use a wider area or the cost approach. Expect the appraisal to take longer."},{"q":"Is property tax charged on trust land?","a":"Trust land is generally exempt from state property tax, but improvements, tribal fees or leasehold taxes may apply (verify for your tribe and county)."}],"aeQuestions":["Do you lend on tribal trust land?","Lease term requirements?","TSR handling?","USDA 502 on trust land?","Conventional leasehold eligibility?","Tribal agreements in place?","Turn times?","Broker comp plan (no term-based comp)?"],"redFlags":["Residential lease not yet approved or recorded","TSR outdated or showing unresolved encumbrances","Fractionated ownership requiring many heirs' consent","Lease term shorter than the loan term plus required margin","No written tribal consent to encumber the leasehold","Parcel mixes fee and trust land","Construction site lacks utilities or legal access","Borrower steered to a higher-cost loan when Section 184, NADL or USDA fits"],"pricing":"Section 184, VA NADL, USDA and conventional leasehold loans have very different fee and mortgage-insurance structures. Compare total costs and cash to close, including guarantee or funding fees. Plan lock periods around TSR and lease approval timelines. Avoid steering toward higher-cost options when a lower-cost program fits. Broker compensation never drives lender or program choice: originator pay cannot vary with loan terms, and steering to a loan because it pays more is prohibited (12 CFR 1026.36(d)/(e)). Provide written comparisons.","marketing":["Tribal housing authorities","Native CDFIs","Native veteran groups","Tribal employer HR","Content on trust land lending"],"checklist":["Approved lease","TSR","Tribal resolution","Enrollment certificate","Income docs","Credit","Appraisal","Construction plans","Insurance","Environmental review"],"updated":"2026-11"}
});
